(372121,41347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... помаранчеву пачку високо над головою.'::text,'тримає'::text,'тримається'::text,'тримаючи'::text,'Він тримає помаранчеву пачку високо над головою.'::text),
(372120,41347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la bolsa naranja muy por encima de su cabeza.'::text,'sostiene'::text,'es sostenido'::text,'sosteniendo'::text,'Él sostiene la bolsa naranja muy por encima de su cabeza.'::text),
(372119,41347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le paquet orange bien au-dessus de sa tête.'::text,'tient'::text,'est tenu'::text,'tenant'::text,'Il tient le paquet orange bien au-dessus de sa tête.'::text),
(372122,41347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, turuncu paketi başının çok üstünde ...'::text,'tutuyor'::text,'tutuluyor'::text,'tutarak'::text,'O, turuncu paketi başının çok üstünde tutuyor.'::text),
