(372132,41348,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kergeti őt, szóval ... nagyon akarja azt a zacskó chipset.'::text,'biztosan'::text,'talán'::text,'biztosan nem'::text,'Kergeti őt, szóval biztosan nagyon akarja azt a zacskó chipset.'::text),
(372135,41349,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mädchen, ... die Tüte nahm, setzte sich aufs Sofa.'::text,'das'::text,'welches'::text,'dessen'::text,'Das Mädchen, das die Tüte nahm, setzte sich aufs Sofa.'::text),
(372139,41349,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчина, ... взяла пачку, сіла на диван.'::text,'яка'::text,'котра'::text,'чия'::text,'Дівчина, яка взяла пачку, сіла на диван.'::text),
