(372146,41350,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il lui a dit que le paquet ... hors de sa portée pour toujours.'::text,'resterait'::text,'restera'::text,'reste'::text,'Il lui a dit que le paquet resterait hors de sa portée pour toujours.'::text),
