(372155,41351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... toujours le dernier paquet de chips quand ils étaient petits.'::text,'cachait'::text,'cachait'::text,'avait l''habitude de cacher'::text,'Meuf, apparemment il cachait toujours le dernier paquet de chips quand ils étaient petits.'::text),
(372158,41351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o çocukken hep son cips paketini ... diyorlar.'::text,'saklarmış'::text,'saklarmış'::text,'saklamaya alışkınmış'::text,'Kızım, o çocukken hep son cips paketini saklarmış diyorlar.'::text),
(372159,41351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag gyerekkorukban mindig ő ... az utolsó zacskó chipset.'::text,'rejtette el'::text,'rejtette el'::text,'volt hozzászokva, hogy elrejtse'::text,'Csajszi, állítólag gyerekkorukban mindig ő rejtette el az utolsó zacskó chipset.'::text),
(372171,41353,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich hat er zuerst die halbe Tüte gegessen, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Bestie, angeblich hat er zuerst die halbe Tüte gegessen, oder?'::text),
(372175,41353,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він спершу з''їв пів пачки, ...?'::text,'так'::text,'так'::text,'так'::text,'Подруго, кажуть, він спершу з''їв пів пачки, так?'::text),
(372174,41353,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, al parecer él se comió primero media bolsa, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Bestie, al parecer él se comió primero media bolsa, ¿verdad?'::text),
