(372177,41353,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, állítólag először ő ette meg a zacskó felét, ...?'::text,'nem igaz'::text,'ugye'::text,'ugye'::text,'Tesó, állítólag először ő ette meg a zacskó felét, nem igaz?'::text),
(372180,41354,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat nicht erwartet, dass du dir die Tüte schnappst, und ehrlich gesagt, ich ...! Respekt.'::text,'auch nicht'::text,'auch'::text,'auch nicht'::text,'Er hat nicht erwartet, dass du dir die Tüte schnappst, und ehrlich gesagt, ich auch nicht! Respekt.'::text),
(372184,41354,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не очікував, що ти схопиш ту пачку, і чесно, я ...! Респект.'::text,'теж ні'::text,'теж'::text,'теж ні'::text,'Він не очікував, що ти схопиш ту пачку, і чесно, я теж ні! Респект.'::text),
