(372182,41354,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne s''attendait pas à ce que tu attrapes ce paquet, et franchement, moi ... ! Respect.'::text,'non plus'::text,'aussi'::text,'non plus'::text,'Il ne s''attendait pas à ce que tu attrapes ce paquet, et franchement, moi non plus ! Respect.'::text),
(372185,41354,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senin o paketi kapacağını beklemiyordu, ve açıkçası ben ...! Saygılar.'::text,'de beklemiyordum'::text,'de bekliyordum'::text,'de beklemiyordum'::text,'Senin o paketi kapacağını beklemiyordu, ve açıkçası ben de beklemiyordum! Saygılar.'::text),
(372186,41354,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem számított rá, hogy elkapod azt a zacskót, és őszintén, én ...! Respekt.'::text,'sem'::text,'is'::text,'sem'::text,'Nem számított rá, hogy elkapod azt a zacskót, és őszintén, én sem! Respekt.'::text),
(372198,41356,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Plan, natürlich: Bis zum Ende des Films wird sie die ganze Tüte ...'::text,'aufgegessen haben'::text,'essen'::text,'am Essen sein'::text,'Toller Plan, natürlich: Bis zum Ende des Films wird sie die ganze Tüte aufgegessen haben.'::text),
(372202,41356,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий план, звісно: до кінця фільму вона ... всю пачку.'::text,'вже з''їсть'::text,'з''їсть'::text,'їстиме'::text,'Чудовий план, звісно: до кінця фільму вона вже з''їсть всю пачку.'::text),
(372201,41356,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran plan, obviamente: para el final de la peli, ella ... toda la bolsa.'::text,'se habrá comido'::text,'se comerá'::text,'estará comiendo'::text,'Gran plan, obviamente: para el final de la peli, ella se habrá comido toda la bolsa.'::text),
(372200,41356,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super plan, évidemment : d''ici la fin du film, elle ... tout le paquet.'::text,'aura mangé'::text,'mangera'::text,'sera en train de manger'::text,'Super plan, évidemment : d''ici la fin du film, elle aura mangé tout le paquet.'::text),
(372203,41356,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika plan, tabii: film bitene kadar o bütün paketi ...'::text,'bitirmiş olacak'::text,'yiyecek'::text,'yiyor olacak'::text,'Harika plan, tabii: film bitene kadar o bütün paketi bitirmiş olacak.'::text),
(372204,41356,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek terv, persze: a film végére ő ... az egész zacskót.'::text,'megeszi'::text,'megeszi'::text,'enni fogja'::text,'Remek terv, persze: a film végére ő megeszi az egész zacskót.'::text),
(348357,38707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... ihr wie ein Profi, als sie sich endlich die Snacks schnappte, kein Witz.'::text,'entwischte gerade'::text,'entwischte'::text,'ist entwischt'::text,'Bro, er entwischte gerade ihr wie ein Profi, als sie sich endlich die Snacks schnappte, kein Witz.'::text),
(348361,38707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... від неї як профі, коли вона нарешті схопила снеки, без брехні.'::text,'ухилявся'::text,'ухилився'::text,'ухилився'::text,'Бро, він ухилявся від неї як профі, коли вона нарешті схопила снеки, без брехні.'::text),
(348360,38707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él la ... como un pro cuando ella por fin agarró los snacks, en serio.'::text,'estaba esquivando'::text,'esquivó'::text,'ha esquivado'::text,'Bro, él la estaba esquivando como un pro cuando ella por fin agarró los snacks, en serio.'::text),
(348359,38707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... comme un pro quand elle a enfin attrapé les snacks, sans mentir.'::text,'l''esquivait'::text,'l''a esquivée'::text,'l''a esquivée'::text,'Frérot, il l''esquivait comme un pro quand elle a enfin attrapé les snacks, sans mentir.'::text),
(348362,38707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sonunda atıştırmalıkları kaptığında o ondan bir profesyonel gibi ..., yemin ederim.'::text,'kaçıyordu'::text,'kaçtı'::text,'kaçmış'::text,'Kanka, sonunda atıştırmalıkları kaptığında o ondan bir profesyonel gibi kaçıyordu, yemin ederim.'::text),
(348363,38707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, profi módon ... a csajt, amikor az végre elkapta a nasit, komolyan.'::text,'cselezgette'::text,'kicselezte'::text,'kicselezte'::text,'Tesó, profi módon cselezgette a csajt, amikor az végre elkapta a nasit, komolyan.'::text),
(348366,38708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... ihren Händen seit zwei Minuten, und sie hat die Tüte immer noch nicht.'::text,'entwischt'::text,'entwischt'::text,'entwischt'::text,'Er entwischt ihren Händen seit zwei Minuten, und sie hat die Tüte immer noch nicht.'::text),
(348370,38708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... від її рук уже дві хвилини, а пачки в неї досі немає.'::text,'ухиляється'::text,'ухиляється'::text,'ухиляється'::text,'Він ухиляється від її рук уже дві хвилини, а пачки в неї досі немає.'::text),
(348369,38708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... sus manos desde hace dos minutos, y ella sigue sin tener la bolsa.'::text,'esquiva'::text,'está esquivando'::text,'esquiva'::text,'Él esquiva sus manos desde hace dos minutos, y ella sigue sin tener la bolsa.'::text),
