(348379,38709,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... до пачки, коли він відскочив убік по килиму.'::text,'тягнулася'::text,'потягнулася'::text,'потягнулася'::text,'Вона тягнулася до пачки, коли він відскочив убік по килиму.'::text),
(348378,38709,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... hacia la bolsa cuando él esquivó de lado por la alfombra.'::text,'estiraba la mano'::text,'estiró la mano'::text,'ha estirado la mano'::text,'Ella estiraba la mano hacia la bolsa cuando él esquivó de lado por la alfombra.'::text),
(348377,38709,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... vers le paquet quand il a esquivé sur le côté à travers le tapis.'::text,'tendait la main'::text,'a tendu la main'::text,'a tendu la main'::text,'Elle tendait la main vers le paquet quand il a esquivé sur le côté à travers le tapis.'::text),
(348380,38709,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O halının üstünde yana kaçtığında kız pakete ...'::text,'uzanıyordu'::text,'uzandı'::text,'uzanmış'::text,'O halının üstünde yana kaçtığında kız pakete uzanıyordu.'::text),
(348381,38709,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lány éppen ... a zacskó után, amikor a srác oldalra ugrott a szőnyegen.'::text,'nyúlt'::text,'nyúlt'::text,'nyúlt'::text,'A lány éppen nyúlt a zacskó után, amikor a srác oldalra ugrott a szőnyegen.'::text),
(348384,38710,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist ihr bisher fünfmal ..., aber sie kommt immer näher.'::text,'ausgewichen'::text,'ausgewichen'::text,'ausgewichen'::text,'Er ist ihr bisher fünfmal ausgewichen, aber sie kommt immer näher.'::text),
(348388,38710,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... від неї вже п''ять разів, але вона підбирається ближче.'::text,'ухилився'::text,'ухилявся'::text,'ухилився'::text,'Він ухилився від неї вже п''ять разів, але вона підбирається ближче.'::text),
(348387,38710,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él la ... cinco veces hasta ahora, pero ella se está acercando.'::text,'ha esquivado'::text,'ha estado esquivando'::text,'esquivó'::text,'Él la ha esquivado cinco veces hasta ahora, pero ella se está acercando.'::text),
(348386,38710,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... cinq fois jusqu''ici, mais elle se rapproche.'::text,'l''a esquivée'::text,'l''esquive'::text,'l''a esquivée'::text,'Il l''a esquivée cinq fois jusqu''ici, mais elle se rapproche.'::text),
(348389,38710,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar ondan beş kez ..., ama kız giderek yaklaşıyor.'::text,'kaçtı'::text,'kaçıyor'::text,'kaçtı'::text,'Şimdiye kadar ondan beş kez kaçtı, ama kız giderek yaklaşıyor.'::text),
(348390,38710,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig ötször ... a lányt, de ő egyre közelebb kerül.'::text,'cselezte ki'::text,'cselezgette'::text,'kicselezte'::text,'Eddig ötször cselezte ki a lányt, de ő egyre közelebb kerül.'::text),
(348393,38711,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, also angeblich ... sie alle anderen Snacks schon gegessen, bevor er anfing, ihr auszuweichen.'::text,'hatte'::text,'hat'::text,'isst'::text,'Ok, also angeblich hatte sie alle anderen Snacks schon gegessen, bevor er anfing, ihr auszuweichen.'::text),
(348397,38711,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, кажуть, вона ... всі інші снеки ще до того, як він почав від неї ухилятися.'::text,'з''їла'::text,'з''їла'::text,'їсть'::text,'Окей, кажуть, вона з''їла всі інші снеки ще до того, як він почав від неї ухилятися.'::text),
(348396,38711,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, pues al parecer ella ... todos los demás snacks antes de que él empezara a esquivarla.'::text,'se había comido'::text,'se ha comido'::text,'se come'::text,'Ok, pues al parecer ella se había comido todos los demás snacks antes de que él empezara a esquivarla.'::text),
(348395,38711,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok alors apparemment elle ... tous les autres snacks avant qu''il commence à l''esquiver.'::text,'avait mangé'::text,'a mangé'::text,'mange'::text,'Ok alors apparemment elle avait mangé tous les autres snacks avant qu''il commence à l''esquiver.'::text),
(348398,38711,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre o, adam ondan kaçmaya başlamadan önce diğer bütün atıştırmalıkları ...'::text,'yemişti'::text,'yemiş'::text,'yiyor'::text,'Tamam, duyduğuma göre o, adam ondan kaçmaya başlamadan önce diğer bütün atıştırmalıkları yemişti.'::text),
(348399,38711,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag ő már ... az összes többi nasit, mielőtt a srác elkezdett kitérni előle.'::text,'megette'::text,'megette'::text,'eszi'::text,'Oké, szóval állítólag ő már megette az összes többi nasit, mielőtt a srác elkezdett kitérni előle.'::text),
(348402,38712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er ihr noch einmal ausweicht, ... sie ihn am Sofa in die Enge.'::text,'treibt'::text,'würde treiben'::text,'trieb'::text,'Wenn er ihr noch einmal ausweicht, treibt sie ihn am Sofa in die Enge.'::text),
(348406,38712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він ухилиться ще раз, вона ... його біля дивана.'::text,'зажене в кут'::text,'загнала б у кут'::text,'загнала в кут'::text,'Якщо він ухилиться ще раз, вона зажене в кут його біля дивана.'::text),
(348405,38712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la esquiva una vez más, ella lo ... junto al sofá.'::text,'acorralará'::text,'acorralaría'::text,'acorraló'::text,'Si la esquiva una vez más, ella lo acorralará junto al sofá.'::text),
(348404,38712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il l''esquive encore une fois, elle le ... près du canapé.'::text,'coincera'::text,'coincerait'::text,'coinça'::text,'S''il l''esquive encore une fois, elle le coincera près du canapé.'::text),
(348407,38712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ondan bir kez daha kaçarsa, kız onu kanepenin yanında ...'::text,'köşeye sıkıştıracak'::text,'köşeye sıkıştırırdı'::text,'köşeye sıkıştırdı'::text,'Ondan bir kez daha kaçarsa, kız onu kanepenin yanında köşeye sıkıştıracak.'::text),
(348408,38712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egyszer kitér előle, a lány ... a kanapénál.'::text,'sarokba szorítja'::text,'sarokba szorítaná'::text,'sarokba szorította'::text,'Ha még egyszer kitér előle, a lány sarokba szorítja a kanapénál.'::text),
(348411,38713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeder ihrer Griffe ... von dem jungen Mann ausgetrickst, bis sie ihn endlich in die Enge trieb.'::text,'wurde'::text,'trickste'::text,'wird'::text,'Jeder ihrer Griffe wurde von dem jungen Mann ausgetrickst, bis sie ihn endlich in die Enge trieb.'::text),
(348415,38713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Від кожної її спроби схопити молодий хлопець ..., поки вона нарешті не загнала його в кут.'::text,'ухилявся'::text,'ухилився'::text,'ухиляється'::text,'Від кожної її спроби схопити молодий хлопець ухилявся, поки вона нарешті не загнала його в кут.'::text),
(348414,38713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada intento ... por el joven hasta que ella por fin lo acorraló.'::text,'fue esquivado'::text,'esquivó'::text,'es esquivado'::text,'Cada intento fue esquivado por el joven hasta que ella por fin lo acorraló.'::text),
(348413,38713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque tentative ... par le jeune homme jusqu''à ce qu''elle le coince enfin.'::text,'était esquivée'::text,'esquivait'::text,'est esquivée'::text,'Chaque tentative était esquivée par le jeune homme jusqu''à ce qu''elle le coince enfin.'::text),
(348416,38713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kapma hamlesi genç adam tarafından ..., ta ki kız sonunda onu köşeye sıkıştırana kadar.'::text,'savuşturuldu'::text,'savuşturdu'::text,'savuşturuluyor'::text,'Her kapma hamlesi genç adam tarafından savuşturuldu, ta ki kız sonunda onu köşeye sıkıştırana kadar.'::text),
(348417,38713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden kapkodását ... a fiatal srác, amíg a lány végül sarokba nem szorította.'::text,'kicselezte'::text,'kicselezte'::text,'kicselezi'::text,'Minden kapkodását kicselezte a fiatal srác, amíg a lány végül sarokba nem szorította.'::text),
(348429,38715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er weicht jedem Griff aus, also ... er nicht vorhaben, zu teilen. Eindeutig ein großzügiger Typ.'::text,'kann'::text,'muss'::text,'sollte'::text,'Er weicht jedem Griff aus, also kann er nicht vorhaben, zu teilen. Eindeutig ein großzügiger Typ.'::text),
(348433,38715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ухиляється від кожного хапання, тож він ... планувати ділитися. Явно щедрий хлопець.'::text,'не може'::text,'мусить'::text,'має'::text,'Він ухиляється від кожного хапання, тож він не може планувати ділитися. Явно щедрий хлопець.'::text),
(348432,38715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esquiva cada intento, así que ... estar pensando en compartir. Claramente un tío generoso.'::text,'no puede'::text,'debe de'::text,'debería'::text,'Esquiva cada intento, así que no puede estar pensando en compartir. Claramente un tío generoso.'::text),
(348431,38715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il esquive chaque tentative, donc il ... avoir l''intention de partager. Clairement un mec généreux.'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'Il esquive chaque tentative, donc il ne peut pas avoir l''intention de partager. Clairement un mec généreux.'::text),
(348434,38715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kapma hamlesinden kaçıyor, yani ... paylaşmayı düşünmüyor. Belli ki cömert biri.'::text,'kesinlikle'::text,'kesin'::text,'herhalde'::text,'Her kapma hamlesinden kaçıyor, yani kesinlikle paylaşmayı düşünmüyor. Belli ki cömert biri.'::text),
(348435,38715,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden kapkodás elől kitér, szóval ... azt tervezi, hogy megosztja. Egyértelműen nagyvonalú srác.'::text,'biztosan nem'::text,'biztosan'::text,'valószínűleg'::text,'Minden kapkodás elől kitér, szóval biztosan nem azt tervezi, hogy megosztja. Egyértelműen nagyvonalú srác.'::text),
(348438,38716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... einer ganzen Minute Ausweichen verlor er die Tüte trotzdem. Makellose Technik.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz einer ganzen Minute Ausweichen verlor er die Tüte trotzdem. Makellose Technik.'::text),
(348442,38716,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... те, що він ухилявся від неї цілу хвилину, він однаково втратив пачку. Бездоганна техніка.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри те, що він ухилявся від неї цілу хвилину, він однаково втратив пачку. Бездоганна техніка.'::text),
(348441,38716,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... esquivarla durante un minuto entero, perdió la bolsa de todos modos. Técnica impecable.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de esquivarla durante un minuto entero, perdió la bolsa de todos modos. Técnica impecable.'::text),
(348440,38716,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... l''avoir esquivée pendant une minute entière, il a quand même perdu le paquet. Technique impeccable.'::text,'Malgré'::text,'Bien que'::text,'En raison de'::text,'Malgré l''avoir esquivée pendant une minute entière, il a quand même perdu le paquet. Technique impeccable.'::text),
(348443,38716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koca bir dakika ondan kaçmasına ..., paketi yine de kaybetti. Kusursuz teknik.'::text,'rağmen'::text,'rağmen'::text,'yüzünden'::text,'Koca bir dakika ondan kaçmasına rağmen, paketi yine de kaybetti. Kusursuz teknik.'::text),
(348444,38716,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... egy teljes percig kitért előle, végül mégis elvesztette a zacskót. Hibátlan technika.'::text,'Annak ellenére, hogy'::text,'Bár'::text,'Mivel'::text,'Annak ellenére, hogy egy teljes percig kitért előle, végül mégis elvesztette a zacskót. Hibátlan technika.'::text),
(391584,43510,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder auf dasselbe Handy.'::text,'starren'::text,'werden starren'::text,'starren'::text,'Morgen um diese Zeit starren sie wieder auf dasselbe Handy.'::text),
(391588,43510,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вони знову ... в той самий телефон.'::text,'витріщатимуться'::text,'витріщаться'::text,'витріщаються'::text,'Завтра в цей час вони знову витріщатимуться в той самий телефон.'::text),
(391587,43510,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, ellos ... otra vez el mismo móvil.'::text,'estarán mirando fijamente'::text,'mirarán fijamente'::text,'miran fijamente'::text,'Mañana a esta hora, ellos estarán mirando fijamente otra vez el mismo móvil.'::text),
(391586,43510,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, ils ... encore le même téléphone.'::text,'seront en train de fixer'::text,'fixeront'::text,'fixent'::text,'Demain à la même heure, ils seront en train de fixer encore le même téléphone.'::text),
(391589,43510,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte yine aynı telefona ...'::text,'bakıyor olacaklar'::text,'bakacaklar'::text,'bakıyorlar'::text,'Yarın bu saatte yine aynı telefona bakıyor olacaklar.'::text),
(391590,43510,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ugyanazt a telefont ...'::text,'fogják bámulni'::text,'bámulják majd'::text,'bámulják'::text,'Holnap ilyenkor megint ugyanazt a telefont fogják bámulni.'::text),
(391593,43511,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'„Ich ... auf den Bildschirm, bis das Video zu Ende ist“, beschließt ein Junge.'::text,'starre'::text,'werde starren'::text,'starre gerade'::text,'„Ich starre auf den Bildschirm, bis das Video zu Ende ist“, beschließt ein Junge.'::text),
(391597,43511,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'«Я ... в екран, доки не скінчиться відео», — вирішує один хлопець.'::text,'дивитимусь'::text,'дивитимусь'::text,'дивлюся'::text,'«Я дивитимусь в екран, доки не скінчиться відео», — вирішує один хлопець.'::text),
(391596,43511,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'«... la pantalla hasta que acabe el vídeo», decide uno de los chicos.'::text,'Miraré'::text,'Estaré mirando'::text,'Estoy mirando'::text,'«Miraré la pantalla hasta que acabe el vídeo», decide uno de los chicos.'::text),
(391595,43511,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'« Je ... l''écran jusqu''à la fin de la vidéo », décide un des garçons.'::text,'fixerai'::text,'serai en train de fixer'::text,'fixe'::text,'« Je fixerai l''écran jusqu''à la fin de la vidéo », décide un des garçons.'::text),
(391598,43511,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'“Video bitene kadar ekrana ...,” diye karar veriyor bir çocuk.'::text,'bakacağım'::text,'bakıyor olacağım'::text,'bakıyorum'::text,'“Video bitene kadar ekrana bakacağım,” diye karar veriyor bir çocuk.'::text),
(391599,43511,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'„Addig ... a képernyőt, amíg véget nem ér a videó” – dönti el az egyik srác.'::text,'bámulom'::text,'fogom bámulni'::text,'bámulom'::text,'„Addig bámulom a képernyőt, amíg véget nem ér a videó” – dönti el az egyik srác.'::text),
(391611,43513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Jahr 2020 ... sie stundenlang auf ein einziges Handy, heißt es im Bericht.'::text,'starrten'::text,'starrten'::text,'waren es gewohnt zu starren'::text,'Im Jahr 2020 starrten sie stundenlang auf ein einziges Handy, heißt es im Bericht.'::text),
(391615,43513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще у 2020-му вони ... годинами дивитися в один телефон, йдеться у звіті.'::text,'могли'::text,'мали звичку'::text,'були звиклі'::text,'Ще у 2020-му вони могли годинами дивитися в один телефон, йдеться у звіті.'::text),
(391614,43513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Allá por 2020, ellos ... un solo móvil durante horas, según el informe.'::text,'miraban'::text,'solían mirar'::text,'estaban acostumbrados a mirar'::text,'Allá por 2020, ellos miraban un solo móvil durante horas, según el informe.'::text),
(391613,43513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En 2020, ils ... un seul téléphone pendant des heures, selon le rapport.'::text,'fixaient'::text,'avaient l''habitude de fixer'::text,'étaient habitués à fixer'::text,'En 2020, ils fixaient un seul téléphone pendant des heures, selon le rapport.'::text),
(391616,43513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapora göre, 2020''de saatlerce tek bir telefona ...'::text,'bakarlardı'::text,'bakarlardı'::text,'bakmaya alışkındılar'::text,'Rapora göre, 2020''de saatlerce tek bir telefona bakarlardı.'::text),
(391617,43513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelentés szerint 2020-ban órákig ... egyetlen telefont.'::text,'bámulták'::text,'bámulták'::text,'hozzá voltak szokva bámulni'::text,'A jelentés szerint 2020-ban órákig bámulták egyetlen telefont.'::text),
(391620,43514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ständig aufs Handy, weil das Handy ja genau da ist.'::text,'starren'::text,'zu starren'::text,'starren'::text,'Sie starren ständig aufs Handy, weil das Handy ja genau da ist.'::text),
(391624,43514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони все ... на телефон, бо телефон просто тут.'::text,'витріщаються'::text,'витріщатися'::text,'витріщаються'::text,'Вони все витріщаються на телефон, бо телефон просто тут.'::text),
(391623,43514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siguen ... el móvil, porque el móvil está justo ahí.'::text,'mirando'::text,'mirar'::text,'miran'::text,'Siguen mirando el móvil, porque el móvil está justo ahí.'::text),
(391622,43514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils n''arrêtent pas de ... le téléphone, parce que le téléphone est juste là.'::text,'fixer'::text,'à fixer'::text,'fixent'::text,'Ils n''arrêtent pas de fixer le téléphone, parce que le téléphone est juste là.'::text),
(391625,43514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefona ... devam ediyorlar, çünkü telefon hemen orada.'::text,'bakmaya'::text,'bakmak'::text,'bakıyorlar'::text,'Telefona bakmaya devam ediyorlar, çünkü telefon hemen orada.'::text),
(391626,43514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Folyton ... a telefont, mert a telefon pont ott van.'::text,'bámulják'::text,'bámulni'::text,'bámulják'::text,'Folyton bámulják a telefont, mert a telefon pont ott van.'::text),
(391629,43515,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie starren auf dasselbe Handy, ...?'::text,'nicht wahr'::text,'oder'::text,'oder etwa'::text,'Sie starren auf dasselbe Handy, nicht wahr?'::text),
(391633,43515,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони дивляться в той самий телефон, ...?'::text,'так'::text,'правда'::text,'хіба ні'::text,'Вони дивляться в той самий телефон, так?'::text),
(391632,43515,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Están mirando el mismo móvil, ¿...?'::text,'verdad'::text,'no'::text,'sí'::text,'Están mirando el mismo móvil, ¿verdad?'::text),
(391631,43515,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils fixent le même téléphone, ... ?'::text,'n''est-ce pas'::text,'non'::text,'hein'::text,'Ils fixent le même téléphone, n''est-ce pas ?'::text),
(391634,43515,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynı telefona bakıyorlar, ...?'::text,'değil mi'::text,'değil mi'::text,'öyle mi'::text,'Aynı telefona bakıyorlar, değil mi?'::text),
(391635,43515,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ugyanazt a telefont bámulják, ...?'::text,'ugye'::text,'nem igaz'::text,'igaz'::text,'Ugyanazt a telefont bámulják, ugye?'::text),
(391638,43516,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Völlig hypnotisiert! Er kann nicht aufhören zu starren, und ...'::text,'seine Freunde auch nicht.'::text,'seine Freunde auch.'::text,'seine Freunde auch nicht.'::text,'Völlig hypnotisiert! Er kann nicht aufhören zu starren, und seine Freunde auch nicht.'::text),
(391642,43516,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повністю загіпнотизований! Він не може перестати витріщатися, і ...'::text,'його друзі теж не можуть.'::text,'його друзі теж можуть.'::text,'його друзі теж ні.'::text,'Повністю загіпнотизований! Він не може перестати витріщатися, і його друзі теж не можуть.'::text),
(391641,43516,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Totalmente hipnotizado! No puede dejar de mirar, y ...'::text,'sus amigos tampoco.'::text,'sus amigos también.'::text,'sus amigos tampoco.'::text,'¡Totalmente hipnotizado! No puede dejar de mirar, y sus amigos tampoco.'::text),
(391640,43516,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Complètement hypnotisé ! Il ne peut pas s''arrêter de fixer, et ...'::text,'ses amis non plus.'::text,'ses amis aussi.'::text,'ses amis non plus.'::text,'Complètement hypnotisé ! Il ne peut pas s''arrêter de fixer, et ses amis non plus.'::text),
(391643,43516,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamamen hipnotize olmuş! Bakmayı bırakamıyor, ve ...'::text,'arkadaşları da bırakamıyor.'::text,'arkadaşları da bırakabiliyor.'::text,'arkadaşları da bırakmıyor.'::text,'Tamamen hipnotize olmuş! Bakmayı bırakamıyor, ve arkadaşları da bırakamıyor.'::text),
(391644,43516,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen hipnotizálva! Nem tudja abbahagyni a bámulást, és ...'::text,'a barátai sem.'::text,'a barátai is.'::text,'a barátai sem.'::text,'Teljesen hipnotizálva! Nem tudja abbahagyni a bámulást, és a barátai sem.'::text),
(391647,43517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mitternacht ... sie sechs Stunden lang auf dieses Handy gestarrt! Ihre Augen sind verloren!'::text,'haben'::text,'werden'::text,'werden'::text,'Bis Mitternacht haben sie sechs Stunden lang auf dieses Handy gestarrt! Ihre Augen sind verloren!'::text),
(391651,43517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі вони ... в той телефон шість годин! Їхні очі приречені!'::text,'витріщатимуться'::text,'витріщатимуться'::text,'витріщатимуться'::text,'До півночі вони витріщатимуться в той телефон шість годин! Їхні очі приречені!'::text),
(391650,43517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para medianoche ... ese móvil durante seis horas! ¡Sus ojos están condenados!'::text,'habrán mirado'::text,'mirarán'::text,'estarán mirando'::text,'¡Para medianoche habrán mirado ese móvil durante seis horas! ¡Sus ojos están condenados!'::text),
(391649,43517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, ils ... ce téléphone pendant six heures ! Leurs yeux sont condamnés !'::text,'auront fixé'::text,'fixeront'::text,'seront en train de fixer'::text,'D''ici minuit, ils auront fixé ce téléphone pendant six heures ! Leurs yeux sont condamnés !'::text),
(391652,43517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar o telefona altı saat ...! Gözlerinin sonu geldi!'::text,'bakmış olacaklar'::text,'bakacaklar'::text,'bakıyor olacaklar'::text,'Gece yarısına kadar o telefona altı saat bakmış olacaklar! Gözlerinin sonu geldi!'::text),
(391653,43517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélig hat órán át ... azt a telefont! A szemük menthetetlen!'::text,'fogják bámulni'::text,'bámulják majd'::text,'fogják bámulni'::text,'Éjfélig hat órán át fogják bámulni azt a telefont! A szemük menthetetlen!'::text),
(391656,43518,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er ihnen das Video nicht gezeigt, ... sie in den Sonnenuntergang gestarrt! Eine Tragödie!'::text,'hätten'::text,'werden'::text,'haben'::text,'Hätte er ihnen das Video nicht gezeigt, hätten sie in den Sonnenuntergang gestarrt! Eine Tragödie!'::text),
(391660,43518,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не показав їм відео, вони ... на захід сонця! Трагедія!'::text,'дивилися б'::text,'дивитимуться'::text,'дивилися'::text,'Якби він не показав їм відео, вони дивилися б на захід сонця! Трагедія!'::text),
(391659,43518,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no les hubiera enseñado el vídeo, ... la puesta de sol! ¡Una tragedia!'::text,'habrían mirado'::text,'mirarán'::text,'miraron'::text,'¡Si no les hubiera enseñado el vídeo, habrían mirado la puesta de sol! ¡Una tragedia!'::text),
(391658,43518,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ne leur avait pas montré la vidéo, ils ... le coucher de soleil ! Une tragédie !'::text,'auraient regardé'::text,'regarderont'::text,'regardaient'::text,'S''il ne leur avait pas montré la vidéo, ils auraient regardé le coucher de soleil ! Une tragédie !'::text),
(391661,43518,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlara videoyu göstermeseydi, gün batımına ...! Tam bir trajedi!'::text,'bakarlardı'::text,'bakacaklar'::text,'baktılar'::text,'Onlara videoyu göstermeseydi, gün batımına bakarlardı! Tam bir trajedi!'::text),
(391662,43518,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem mutatta volna meg nekik a videót, a naplementét ...! Micsoda tragédia!'::text,'bámulták volna'::text,'bámulják majd'::text,'bámulták'::text,'Ha nem mutatta volna meg nekik a videót, a naplementét bámulták volna! Micsoda tragédia!'::text),
(391674,43520,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine Minute lang aufs Handy, bevor alle anfingen zu lachen.'::text,'starrten'::text,'starren'::text,'starren'::text,'Sie starrten eine Minute lang aufs Handy, bevor alle anfingen zu lachen.'::text),
(391678,43520,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... в телефон хвилину, перш ніж усі почали сміятися.'::text,'дивилися'::text,'дивляться'::text,'дивляться'::text,'Вони дивилися в телефон хвилину, перш ніж усі почали сміятися.'::text),
(391677,43520,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... el móvil durante un minuto antes de que todos empezaran a reírse.'::text,'habían estado mirando'::text,'han estado mirando'::text,'están mirando'::text,'Ellos habían estado mirando el móvil durante un minuto antes de que todos empezaran a reírse.'::text),
(391676,43520,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le téléphone pendant une minute avant que tout le monde se mette à rire.'::text,'avaient fixé'::text,'ont fixé'::text,'fixent'::text,'Ils avaient fixé le téléphone pendant une minute avant que tout le monde se mette à rire.'::text),
(391679,43520,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hepsi gülmeye başlamadan önce bir dakika telefona ...'::text,'bakıyorlardı'::text,'bakıyorlar'::text,'bakıyorlar'::text,'Hepsi gülmeye başlamadan önce bir dakika telefona bakıyorlardı.'::text),
(391680,43520,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy percig ... a telefont, mielőtt mind nevetni kezdtek.'::text,'bámulták'::text,'bámulják'::text,'bámulják'::text,'Egy percig bámulták a telefont, mielőtt mind nevetni kezdtek.'::text),
(396264,44030,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... voller Entsetzen den Gang entlang, als ein Zombiekopf aufleuchtete.'::text,'gingen gerade'::text,'gingen'::text,'sind gegangen'::text,'Sie gingen gerade voller Entsetzen den Gang entlang, als ein Zombiekopf aufleuchtete.'::text),
(396268,44030,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... коридором у жаху, коли засвітилася голова зомбі.'::text,'йшли'::text,'пройшли'::text,'пройшли'::text,'Вони йшли коридором у жаху, коли засвітилася голова зомбі.'::text),
(396267,44030,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... por el pasillo aterrorizados cuando se iluminó una cabeza de zombi.'::text,'Caminaban'::text,'Caminaron'::text,'Han caminado'::text,'Caminaban por el pasillo aterrorizados cuando se iluminó una cabeza de zombi.'::text),
(396266,44030,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... dans le couloir, terrifiés, quand une tête de zombie s''est allumée.'::text,'avançaient'::text,'ont avancé'::text,'ont avancé'::text,'Ils avançaient dans le couloir, terrifiés, quand une tête de zombie s''est allumée.'::text),
(396269,44030,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir zombi kafası yandığında koridorda dehşet içinde ...'::text,'yürüyorlardı'::text,'yürüdüler'::text,'yürümüşler'::text,'Bir zombi kafası yandığında koridorda dehşet içinde yürüyorlardı.'::text),
(396270,44030,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rettegve ... a folyosón, amikor felvillant egy zombifej.'::text,'lépkedtek'::text,'végigmentek'::text,'végigmentek'::text,'Rettegve lépkedtek a folyosón, amikor felvillant egy zombifej.'::text),
(396273,44031,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie beeindruckt: Ihr ... diesem Grauen seit zehn Minuten zusammen als Team.'::text,'trotzt'::text,'trotzt'::text,'trotzt'::text,'Irgendwie beeindruckt: Ihr trotzt diesem Grauen seit zehn Minuten zusammen als Team.'::text),
(396277,44031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Навіть вражає: ви ... цьому жаху разом як команда вже десять хвилин.'::text,'протистоїте'::text,'протистоїте'::text,'протистоїте'::text,'Навіть вражає: ви протистоїте цьому жаху разом як команда вже десять хвилин.'::text),
(396276,44031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Algo impresionado: lleváis diez minutos ... este terror juntos como equipo.'::text,'enfrentando'::text,'enfrentáis'::text,'enfrentáis'::text,'Algo impresionado: lleváis diez minutos enfrentando este terror juntos como equipo.'::text),
(396275,44031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Assez impressionné : vous ... cette terreur ensemble, en équipe, depuis dix minutes.'::text,'affrontez'::text,'affrontez'::text,'affrontez'::text,'Assez impressionné : vous affrontez cette terreur ensemble, en équipe, depuis dix minutes.'::text),
(396278,44031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz etkilendim: on dakikadır bu dehşete bir takım olarak birlikte ...'::text,'göğüs geriyorsunuz'::text,'göğüs geriyorsunuz'::text,'göğüs gerersiniz'::text,'Biraz etkilendim: on dakikadır bu dehşete bir takım olarak birlikte göğüs geriyorsunuz.'::text),
(396279,44031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit lenyűgöző: tíz perce ... együtt, csapatként ezzel a rettegéssel.'::text,'néztek szembe'::text,'néztek szembe'::text,'néztek szembe'::text,'Kicsit lenyűgöző: tíz perce néztek szembe együtt, csapatként ezzel a rettegéssel.'::text),
(396291,44033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich furchtlos: Er bestritt, bei der Clownsmaske vor Entsetzen ...'::text,'geschrien zu haben'::text,'zu schreien'::text,'schrie'::text,'Offensichtlich furchtlos: Er bestritt, bei der Clownsmaske vor Entsetzen geschrien zu haben.'::text),
(396295,44033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно безстрашний: він заперечив, що ... від жаху біля маски клоуна.'::text,'кричав'::text,'кричати'::text,'закричав'::text,'Очевидно безстрашний: він заперечив, що кричав від жаху біля маски клоуна.'::text),
(396294,44033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente valiente: negó ... de terror ante la máscara de payaso.'::text,'haber gritado'::text,'gritar'::text,'gritó'::text,'Obviamente valiente: negó haber gritado de terror ante la máscara de payaso.'::text),
(396293,44033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visiblement sans peur : il a nié ... de terreur devant le masque de clown.'::text,'avoir crié'::text,'crier'::text,'a crié'::text,'Visiblement sans peur : il a nié avoir crié de terreur devant le masque de clown.'::text),
(396296,44033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki korkusuz: palyaço maskesini görünce dehşetle ... inkâr etti.'::text,'çığlık attığını'::text,'çığlık atmayı'::text,'çığlık attı'::text,'Belli ki korkusuz: palyaço maskesini görünce dehşetle çığlık attığını inkâr etti.'::text),
(396297,44033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvalóan rettenthetetlen: tagadta, hogy rémületében ... a bohócmaszknál.'::text,'felsikoltott'::text,'felsikoltani'::text,'felsikoltott'::text,'Nyilvánvalóan rettenthetetlen: tagadta, hogy rémületében felsikoltott a bohócmaszknál.'::text),
(396300,44034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... in totaler Todesangst gewesen sein, sie hat so laut geschrien, echt.'::text,'muss'::text,'hätte'::text,'kann nicht'::text,'Bro, sie muss in totaler Todesangst gewesen sein, sie hat so laut geschrien, echt.'::text),
(396304,44034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... була в повному жаху, так голосно кричала, чесно.'::text,'напевно'::text,'мала б'::text,'не могла'::text,'Бро, вона напевно була в повному жаху, так голосно кричала, чесно.'::text),
(396303,44034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... estado aterrada total, gritó superfuerte, en serio.'::text,'debe de haber'::text,'debería haber'::text,'no puede'::text,'Bro, ella debe de haber estado aterrada total, gritó superfuerte, en serio.'::text),
(396302,44034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... été complètement terrifiée, elle a crié trop fort, sérieux.'::text,'a dû'::text,'aurait dû'::text,'ne peut pas'::text,'Frérot, elle a dû été complètement terrifiée, elle a crié trop fort, sérieux.'::text),
(396305,44034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o büyük bir dehşet içinde ..., o kadar yüksek çığlık attı ki, cidden.'::text,'olmalı'::text,'olmalıydı'::text,'olamaz'::text,'Kanka, o büyük bir dehşet içinde olmalı, o kadar yüksek çığlık attı ki, cidden.'::text),
(396306,44034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ... totál rettegésben, olyan hangosan sikított, komolyan.'::text,'biztos volt'::text,'kellett volna lennie'::text,'nem lehetett'::text,'Tesó, ő biztos volt totál rettegésben, olyan hangosan sikított, komolyan.'::text),
(396309,44035,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie hat ihn dazu gebracht, ihre Hand ... – den ganzen Horror lang, kein Witz.'::text,'zu halten'::text,'halten'::text,'gehalten'::text,'Alter, sie hat ihn dazu gebracht, ihre Hand zu halten – den ganzen Horror lang, kein Witz.'::text),
(396313,44035,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона змусила його ... її за руку весь цей жах, без брехні.'::text,'тримати'::text,'тримати'::text,'тримав'::text,'Чувак, вона змусила його тримати її за руку весь цей жах, без брехні.'::text),
(396312,44035,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella consiguió que él le ... la mano durante todo ese terror, en serio.'::text,'sujetara'::text,'sujeta'::text,'sujetó'::text,'Tío, ella consiguió que él le sujetara la mano durante todo ese terror, en serio.'::text),
(396311,44035,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle l''a convaincu de lui ... la main pendant toute cette terreur, sans mentir.'::text,'tenir'::text,'tenir'::text,'tenu'::text,'Mec, elle l''a convaincu de lui tenir la main pendant toute cette terreur, sans mentir.'::text),
(396314,44035,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o bütün dehşet boyunca çocuğun elini ... sağladı, yemin ederim.'::text,'tutmasını'::text,'tutmak'::text,'tuttu'::text,'Kanka, o bütün dehşet boyunca çocuğun elini tutmasını sağladı, yemin ederim.'::text),
(396315,44035,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, elérte, hogy a srác ... a kezét végig az egész rettegés alatt, komolyan.'::text,'fogja'::text,'fogni'::text,'fogta'::text,'Haver, elérte, hogy a srác fogja a kezét végig az egész rettegés alatt, komolyan.'::text),
(396318,44036,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Besucher wünschen sich, das 15-Euro-Angebot ... eine Warnung vor dem Horror im Inneren enthalten.'::text,'hätte'::text,'hat'::text,'wird'::text,'Die Besucher wünschen sich, das 15-Euro-Angebot hätte eine Warnung vor dem Horror im Inneren enthalten.'::text),
(396322,44036,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відвідувачі хотіли б, щоб пакет за 15 євро ... попередження про жах усередині.'::text,'містив'::text,'містив'::text,'міститиме'::text,'Відвідувачі хотіли б, щоб пакет за 15 євро містив попередження про жах усередині.'::text),
(396321,44036,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los visitantes desearían que la oferta de 15 euros ... un aviso sobre el terror del interior.'::text,'hubiera incluido'::text,'incluyera'::text,'incluirá'::text,'Los visitantes desearían que la oferta de 15 euros hubiera incluido un aviso sobre el terror del interior.'::text),
(396320,44036,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les visiteurs auraient aimé que l''offre à 15 euros ... un avertissement sur la terreur à l''intérieur.'::text,'ait inclus'::text,'inclue'::text,'inclura'::text,'Les visiteurs auraient aimé que l''offre à 15 euros ait inclus un avertissement sur la terreur à l''intérieur.'::text),
(396323,44036,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziyaretçiler, 15 euroluk paketin içerideki dehşet hakkında bir uyarı ... isterdi.'::text,'içermiş olmasını'::text,'içermesini'::text,'içereceğini'::text,'Ziyaretçiler, 15 euroluk paketin içerideki dehşet hakkında bir uyarı içermiş olmasını isterdi.'::text),
(396324,44036,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látogatók azt szeretnék, ha a 15 eurós ajánlat ... egy figyelmeztetést a bent várható rettegésről.'::text,'tartalmazott volna'::text,'tartalmazna'::text,'tartalmazni fog'::text,'A látogatók azt szeretnék, ha a 15 eurós ajánlat tartalmazott volna egy figyelmeztetést a bent várható rettegésről.'::text),
(396327,44037,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Augen vor Entsetzen weit aufgerissen sind, umklammert seine Schulter.'::text,'deren'::text,'die'::text,'welche'::text,'Die Frau, deren Augen vor Entsetzen weit aufgerissen sind, umklammert seine Schulter.'::text),
(396331,44037,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... очі широко розплющені від жаху, стискає його плече.'::text,'у якої'::text,'яка'::text,'котра'::text,'Жінка, у якої очі широко розплющені від жаху, стискає його плече.'::text),
(396330,44037,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer, ... ojos están abiertos de par en par por el terror, le agarra el hombro.'::text,'cuyos'::text,'la cual'::text,'que'::text,'La mujer, cuyos ojos están abiertos de par en par por el terror, le agarra el hombro.'::text),
(396329,44037,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme, ... les yeux sont écarquillés de terreur, lui agrippe l''épaule.'::text,'dont'::text,'laquelle'::text,'qui'::text,'La femme, dont les yeux sont écarquillés de terreur, lui agrippe l''épaule.'::text),
(396332,44037,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözleri dehşetten kocaman açılmış ... kadın, onun omzunu kavrıyor.'::text,'olan'::text,'olan'::text,'olan'::text,'Gözleri dehşetten kocaman açılmış olan kadın, onun omzunu kavrıyor.'::text),
(396333,44037,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... szeme tágra nyílt a rémülettől, megszorítja a srác vállát.'::text,'akinek a'::text,'amelyik'::text,'aki'::text,'A nő, akinek a szeme tágra nyílt a rémülettől, megszorítja a srác vállát.'::text),
(396336,44038,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., den sie zeigen, tritt typischerweise als Reaktion auf plötzliche Bedrohungen auf.'::text,'Der Schrecken'::text,'Ein Schrecken'::text,'Schrecken'::text,'Der Schrecken, den sie zeigen, tritt typischerweise als Reaktion auf plötzliche Bedrohungen auf.'::text),
(396340,44038,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., який вони демонструють, зазвичай виникає у відповідь на раптові загрози.'::text,'Жах'::text,'Жах'::text,'Жах'::text,'Жах, який вони демонструють, зазвичай виникає у відповідь на раптові загрози.'::text),
(396339,44038,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... que muestran suele producirse como respuesta a amenazas repentinas.'::text,'El terror'::text,'Un terror'::text,'Terror'::text,'El terror que muestran suele producirse como respuesta a amenazas repentinas.'::text),
(396338,44038,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... qu''ils manifestent survient généralement en réaction à des menaces soudaines.'::text,'La terreur'::text,'Une terreur'::text,'Terreur'::text,'La terreur qu''ils manifestent survient généralement en réaction à des menaces soudaines.'::text),
(396341,44038,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sergiledikleri ... genellikle ani tehditlere tepki olarak ortaya çıkar.'::text,'dehşet'::text,'bir dehşet'::text,'dehşet'::text,'Sergiledikleri dehşet genellikle ani tehditlere tepki olarak ortaya çıkar.'::text),
(396342,44038,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., amelyet mutatnak, jellemzően hirtelen fenyegetésekre adott válaszként jelentkezik.'::text,'A rettegés'::text,'Egy rettegés'::text,'Rettegés'::text,'A rettegés, amelyet mutatnak, jellemzően hirtelen fenyegetésekre adott válaszként jelentkezik.'::text),
(396354,44040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Gangs ... sie mindestens dreimal vor Entsetzen geschrien.'::text,'haben'::text,'werden'::text,'werden'::text,'Bis zum Ende des Gangs haben sie mindestens dreimal vor Entsetzen geschrien.'::text),
(396358,44040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця коридору вони ... від жаху щонайменше тричі.'::text,'закричать'::text,'закричать'::text,'кричатимуть'::text,'До кінця коридору вони закричать від жаху щонайменше тричі.'::text),
(396357,44040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del pasillo, ... de terror al menos tres veces.'::text,'habrán gritado'::text,'gritarán'::text,'estarán gritando'::text,'Para el final del pasillo, habrán gritado de terror al menos tres veces.'::text),
(396356,44040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du couloir, ils ... de terreur au moins trois fois.'::text,'auront crié'::text,'crieront'::text,'seront en train de crier'::text,'D''ici la fin du couloir, ils auront crié de terreur au moins trois fois.'::text),
(396359,44040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koridorun sonuna kadar dehşetle en az üç kez ...'::text,'çığlık atmış olacaklar'::text,'çığlık atacaklar'::text,'çığlık atıyor olacaklar'::text,'Koridorun sonuna kadar dehşetle en az üç kez çığlık atmış olacaklar.'::text),
(396360,44040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A folyosó végéig legalább háromszor ... a rémülettől.'::text,'felsikoltanak'::text,'sikítani fognak'::text,'sikítani fognak'::text,'A folyosó végéig legalább háromszor felsikoltanak a rémülettől.'::text),
(337575,37509,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade die Ruhe des Abends, als der T-Rex heraussprang. Leicht ungeplant.'::text,'genoss'::text,'genoss'::text,'hat genossen'::text,'Sie genoss gerade die Ruhe des Abends, als der T-Rex heraussprang. Leicht ungeplant.'::text),
(337579,37509,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... спокоєм вечора, коли вискочив Ті-рекс. Трохи незаплановано.'::text,'насолоджувалася'::text,'насолодилася'::text,'насолодилася'::text,'Вона насолоджувалася спокоєм вечора, коли вискочив Ті-рекс. Трохи незаплановано.'::text),
(337578,37509,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... de la calma de la noche cuando saltó el T-rex. Un pelín improvisado.'::text,'estaba disfrutando'::text,'disfrutó'::text,'ha disfrutado'::text,'Ella estaba disfrutando de la calma de la noche cuando saltó el T-rex. Un pelín improvisado.'::text),
(337577,37509,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... du calme de la soirée quand le T-rex a surgi. Légèrement imprévu.'::text,'profitait'::text,'a profité'::text,'a profité'::text,'Elle profitait du calme de la soirée quand le T-rex a surgi. Légèrement imprévu.'::text),
(337580,37509,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, akşamın sakinliğinin keyfini ... ki T-rex fırladı. Biraz plansız oldu.'::text,'çıkarıyordu'::text,'çıkardı'::text,'çıkarmış'::text,'O, akşamın sakinliğinin keyfini çıkarıyordu ki T-rex fırladı. Biraz plansız oldu.'::text),
(337581,37509,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az este nyugalmát, amikor előugrott a T-rex. Kicsit nem volt betervezve.'::text,'élvezte'::text,'élvezte'::text,'élvezte'::text,'Épp élvezte az este nyugalmát, amikor előugrott a T-rex. Kicsit nem volt betervezve.'::text),
(337584,37510,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der T-Rex ... schon den ganzen Abend ihre Ruhe auf die Probe. Wirklich reizende Gesellschaft.'::text,'stellt'::text,'stellt'::text,'stellt'::text,'Der T-Rex stellt schon den ganzen Abend ihre Ruhe auf die Probe. Wirklich reizende Gesellschaft.'::text),
(337588,37510,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ті-рекс увесь вечір ... її спокій. Справді чарівна компанія.'::text,'випробовує'::text,'випробовує'::text,'випробовує'::text,'Ті-рекс увесь вечір випробовує її спокій. Справді чарівна компанія.'::text),
(337587,37510,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El T-rex lleva toda la noche ... su calma. Una compañía verdaderamente encantadora.'::text,'poniendo a prueba'::text,'pone a prueba'::text,'pone a prueba'::text,'El T-rex lleva toda la noche poniendo a prueba su calma. Una compañía verdaderamente encantadora.'::text),
(337586,37510,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le T-rex ... son calme toute la soirée. Une compagnie vraiment charmante.'::text,'met à l''épreuve'::text,'met à l''épreuve'::text,'met à l''épreuve'::text,'Le T-rex met à l''épreuve son calme toute la soirée. Une compagnie vraiment charmante.'::text),
(337589,37510,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T-rex bütün akşam onun sakinliğini ..., gerçekten çok hoş bir arkadaş.'::text,'sınıyor'::text,'sınıyor'::text,'sınar'::text,'T-rex bütün akşam onun sakinliğini sınıyor, gerçekten çok hoş bir arkadaş.'::text),
(337590,37510,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A T-rex egész este ... a nyugalmát. Igazán elbűvölő társaság.'::text,'teszi próbára'::text,'teszi próbára'::text,'teszi próbára'::text,'A T-rex egész este teszi próbára a nyugalmát. Igazán elbűvölő társaság.'::text),
(337593,37511,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, ihre Ruhe ... in der Sekunde, als der T-Rex auftauchte, echt.'::text,'verschwand'::text,'verschwand gerade'::text,'ist verschwunden'::text,'Nee, ihre Ruhe verschwand in der Sekunde, als der T-Rex auftauchte, echt.'::text),
(337597,37511,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не-а, її спокій ... тієї ж секунди, як вискочив той Ті-рекс, чесно.'::text,'зник'::text,'зникав'::text,'зник'::text,'Не-а, її спокій зник тієї ж секунди, як вискочив той Ті-рекс, чесно.'::text),
(337596,37511,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, su calma ... en el segundo en que apareció ese T-rex, en serio.'::text,'desapareció'::text,'estaba desapareciendo'::text,'ha desaparecido'::text,'Nah, su calma desapareció en el segundo en que apareció ese T-rex, en serio.'::text),
(337595,37511,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, son calme ... à la seconde où ce T-rex a surgi, sérieux.'::text,'a disparu'::text,'disparaissait'::text,'a disparu'::text,'Nan, son calme a disparu à la seconde où ce T-rex a surgi, sérieux.'::text),
(337598,37511,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok ya, o T-rex ortaya çıktığı saniye onun sakinliği ..., cidden.'::text,'uçup gitti'::text,'gidiyordu'::text,'gitmiş'::text,'Yok ya, o T-rex ortaya çıktığı saniye onun sakinliği uçup gitti, cidden.'::text),
(337599,37511,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, a nyugalma abban a pillanatban ..., ahogy az a T-rex felbukkant, komolyan.'::text,'elszállt'::text,'szállt el'::text,'elszállt'::text,'Á, a nyugalma abban a pillanatban elszállt, ahogy az a T-rex felbukkant, komolyan.'::text),
(337602,37512,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wegen diesem T-Rex-Typen hat sie diese Woche schon dreimal die Ruhe ...'::text,'verloren'::text,'verloren'::text,'verloren'::text,'Bro, wegen diesem T-Rex-Typen hat sie diese Woche schon dreimal die Ruhe verloren.'::text),
(337606,37512,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона цього тижня тричі ... спокій через того чувака в костюмі Ті-рекса.'::text,'втратила'::text,'втрачала'::text,'втратила'::text,'Бро, вона цього тижня тричі втратила спокій через того чувака в костюмі Ті-рекса.'::text),
(337605,37512,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, esta semana ella ... la calma tres veces por culpa del tío del T-rex.'::text,'ha perdido'::text,'ha estado perdiendo'::text,'perdió'::text,'Bro, esta semana ella ha perdido la calma tres veces por culpa del tío del T-rex.'::text),
(337604,37512,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... son calme trois fois cette semaine à cause de ce mec en T-rex.'::text,'a perdu'::text,'perd'::text,'a perdu'::text,'Frérot, elle a perdu son calme trois fois cette semaine à cause de ce mec en T-rex.'::text),
(337607,37512,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu hafta o T-rex tipi yüzünden üç kez sakinliğini ...'::text,'kaybetti'::text,'kaybediyor'::text,'kaybetti'::text,'Kanka, bu hafta o T-rex tipi yüzünden üç kez sakinliğini kaybetti.'::text),
(337608,37512,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ezen a héten háromszor ... a nyugalmát a T-rexes csávó miatt.'::text,'vesztette el'::text,'veszítette'::text,'elvesztette'::text,'Tesó, ezen a héten háromszor vesztette el a nyugalmát a T-rexes csávó miatt.'::text),
(337611,37513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ruhe, ... für heute Abend auf der Agenda stand, dauerte genau 4 Sekunden.'::text,'die'::text,'wer'::text,'was'::text,'Die Ruhe, die für heute Abend auf der Agenda stand, dauerte genau 4 Sekunden.'::text),
(337615,37513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спокій, ... був у сьогоднішньому порядку денному, тривав рівно 4 секунди.'::text,'який'::text,'хто'::text,'що'::text,'Спокій, який був у сьогоднішньому порядку денному, тривав рівно 4 секунди.'::text),
(337614,37513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La calma ... estaba en la agenda de esta noche duró exactamente 4 segundos.'::text,'que'::text,'quien'::text,'lo que'::text,'La calma que estaba en la agenda de esta noche duró exactamente 4 segundos.'::text),
(337613,37513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le calme ... était à l''ordre du jour ce soir a duré exactement 4 secondes.'::text,'qui'::text,'lequel'::text,'ce qui'::text,'Le calme qui était à l''ordre du jour ce soir a duré exactement 4 secondes.'::text),
(337616,37513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşamın gündeminde ... sakinlik tam 4 saniye sürdü.'::text,'olan'::text,'olan'::text,'olan'::text,'Bu akşamın gündeminde olan sakinlik tam 4 saniye sürdü.'::text),
(337617,37513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nyugalom, ... a ma esti napirenden szerepelt, pontosan 4 másodpercig tartott.'::text,'ami'::text,'aki'::text,'amit'::text,'A nyugalom, ami a ma esti napirenden szerepelt, pontosan 4 másodpercig tartott.'::text),
(337620,37514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... ihre Ruhe verloren, weil sie nicht mehr ruhig war.'::text,'habe'::text,'hat'::text,'verliere'::text,'Sie sagte, sie habe ihre Ruhe verloren, weil sie nicht mehr ruhig war.'::text),
(337624,37514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... спокій, бо вже не була спокійною.'::text,'втратила'::text,'втратила'::text,'втрачає'::text,'Вона сказала, що втратила спокій, бо вже не була спокійною.'::text),
(337623,37514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... la calma porque ya no estaba tranquila.'::text,'había perdido'::text,'ha perdido'::text,'pierde'::text,'Dijo que había perdido la calma porque ya no estaba tranquila.'::text),
(337622,37514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... son calme parce qu''elle n''était plus calme.'::text,'avait perdu'::text,'a perdu'::text,'perd'::text,'Elle a dit qu''elle avait perdu son calme parce qu''elle n''était plus calme.'::text),
(337625,37514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Artık sakin olmadığı için sakinliğini ... söyledi.'::text,'kaybettiğini'::text,'kaybettiğini'::text,'kaybediyor olduğunu'::text,'Artık sakin olmadığı için sakinliğini kaybettiğini söyledi.'::text),
(337626,37514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy ... a nyugalmát, mert már nem volt nyugodt.'::text,'elvesztette'::text,'elvesztette'::text,'elveszíti'::text,'Azt mondta, hogy elvesztette a nyugalmát, mert már nem volt nyugodt.'::text),
(337638,37516,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wird nie wieder riskieren, bei einem Filmabend mit diesem T-Rex in der Nähe ihre Ruhe ...!'::text,'zu verlieren'::text,'verlieren'::text,'verliert'::text,'Sie wird nie wieder riskieren, bei einem Filmabend mit diesem T-Rex in der Nähe ihre Ruhe zu verlieren!'::text),
(337642,37516,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона більше ніколи не ризикне ... спокій на кіновечорі з тим Ті-рексом поруч!'::text,'втратити'::text,'втратити'::text,'втрачати'::text,'Вона більше ніколи не ризикне втратити спокій на кіновечорі з тим Ті-рексом поруч!'::text),
(337641,37516,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca más se arriesgará a ... la calma en una noche de peli con ese T-rex cerca!'::text,'perder'::text,'perder'::text,'pierde'::text,'¡Nunca más se arriesgará a perder la calma en una noche de peli con ese T-rex cerca!'::text),
(337640,37516,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plus jamais elle ne risquera de ... son calme lors d''une soirée film avec ce T-rex dans les parages !'::text,'perdre'::text,'perdre'::text,'perd'::text,'Plus jamais elle ne risquera de perdre son calme lors d''une soirée film avec ce T-rex dans les parages !'::text),
(337643,37516,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O T-rex etraftayken bir film gecesinde sakinliğini ... riskine bir daha asla girmeyecek!'::text,'kaybetme'::text,'kaybetmek'::text,'kaybeder'::text,'O T-rex etraftayken bir film gecesinde sakinliğini kaybetme riskine bir daha asla girmeyecek!'::text),
(337644,37516,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha többé nem kockáztatja, hogy ... a nyugalmát egy filmesten, ha az a T-rex a közelben van!'::text,'elveszítse'::text,'elveszíteni'::text,'elveszíti'::text,'Soha többé nem kockáztatja, hogy elveszítse a nyugalmát egy filmesten, ha az a T-rex a közelben van!'::text),
(337647,37517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kommt mit ... von jemandem herein, der einen ruhigen Filmabend erwartet.'::text,'der Ruhe'::text,'einer Ruhe'::text,'Ruhe'::text,'Sie kommt mit der Ruhe von jemandem herein, der einen ruhigen Filmabend erwartet.'::text),
(337651,37517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона заходить зі ... людини, яка чекає тихого кіновечора.'::text,'спокоєм'::text,'спокоєм'::text,'спокоєм'::text,'Вона заходить зі спокоєм людини, яка чекає тихого кіновечора.'::text),
(337650,37517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entra con ... de alguien que espera una noche de peli tranquila.'::text,'la calma'::text,'una calma'::text,'calma'::text,'Entra con la calma de alguien que espera una noche de peli tranquila.'::text),
(337649,37517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle entre avec ... de quelqu''un qui s''attend à une soirée film tranquille.'::text,'le calme'::text,'un calme'::text,'calme'::text,'Elle entre avec le calme de quelqu''un qui s''attend à une soirée film tranquille.'::text),
(337652,37517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakin bir film gecesi bekleyen birinin ... içeri giriyor.'::text,'sakinliğiyle'::text,'bir sakinlikle'::text,'sakinlikle'::text,'Sakin bir film gecesi bekleyen birinin sakinliğiyle içeri giriyor.'::text),
(337653,37517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... lép be, mint aki nyugodt filmestére számít.'::text,'Azzal a nyugalommal'::text,'Egy nyugalommal'::text,'Nyugalommal'::text,'Azzal a nyugalommal lép be, mint aki nyugodt filmestére számít.'::text),
(337665,37519,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Ruhe ... erst ein paar Sekunden gedauert, als der T-Rex hochsprang.'::text,'hatte'::text,'hat'::text,'dauert'::text,'Ihre Ruhe hatte erst ein paar Sekunden gedauert, als der T-Rex hochsprang.'::text),
(337669,37519,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її спокій ... лише кілька секунд, коли вискочив Ті-рекс.'::text,'тривав'::text,'тривав'::text,'триває'::text,'Її спокій тривав лише кілька секунд, коли вискочив Ті-рекс.'::text),
(337668,37519,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su calma ... solo unos segundos cuando el T-rex saltó.'::text,'había durado'::text,'ha durado'::text,'dura'::text,'Su calma había durado solo unos segundos cuando el T-rex saltó.'::text),
(337667,37519,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son calme ... seulement quelques secondes quand le T-rex a bondi.'::text,'avait duré'::text,'a duré'::text,'dure'::text,'Son calme avait duré seulement quelques secondes quand le T-rex a bondi.'::text),
(337670,37519,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T-rex fırladığında sakinliği sadece birkaç saniye ...'::text,'sürmüştü'::text,'sürdü'::text,'sürer'::text,'T-rex fırladığında sakinliği sadece birkaç saniye sürmüştü.'::text),
(337671,37519,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nyugalma csak néhány másodpercig ..., amikor a T-rex felugrott.'::text,'tartott'::text,'tartott'::text,'tart'::text,'A nyugalma csak néhány másodpercig tartott, amikor a T-rex felugrott.'::text),
(367860,40874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... die Ranger den Weg ungefähr sechs Stunden lang mit Fahnen markiert.'::text,'haben'::text,'werden'::text,'haben'::text,'Bis Sonnenuntergang haben die Ranger den Weg ungefähr sechs Stunden lang mit Fahnen markiert.'::text),
(367864,40874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця рейнджери ... стежку прапорцями приблизно шість годин.'::text,'позначатимуть'::text,'позначатимуть'::text,'позначать'::text,'До заходу сонця рейнджери позначатимуть стежку прапорцями приблизно шість годин.'::text),
(367863,40874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, los guardas ... el sendero con banderas durante aproximadamente seis horas.'::text,'habrán estado marcando'::text,'estarán marcando'::text,'habrán marcado'::text,'Para el atardecer, los guardas habrán estado marcando el sendero con banderas durante aproximadamente seis horas.'::text),
(367862,40874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, les rangers ... le sentier avec des drapeaux pendant environ six heures.'::text,'auront balisé'::text,'seront en train de baliser'::text,'auront balisé'::text,'D''ici le coucher du soleil, les rangers auront balisé le sentier avec des drapeaux pendant environ six heures.'::text),
(367865,40874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar korucular patikayı yaklaşık altı saat boyunca bayraklarla ...'::text,'işaretliyor olacaklar'::text,'işaretliyor olacaklar'::text,'işaretlemiş olacaklar'::text,'Gün batımına kadar korucular patikayı yaklaşık altı saat boyunca bayraklarla işaretliyor olacaklar.'::text),
(367866,40874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtáig a vadőrök körülbelül hat órán át ... az ösvényt zászlókkal.'::text,'jelölik'::text,'fogják jelölni'::text,'jelölik ki'::text,'Napnyugtáig a vadőrök körülbelül hat órán át jelölik az ösvényt zászlókkal.'::text),
(367869,40875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten sie die Linie nicht markiert, ... sich die Wanderer komplett verlaufen! Ein Albtraum!'::text,'hätten'::text,'werden'::text,'haben'::text,'Hätten sie die Linie nicht markiert, hätten sich die Wanderer komplett verlaufen! Ein Albtraum!'::text),
(367873,40875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони не позначили лінію, туристи ... зовсім! Кошмар!'::text,'заблукали б'::text,'заблукають'::text,'заблукали'::text,'Якби вони не позначили лінію, туристи заблукали б зовсім! Кошмар!'::text),
(367872,40875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no hubieran marcado la línea, los excursionistas ... completamente! ¡Una pesadilla!'::text,'se habrían perdido'::text,'se perderán'::text,'se perdieron'::text,'¡Si no hubieran marcado la línea, los excursionistas se habrían perdido completamente! ¡Una pesadilla!'::text),
(367871,40875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils n''avaient pas balisé la ligne, les randonneurs ... complètement ! Un cauchemar !'::text,'se seraient perdus'::text,'se perdront'::text,'se sont perdus'::text,'S''ils n''avaient pas balisé la ligne, les randonneurs se seraient perdus complètement ! Un cauchemar !'::text),
(367874,40875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hattı işaretlemeselerdi, yürüyüşçüler tamamen ...! Kâbus!'::text,'kaybolurlardı'::text,'kaybolacaklar'::text,'kayboldular'::text,'Hattı işaretlemeselerdi, yürüyüşçüler tamamen kaybolurlardı! Kâbus!'::text),
(367875,40875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem jelölték volna ki a vonalat, a túrázók teljesen ...! Rémálom!'::text,'eltévedtek volna'::text,'eltévednek'::text,'eltévedtek'::text,'Ha nem jelölték volna ki a vonalat, a túrázók teljesen eltévedtek volna! Rémálom!'::text),
(367878,40876,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten sie den Weg gestern nicht markiert, ... die Wanderer jetzt völlig verloren auf diesen Hügeln!'::text,'wären'::text,'wären gewesen'::text,'werden'::text,'Hätten sie den Weg gestern nicht markiert, wären die Wanderer jetzt völlig verloren auf diesen Hügeln!'::text),
(367882,40876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони вчора не позначили стежку, туристи ... зараз геть загублені на цих пагорбах!'::text,'були б'::text,'були б'::text,'будуть'::text,'Якби вони вчора не позначили стежку, туристи були б зараз геть загублені на цих пагорбах!'::text),
(367881,40876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no hubieran marcado el sendero ayer, los excursionistas ... totalmente perdidos en estas colinas ahora!'::text,'estarían'::text,'habrían estado'::text,'estarán'::text,'¡Si no hubieran marcado el sendero ayer, los excursionistas estarían totalmente perdidos en estas colinas ahora!'::text),
(367880,40876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils n''avaient pas balisé le chemin hier, les randonneurs ... complètement perdus sur ces collines maintenant !'::text,'seraient'::text,'auraient été'::text,'seront'::text,'S''ils n''avaient pas balisé le chemin hier, les randonneurs seraient complètement perdus sur ces collines maintenant !'::text),
(367883,40876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün patikayı işaretlemeselerdi, yürüyüşçüler şu an bu tepelerde tamamen kaybolmuş ...!'::text,'olurlardı'::text,'olurlardı'::text,'olacaklar'::text,'Dün patikayı işaretlemeselerdi, yürüyüşçüler şu an bu tepelerde tamamen kaybolmuş olurlardı!'::text),
(367884,40876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha tegnap nem jelölték volna ki az ösvényt, a túrázók most teljesen ... ezeken a dombokon!'::text,'eltévednének'::text,'eltévedtek volna'::text,'eltévednek'::text,'Ha tegnap nem jelölték volna ki az ösvényt, a túrázók most teljesen eltévednének ezeken a dombokon!'::text),
(367887,40877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Grat soll jahrelang falsch ... sein, was ein absoluter Albtraum ist!'::text,'markiert worden'::text,'markieren'::text,'markierend'::text,'Dieser Grat soll jahrelang falsch markiert worden sein, was ein absoluter Albtraum ist!'::text),
(367891,40877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що цей хребет роками ... неправильно, і це абсолютний кошмар!'::text,'позначали'::text,'позначати'::text,'позначення'::text,'Вважається, що цей хребет роками позначали неправильно, і це абсолютний кошмар!'::text),
(367890,40877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se cree que esta cresta ... mal durante años, lo cual es una auténtica pesadilla!'::text,'ha sido marcada'::text,'marcar'::text,'marcando'::text,'¡Se cree que esta cresta ha sido marcada mal durante años, lo cual es una auténtica pesadilla!'::text),
(367889,40877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que cette crête ... mal pendant des années, ce qui est un vrai cauchemar !'::text,'a été balisée'::text,'baliser'::text,'balisant'::text,'On pense que cette crête a été balisée mal pendant des années, ce qui est un vrai cauchemar !'::text),
(367892,40877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sırtın yıllarca yanlış ... sanılıyor, ki bu tam bir kâbus!'::text,'işaretlendiği'::text,'işaretlemek'::text,'işaretleme'::text,'Bu sırtın yıllarca yanlış işaretlendiği sanılıyor, ki bu tam bir kâbus!'::text),
(367893,40877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy ezt a gerincet évekig rosszul ..., ami egy abszolút rémálom!'::text,'jelölték'::text,'jelölni'::text,'jelölve'::text,'Úgy tartják, hogy ezt a gerincet évekig rosszul jelölték, ami egy abszolút rémálom!'::text),
(367896,40878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, angeblich hat sie sich geweigert, die Linie ..., ohne vorher die Karte zu checken.'::text,'zu markieren'::text,'markieren'::text,'markieren'::text,'Ok also, angeblich hat sie sich geweigert, die Linie zu markieren, ohne vorher die Karte zu checken.'::text),
(367900,40878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, кажуть, вона відмовилася ... лінію, не перевіривши спершу карту.'::text,'позначати'::text,'позначення'::text,'позначати'::text,'Окей, кажуть, вона відмовилася позначати лінію, не перевіривши спершу карту.'::text),
(367899,40878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, pues dicen que ella se negó a ... la línea sin mirar antes el mapa.'::text,'marcar'::text,'marcando'::text,'marca'::text,'Ok, pues dicen que ella se negó a marcar la línea sin mirar antes el mapa.'::text),
(367898,40878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok alors, il paraît qu''elle a refusé de ... la ligne sans vérifier la carte d''abord.'::text,'baliser'::text,'balisant'::text,'balise'::text,'Ok alors, il paraît qu''elle a refusé de baliser la ligne sans vérifier la carte d''abord.'::text),
(367901,40878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre önce haritaya bakmadan hattı ... reddetmiş.'::text,'işaretlemeyi'::text,'işaretleme'::text,'işaretle'::text,'Tamam, duyduğuma göre önce haritaya bakmadan hattı işaretlemeyi reddetmiş.'::text),
(367902,40878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval azt beszélik, nem volt hajlandó ... a vonalat anélkül, hogy előbb megnézte volna a térképet.'::text,'kijelölni'::text,'kijelölés'::text,'jelöl'::text,'Oké, szóval azt beszélik, nem volt hajlandó kijelölni a vonalat anélkül, hogy előbb megnézte volna a térképet.'::text),
(367905,40879,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie haben die Karte studiert, also ... sie die Linie darauf markiert haben, bevor sie bergauf gingen.'::text,'müssen'::text,'müssen'::text,'können nicht'::text,'Sie haben die Karte studiert, also müssen sie die Linie darauf markiert haben, bevor sie bergauf gingen.'::text),
(367909,40879,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони вивчали карту, тож вони ... лінію на ній, перш ніж піти вгору.'::text,'напевно позначили'::text,'мусять позначити'::text,'не могли позначити'::text,'Вони вивчали карту, тож вони напевно позначили лінію на ній, перш ніж піти вгору.'::text),
(367908,40879,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estudiaron el mapa, así que ... la línea en él antes de subir la cuesta.'::text,'debieron de marcar'::text,'deben marcar'::text,'no pueden haber marcado'::text,'Estudiaron el mapa, así que debieron de marcar la línea en él antes de subir la cuesta.'::text),
(367907,40879,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont étudié la carte, donc ils ... la ligne dessus avant de monter.'::text,'ont dû tracer'::text,'doivent tracer'::text,'n''ont pas pu tracer'::text,'Ils ont étudié la carte, donc ils ont dû tracer la ligne dessus avant de monter.'::text),
(367910,40879,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haritayı incelediler, yani yokuşu tırmanmadan önce hattı haritada ...'::text,'işaretlemiş olmalılar'::text,'işaretlemeliler'::text,'işaretlemiş olamazlar'::text,'Haritayı incelediler, yani yokuşu tırmanmadan önce hattı haritada işaretlemiş olmalılar.'::text),
(367911,40879,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tanulmányozták a térképet, szóval ... rajta a vonalat, mielőtt felmentek a dombra.'::text,'biztosan bejelölték'::text,'be kell jelölniük'::text,'nem jelölhették be'::text,'Tanulmányozták a térképet, szóval biztosan bejelölték rajta a vonalat, mielőtt felmentek a dombra.'::text),
(367914,40880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst als die letzte Fahne steckte, ... zurück, um sich die markierte Linie anzusehen.'::text,'trat sie'::text,'sie trat'::text,'trat sie'::text,'Erst als die letzte Fahne steckte, trat sie zurück, um sich die markierte Linie anzusehen.'::text),
(367918,40880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише коли останній прапорець був на місці, ... назад, щоб подивитися на позначену лінію.'::text,'вона відступила'::text,'вона відступила'::text,'відступила вона'::text,'Лише коли останній прапорець був на місці, вона відступила назад, щоб подивитися на позначену лінію.'::text),
(367917,40880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta que no estuvo clavada la última bandera, no ... atrás para mirar la línea marcada.'::text,'dio ella un paso'::text,'ella dio un paso'::text,'dio un paso ella'::text,'Hasta que no estuvo clavada la última bandera, no dio ella un paso atrás para mirar la línea marcada.'::text),
(367916,40880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est que lorsque le dernier drapeau fut planté que ... un pas en arrière pour regarder la ligne balisée.'::text,'elle fit'::text,'elle fit'::text,'fit-elle'::text,'Ce n''est que lorsque le dernier drapeau fut planté que elle fit un pas en arrière pour regarder la ligne balisée.'::text),
(367919,40880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ancak son bayrak dikildiğinde, işaretli hatta bakmak için geri ...'::text,'çekildi'::text,'çekildi'::text,'çekildi'::text,'Ancak son bayrak dikildiğinde, işaretli hatta bakmak için geri çekildi.'::text),
(367920,40880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak amikor az utolsó zászló is a helyén volt, ... hátra, hogy megnézze a kijelölt vonalat.'::text,'lépett'::text,'lépett ő'::text,'ő lépett'::text,'Csak amikor az utolsó zászló is a helyén volt, lépett hátra, hogy megnézze a kijelölt vonalat.'::text),
(367923,40881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Parkleiter ließ die Ranger den neuen Weg mit orangen Fahnen ...'::text,'markieren'::text,'zu markieren'::text,'markiert'::text,'Der Parkleiter ließ die Ranger den neuen Weg mit orangen Fahnen markieren.'::text),
(367927,40881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Керівник парку доручив рейнджерам ... нову стежку помаранчевими прапорцями.'::text,'позначити'::text,'позначати'::text,'позначили'::text,'Керівник парку доручив рейнджерам позначити нову стежку помаранчевими прапорцями.'::text),
(367926,40881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El director del parque hizo que los guardas ... el nuevo sendero con banderas naranjas.'::text,'marcaran'::text,'marcar'::text,'marcaron'::text,'El director del parque hizo que los guardas marcaran el nuevo sendero con banderas naranjas.'::text),
(367925,40881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le directeur du parc a fait ... le nouveau sentier aux rangers avec des drapeaux orange.'::text,'baliser'::text,'de baliser'::text,'balisé'::text,'Le directeur du parc a fait baliser le nouveau sentier aux rangers avec des drapeaux orange.'::text),
(367928,40881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Park müdürü koruculara yeni patikayı turuncu bayraklarla ...'::text,'işaretletti'::text,'işaretlemeyi'::text,'işaretlendi'::text,'Park müdürü koruculara yeni patikayı turuncu bayraklarla işaretletti.'::text),
(367929,40881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A park vezetője ... a vadőrökkel az új ösvényt narancssárga zászlókkal.'::text,'kijelöltette'::text,'kijelölni'::text,'kijelölte'::text,'A park vezetője kijelöltette a vadőrökkel az új ösvényt narancssárga zászlókkal.'::text),
(367941,40883,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Grat, ... sie vor der Deadline mit 40 Fahnen markiert haben, reicht bis zum Meer.'::text,'den'::text,'wer'::text,'welchen'::text,'Der Grat, den sie vor der Deadline mit 40 Fahnen markiert haben, reicht bis zum Meer.'::text),
(367945,40883,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хребет, ... вони позначили 40 прапорцями до дедлайну, спускається до моря.'::text,'який'::text,'хто'::text,'котрий'::text,'Хребет, який вони позначили 40 прапорцями до дедлайну, спускається до моря.'::text),
(367944,40883,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cresta, ... marcaron con 40 banderas antes de la fecha límite, baja hasta el mar.'::text,'que'::text,'quien'::text,'la cual'::text,'La cresta, que marcaron con 40 banderas antes de la fecha límite, baja hasta el mar.'::text),
(367943,40883,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La crête, ... les rangers ont balisée avec 40 drapeaux avant la deadline, descend jusqu''à la mer.'::text,'que'::text,'qui'::text,'laquelle'::text,'La crête, que les rangers ont balisée avec 40 drapeaux avant la deadline, descend jusqu''à la mer.'::text),
(367946,40883,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tarihten önce 40 bayrakla ... sırt denize kadar uzanıyor.'::text,'işaretledikleri'::text,'işaretleyen'::text,'işaretledikleri'::text,'Son tarihten önce 40 bayrakla işaretledikleri sırt denize kadar uzanıyor.'::text),
(367947,40883,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gerinc, ... a határidő előtt 40 zászlóval jelöltek ki, egészen a tengerig ér.'::text,'amelyet'::text,'aki'::text,'amit'::text,'A gerinc, amelyet a határidő előtt 40 zászlóval jelöltek ki, egészen a tengerig ér.'::text),
(367950,40884,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Karte markierten sie die Linie genau entlang des Grats.'::text,'Dank'::text,'Trotz'::text,'Statt'::text,'Dank der Karte markierten sie die Linie genau entlang des Grats.'::text),
(367954,40884,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... карті вони позначили лінію точно вздовж хребта.'::text,'Завдяки'::text,'Попри'::text,'Замість'::text,'Завдяки карті вони позначили лінію точно вздовж хребта.'::text),
(367953,40884,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el mapa, marcaron la línea justo a lo largo de la cresta.'::text,'Gracias a'::text,'A pesar de'::text,'En lugar de'::text,'Gracias a el mapa, marcaron la línea justo a lo largo de la cresta.'::text),
(367952,40884,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la carte, ils ont balisé la ligne exactement le long de la crête.'::text,'Grâce à'::text,'Malgré'::text,'Au lieu de'::text,'Grâce à la carte, ils ont balisé la ligne exactement le long de la crête.'::text),
(367955,40884,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harita ... hattı tam olarak sırt boyunca işaretlediler.'::text,'sayesinde'::text,'rağmen'::text,'yerine'::text,'Harita sayesinde hattı tam olarak sırt boyunca işaretlediler.'::text),
(367956,40884,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A térképnek ... pontosan a gerinc mentén jelölték ki a vonalat.'::text,'köszönhetően'::text,'ellenére'::text,'helyett'::text,'A térképnek köszönhetően pontosan a gerinc mentén jelölték ki a vonalat.'::text),
(396408,44046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ärztin ... seinen Hals untersucht, also darf er jetzt Wasser trinken.'::text,'hat'::text,'hat'::text,'untersucht'::text,'Die Ärztin hat seinen Hals untersucht, also darf er jetzt Wasser trinken.'::text),
(396412,44046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лікарка ... йому горло, тож тепер він може пити воду.'::text,'оглянула'::text,'оглядала'::text,'оглядає'::text,'Лікарка оглянула йому горло, тож тепер він може пити воду.'::text),
(396411,44046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La doctora le ... la garganta, así que ahora puede beber agua.'::text,'ha revisado'::text,'ha estado revisando'::text,'revisa'::text,'La doctora le ha revisado la garganta, así que ahora puede beber agua.'::text),
(396410,44046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La médecin lui ... la gorge, donc il peut boire de l''eau maintenant.'::text,'a examiné'::text,'examine'::text,'examine'::text,'La médecin lui a examiné la gorge, donc il peut boire de l''eau maintenant.'::text),
(396413,44046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doktor onun boğazını ..., o yüzden artık su içebilir.'::text,'kontrol etti'::text,'kontrol ediyor'::text,'kontrol eder'::text,'Doktor onun boğazını kontrol etti, o yüzden artık su içebilir.'::text),
(396414,44046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az orvos ... a torkát, így most már ihat vizet.'::text,'megvizsgálta'::text,'vizsgálta'::text,'vizsgálja'::text,'Az orvos megvizsgálta a torkát, így most már ihat vizet.'::text),
(396417,44047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ärztin ... seinen Hals untersucht, bevor er zum Wasserspender ging.'::text,'hatte'::text,'hat'::text,'untersucht'::text,'Die Ärztin hatte seinen Hals untersucht, bevor er zum Wasserspender ging.'::text),
(396421,44047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лікарка ... йому горло, перш ніж він пішов до кулера.'::text,'оглянула'::text,'оглянула'::text,'оглядає'::text,'Лікарка оглянула йому горло, перш ніж він пішов до кулера.'::text),
(396420,44047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La doctora le ... la garganta antes de que él fuera al dispensador de agua.'::text,'había revisado'::text,'ha revisado'::text,'revisa'::text,'La doctora le había revisado la garganta antes de que él fuera al dispensador de agua.'::text),
(396419,44047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La médecin lui ... la gorge avant qu''il aille à la fontaine à eau.'::text,'avait examiné'::text,'a examiné'::text,'examine'::text,'La médecin lui avait examiné la gorge avant qu''il aille à la fontaine à eau.'::text),
(396422,44047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O su sebiline gitmeden önce doktor boğazını ...'::text,'kontrol etmişti'::text,'kontrol etti'::text,'kontrol eder'::text,'O su sebiline gitmeden önce doktor boğazını kontrol etmişti.'::text),
(396423,44047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az orvos ... a torkát, mielőtt a srác a vízadagolóhoz ment.'::text,'megvizsgálta'::text,'megvizsgálta'::text,'vizsgálja'::text,'Az orvos megvizsgálta a torkát, mielőtt a srác a vízadagolóhoz ment.'::text),
(396426,44048,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich spaßig: Wenn die Ärztin seine Zunge noch mal runterdrückt, ... sich sein Hals wund an.'::text,'fühlt'::text,'würde'::text,'fühlte'::text,'Offensichtlich spaßig: Wenn die Ärztin seine Zunge noch mal runterdrückt, fühlt sich sein Hals wund an.'::text),
(396430,44048,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно весело: якщо лікарка знову натисне йому на язик, у нього ... горло.'::text,'болітиме'::text,'боліло б'::text,'боліло'::text,'Явно весело: якщо лікарка знову натисне йому на язик, у нього болітиме горло.'::text),
(396429,44048,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diversión garantizada: si la doctora le vuelve a aplastar la lengua, le ... la garganta.'::text,'dolerá'::text,'dolería'::text,'dolió'::text,'Diversión garantizada: si la doctora le vuelve a aplastar la lengua, le dolerá la garganta.'::text),
(396428,44048,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement amusant : si la médecin lui appuie encore sur la langue, il ... mal à la gorge.'::text,'aura'::text,'aurait'::text,'avait'::text,'Clairement amusant : si la médecin lui appuie encore sur la langue, il aura mal à la gorge.'::text),
(396431,44048,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki çok eğlenceli: doktor dilini yine bastırırsa, boğazı ...'::text,'acıyacak'::text,'acırdı'::text,'acıdı'::text,'Belli ki çok eğlenceli: doktor dilini yine bastırırsa, boğazı acıyacak.'::text),
(396432,44048,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvalóan szórakoztató: ha az orvos megint lenyomja a nyelvét, ... a torka.'::text,'fájni fog'::text,'fájna'::text,'fájt'::text,'Nyilvánvalóan szórakoztató: ha az orvos megint lenyomja a nyelvét, fájni fog a torka.'::text),
(396435,44049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn mein Hals so trocken wäre, ... ich den ganzen Wasserspender leer, echt.'::text,'tränke'::text,'trinke'::text,'trinke'::text,'Alter, wenn mein Hals so trocken wäre, tränke ich den ganzen Wasserspender leer, echt.'::text),
(396439,44049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якби в мене було таке сухе горло, я ... весь кулер, чесно.'::text,'випив би'::text,'вип''ю'::text,'п''ю'::text,'Чувак, якби в мене було таке сухе горло, я випив би весь кулер, чесно.'::text),
(396438,44049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si tuviera la garganta así de seca, ... todo el dispensador de agua, en serio.'::text,'me bebería'::text,'me beberé'::text,'me bebo'::text,'Tío, si tuviera la garganta así de seca, me bebería todo el dispensador de agua, en serio.'::text),
(396437,44049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, si j''avais la gorge aussi sèche, je ... toute la fontaine à eau, sérieux.'::text,'boirais'::text,'boirai'::text,'bois'::text,'Mec, si j''avais la gorge aussi sèche, je boirais toute la fontaine à eau, sérieux.'::text),
(396440,44049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, boğazım o kadar kuru olsaydı, bütün su sebilini ..., cidden.'::text,'içerdim'::text,'içeceğim'::text,'içerim'::text,'Kanka, boğazım o kadar kuru olsaydı, bütün su sebilini içerdim, cidden.'::text),
(396441,44049,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha ilyen száraz lenne a torkom, ... az egész vízadagolót, komolyan.'::text,'kiinnám'::text,'kiiszom'::text,'iszom'::text,'Haver, ha ilyen száraz lenne a torkom, kiinnám az egész vízadagolót, komolyan.'::text),
(396444,44050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Hals ... von der Ärztin mit einem Holzspatel untersucht.'::text,'wurde'::text,'wird'::text,'hat'::text,'Sein Hals wurde von der Ärztin mit einem Holzspatel untersucht.'::text),
(396448,44050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його горло ... лікаркою за допомогою дерев''яної палички.'::text,'було оглянуто'::text,'оглядають'::text,'оглянуло'::text,'Його горло було оглянуто лікаркою за допомогою дерев''яної палички.'::text),
(396447,44050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su garganta ... por la doctora con un palito de madera.'::text,'fue revisada'::text,'es revisada'::text,'revisó'::text,'Su garganta fue revisada por la doctora con un palito de madera.'::text),
(396446,44050,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa gorge ... par la médecin avec un bâtonnet en bois.'::text,'a été examinée'::text,'est examinée'::text,'a examiné'::text,'Sa gorge a été examinée par la médecin avec un bâtonnet en bois.'::text),
(396449,44050,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boğazı doktor tarafından tahta bir çubukla ...'::text,'kontrol edildi'::text,'kontrol ediliyor'::text,'kontrol etti'::text,'Boğazı doktor tarafından tahta bir çubukla kontrol edildi.'::text),
(396450,44050,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A torkát az orvos ... egy fa spatulával.'::text,'vizsgálta meg'::text,'vizsgálja meg'::text,'megvizsgálta'::text,'A torkát az orvos vizsgálta meg egy fa spatulával.'::text),
(396453,44051,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ärztin ... vor ihrer Deadline um 17 Uhr 20 Hälse.'::text,'untersuchte'::text,'wurde untersucht'::text,'untersuchend'::text,'Die Ärztin untersuchte vor ihrer Deadline um 17 Uhr 20 Hälse.'::text),
(396457,44051,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лікарка ... 20 горлянок до свого дедлайну о 17:00.'::text,'оглянула'::text,'була оглянута'::text,'оглядаючи'::text,'Лікарка оглянула 20 горлянок до свого дедлайну о 17:00.'::text),
(396456,44051,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La doctora ... 20 gargantas antes de su fecha límite de las 17:00.'::text,'revisó'::text,'fue revisada'::text,'revisando'::text,'La doctora revisó 20 gargantas antes de su fecha límite de las 17:00.'::text),
(396455,44051,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La médecin ... 20 gorges avant sa deadline de 17 h.'::text,'a examiné'::text,'a été examinée'::text,'examinant'::text,'La médecin a examiné 20 gorges avant sa deadline de 17 h.'::text),
(396458,44051,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doktor saat 17.00''deki son teslim saatinden önce 20 boğazı ...'::text,'kontrol etti'::text,'kontrol edildi'::text,'kontrol ederek'::text,'Doktor saat 17.00''deki son teslim saatinden önce 20 boğazı kontrol etti.'::text),
(396459,44051,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az orvos a délután 5-ös határidő előtt 20 torkot ...'::text,'vizsgált meg'::text,'meg lett vizsgálva'::text,'vizsgálva'::text,'Az orvos a délután 5-ös határidő előtt 20 torkot vizsgált meg.'::text),
(396462,44052,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er trinkt und fasst sich an die Brust, also ... sein Hals trocken sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Er trinkt und fasst sich an die Brust, also muss sein Hals trocken sein.'::text),
(396466,44052,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він п''є і торкається грудей, тож горло в нього ... сухе.'::text,'напевно'::text,'аж ніяк не'::text,'мабуть'::text,'Він п''є і торкається грудей, тож горло в нього напевно сухе.'::text),
(396465,44052,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebe y se toca el pecho, así que su garganta ... estar seca.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Bebe y se toca el pecho, así que su garganta debe de estar seca.'::text),
(396464,44052,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il boit et se touche la poitrine, donc sa gorge ... être sèche.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Il boit et se touche la poitrine, donc sa gorge doit être sèche.'::text),
(396467,44052,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su içiyor ve göğsüne dokunuyor, yani boğazı kuru ...'::text,'olmalı'::text,'olamaz'::text,'olması lazım'::text,'Su içiyor ve göğsüne dokunuyor, yani boğazı kuru olmalı.'::text),
(396468,44052,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Iszik és a mellkasához nyúl, szóval a torka ... száraz.'::text,'biztosan'::text,'biztosan nem'::text,'valószínűleg'::text,'Iszik és a mellkasához nyúl, szóval a torka biztosan száraz.'::text),
(396480,44054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er erzählte der Ärztin, sein Hals ... die ganze Nacht gebrannt! Pure Qual!'::text,'habe'::text,'hat'::text,'brennt'::text,'Er erzählte der Ärztin, sein Hals habe die ganze Nacht gebrannt! Pure Qual!'::text),
(396484,44054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав лікарці, що горло ... всю ніч! Справжня агонія!'::text,'пекло'::text,'пече'::text,'пече'::text,'Він сказав лікарці, що горло пекло всю ніч! Справжня агонія!'::text),
(396483,44054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Le dijo a la doctora que la garganta le ... toda la noche! ¡Pura agonía!'::text,'había estado ardiendo'::text,'ha estado ardiendo'::text,'está ardiendo'::text,'¡Le dijo a la doctora que la garganta le había estado ardiendo toda la noche! ¡Pura agonía!'::text),
(396482,44054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit à la médecin que sa gorge le ... toute la nuit ! Une vraie torture !'::text,'brûlait'::text,'brûle'::text,'brûle'::text,'Il a dit à la médecin que sa gorge le brûlait toute la nuit ! Une vraie torture !'::text),
(396485,44054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doktora boğazının bütün gece ... söyledi! Tam bir işkence!'::text,'yandığını'::text,'yandığını'::text,'yanıyor olduğunu'::text,'Doktora boğazının bütün gece yandığını söyledi! Tam bir işkence!'::text),
(396486,44054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elmondta az orvosnak, hogy egész éjjel ... a torka! Tiszta kínszenvedés!'::text,'égett'::text,'ég'::text,'ég'::text,'Elmondta az orvosnak, hogy egész éjjel égett a torka! Tiszta kínszenvedés!'::text),
(396489,44055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kind ... ihm jeden Winter der Hals weh! Das Allerschlimmste!'::text,'tat'::text,'tat'::text,'war gewohnt'::text,'Als Kind tat ihm jeden Winter der Hals weh! Das Allerschlimmste!'::text),
(396493,44055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві горло в нього щозими ...! Найгірше, що може бути!'::text,'боліло'::text,'боліло'::text,'звикло боліти'::text,'У дитинстві горло в нього щозими боліло! Найгірше, що може бути!'::text),
(396492,44055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡De pequeño, la garganta le ... cada invierno! ¡Lo peor de lo peor!'::text,'dolía'::text,'solía doler'::text,'estaba acostumbrada a doler'::text,'¡De pequeño, la garganta le dolía cada invierno! ¡Lo peor de lo peor!'::text),
(396491,44055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfant, il ... mal à la gorge chaque hiver ! Le pire du pire !'::text,'avait'::text,'avait'::text,'était habitué à avoir'::text,'Enfant, il avait mal à la gorge chaque hiver ! Le pire du pire !'::text),
(396494,44055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken her kış boğazı ...! Resmen en kötüsü!'::text,'ağrırdı'::text,'ağrırdı'::text,'ağrımaya alışkındı'::text,'Çocukken her kış boğazı ağrırdı! Resmen en kötüsü!'::text),
(396495,44055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekkorában minden télen ... a torka! A lehető legrosszabb!'::text,'fájt'::text,'szokott fájni'::text,'hozzá volt szokva, hogy fájjon'::text,'Gyerekkorában minden télen fájt a torka! A lehető legrosszabb!'::text),
(396498,44056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er muss Wasser ..., um seinem trockenen Hals zu helfen.'::text,'trinken'::text,'Trinken'::text,'trinkt'::text,'Er muss Wasser trinken, um seinem trockenen Hals zu helfen.'::text),
(396502,44056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому треба ... воду, щоб допомогти сухому горлу.'::text,'випити'::text,'пиття'::text,'п''є'::text,'Йому треба випити воду, щоб допомогти сухому горлу.'::text),
(396501,44056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Necesita ... agua para ayudar a su garganta seca.'::text,'beber'::text,'bebiendo'::text,'bebe'::text,'Necesita beber agua para ayudar a su garganta seca.'::text),
(396500,44056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a besoin de ... de l''eau pour soulager sa gorge sèche.'::text,'boire'::text,'buvant'::text,'boit'::text,'Il a besoin de boire de l''eau pour soulager sa gorge sèche.'::text),
(396503,44056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuru boğazına iyi gelmesi için su ... gerekiyor.'::text,'içmesi'::text,'içme'::text,'içer'::text,'Kuru boğazına iyi gelmesi için su içmesi gerekiyor.'::text),
(396504,44056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vizet kell ..., hogy segítsen a száraz torkán.'::text,'innia'::text,'ivás'::text,'iszik'::text,'Vizet kell innia, hogy segítsen a száraz torkán.'::text),
(397164,44130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kleinkind ... gerade über den Teppich, als es sich hinsetzte, also hörte es auf zu laufen.'::text,'lief'::text,'lief'::text,'ist gelaufen'::text,'Das Kleinkind lief gerade über den Teppich, als es sich hinsetzte, also hörte es auf zu laufen.'::text),
(397168,44130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Малеча ... по килиму, коли сіла, тож перестала ходити.'::text,'йшла'::text,'пройшла'::text,'пройшла'::text,'Малеча йшла по килиму, коли сіла, тож перестала ходити.'::text),
(397167,44130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La niña pequeña ... por la alfombra cuando se sentó, así que dejó de andar.'::text,'estaba caminando'::text,'caminó'::text,'ha caminado'::text,'La niña pequeña estaba caminando por la alfombra cuando se sentó, así que dejó de andar.'::text),
(397166,44130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La petite ... sur le tapis quand elle s''est assise, alors elle a arrêté de marcher.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'La petite marchait sur le tapis quand elle s''est assise, alors elle a arrêté de marcher.'::text),
(397169,44130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebek oturduğunda halının üstünde ..., o yüzden yürümeyi bıraktı.'::text,'yürüyordu'::text,'yürüdü'::text,'yürümüş'::text,'Bebek oturduğunda halının üstünde yürüyordu, o yüzden yürümeyi bıraktı.'::text),
(397170,44130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A totyogó kislány éppen ... a szőnyegen, amikor leült, így abbahagyta a járást.'::text,'sétált'::text,'átsétált'::text,'átsétált'::text,'A totyogó kislány éppen sétált a szőnyegen, amikor leült, így abbahagyta a járást.'::text),
(397173,44131,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise ... das Kleinkind seit etwa zehn Minuten Schritte ohne Hilfe.'::text,'macht'::text,'macht'::text,'macht'::text,'Bemerkenswerterweise macht das Kleinkind seit etwa zehn Minuten Schritte ohne Hilfe.'::text),
(397177,44131,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що малюк ... самостійні кроки приблизно десять хвилин.'::text,'робить'::text,'робить'::text,'робить'::text,'Примітно, що малюк робить самостійні кроки приблизно десять хвилин.'::text),
(397176,44131,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sorprendentemente, la niña ... pasos sin apoyo durante aproximadamente diez minutos.'::text,'lleva dando'::text,'está dando'::text,'da'::text,'Sorprendentemente, la niña lleva dando pasos sin apoyo durante aproximadamente diez minutos.'::text),
(397175,44131,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, le tout-petit ... des pas sans appui depuis environ dix minutes.'::text,'fait'::text,'fait'::text,'fait'::text,'Fait remarquable, le tout-petit fait des pas sans appui depuis environ dix minutes.'::text),
(397178,44131,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde, yürümeye yeni başlayan çocuk yaklaşık on dakikadır desteksiz adımlar ...'::text,'atıyor'::text,'atıyor'::text,'atar'::text,'Dikkat çekici biçimde, yürümeye yeni başlayan çocuk yaklaşık on dakikadır desteksiz adımlar atıyor.'::text),
(397179,44131,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó módon a kisgyermek körülbelül tíz perce ... támasz nélküli lépéseket.'::text,'tesz'::text,'tesz'::text,'tesz'::text,'Figyelemre méltó módon a kisgyermek körülbelül tíz perce tesz támasz nélküli lépéseket.'::text),
(397182,44132,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In dem Moment, als das Kleinkind seinen ersten Schritt ..., haben die Eltern buchstäblich geschrien!'::text,'machte'::text,'machte gerade'::text,'hat gemacht'::text,'In dem Moment, als das Kleinkind seinen ersten Schritt machte, haben die Eltern buchstäblich geschrien!'::text),
(397186,44132,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно малеча ... свій перший крок, батьки буквально закричали!'::text,'зробила'::text,'робила'::text,'зробила'::text,'Щойно малеча зробила свій перший крок, батьки буквально закричали!'::text),
(397185,44132,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En cuanto la niña ... su primer paso, sus padres literalmente gritaron!'::text,'dio'::text,'estaba dando'::text,'ha dado'::text,'¡En cuanto la niña dio su primer paso, sus padres literalmente gritaron!'::text),
(397184,44132,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où la petite ... son premier pas, ses parents ont littéralement hurlé !'::text,'a fait'::text,'faisait'::text,'a fait'::text,'Au moment où la petite a fait son premier pas, ses parents ont littéralement hurlé !'::text),
(397187,44132,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebek ilk adımını ... anda anne babası resmen çığlık attı!'::text,'attığı'::text,'atmakta olduğu'::text,'atmış olduğu'::text,'Bebek ilk adımını attığı anda anne babası resmen çığlık attı!'::text),
(397188,44132,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abban a pillanatban, amikor a kicsi ... az első lépését, a szülei szó szerint felsikoltottak!'::text,'megtette'::text,'tette'::text,'megtette'::text,'Abban a pillanatban, amikor a kicsi megtette az első lépését, a szülei szó szerint felsikoltottak!'::text),
(397191,44133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Kleinkind ... schon drei Schritte gemacht, und der ganze Raum dreht komplett durch!'::text,'hat'::text,'hat'::text,'machte'::text,'Dieses Kleinkind hat schon drei Schritte gemacht, und der ganze Raum dreht komplett durch!'::text),
(397195,44133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця малеча вже ... три кроки, і вся кімната геть божеволіє!'::text,'зробила'::text,'робить'::text,'зробила'::text,'Ця малеча вже зробила три кроки, і вся кімната геть божеволіє!'::text),
(397194,44133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta niña ya ... tres pasos y toda la sala está perdiendo la cabeza!'::text,'ha dado'::text,'ha estado dando'::text,'dio'::text,'¡Esta niña ya ha dado tres pasos y toda la sala está perdiendo la cabeza!'::text),
(397193,44133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette petite ... déjà trois pas, et toute la pièce devient complètement folle !'::text,'a fait'::text,'fait'::text,'fit'::text,'Cette petite a fait déjà trois pas, et toute la pièce devient complètement folle !'::text),
(397196,44133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu bebek şimdiden üç adım ... ve bütün oda tamamen çıldırıyor!'::text,'attı'::text,'atıyor'::text,'attı'::text,'Bu bebek şimdiden üç adım attı ve bütün oda tamamen çıldırıyor!'::text),
(397197,44133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a kicsi már három lépést ..., és az egész szoba teljesen megőrül!'::text,'tett'::text,'tesz'::text,'tett'::text,'Ez a kicsi már három lépést tett, és az egész szoba teljesen megőrül!'::text),
(397200,44134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Kleinkind bei ihnen ankam, ... die Eltern ihre Stimme komplett verloren!'::text,'hatten'::text,'verloren'::text,'haben'::text,'Als das Kleinkind bei ihnen ankam, hatten die Eltern ihre Stimme komplett verloren!'::text),
(397204,44134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки малеча до них дійшла, батьки вже геть ... голос!'::text,'зірвали'::text,'зірвали'::text,'зірвали'::text,'Поки малеча до них дійшла, батьки вже геть зірвали голос!'::text),
(397203,44134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando la niña llegó hasta ellos, sus padres ... la voz por completo!'::text,'habían perdido'::text,'perdieron'::text,'han perdido'::text,'¡Para cuando la niña llegó hasta ellos, sus padres habían perdido la voz por completo!'::text),
(397202,44134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que la petite les atteigne, ses parents ... complètement la voix !'::text,'avaient perdu'::text,'perdirent'::text,'ont perdu'::text,'Le temps que la petite les atteigne, ses parents avaient perdu complètement la voix !'::text),
(397205,44134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebek yanlarına vardığında anne babasının sesi tamamen ...!'::text,'kısılmıştı'::text,'kısıldı'::text,'kısıldı'::text,'Bebek yanlarına vardığında anne babasının sesi tamamen kısılmıştı!'::text),
(397206,44134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kicsi odaért hozzájuk, a szülei teljesen ... a hangjukat!'::text,'elvesztették'::text,'elvesztették'::text,'elvesztették'::text,'Mire a kicsi odaért hozzájuk, a szülei teljesen elvesztették a hangjukat!'::text),
(397209,44135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich wird das Kleinkind nächsten Monat um diese Zeit schon durchs ganze Haus ...'::text,'rennen'::text,'rennen'::text,'rennt'::text,'Hör zu, angeblich wird das Kleinkind nächsten Monat um diese Zeit schon durchs ganze Haus rennen.'::text),
(397213,44135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, наступного місяця в цей час малеча ... по всьому дому.'::text,'бігатиме'::text,'бігатиме'::text,'бігає'::text,'Слухай, кажуть, наступного місяця в цей час малеча бігатиме по всьому дому.'::text),
(397212,44135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer el mes que viene a estas horas la niña ... por toda la casa.'::text,'estará corriendo'::text,'correrá'::text,'corre'::text,'Oye, al parecer el mes que viene a estas horas la niña estará corriendo por toda la casa.'::text),
(397211,44135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment le mois prochain à cette heure-ci, la petite ... partout dans la maison.'::text,'sera en train de courir'::text,'courra'::text,'court'::text,'Écoute, apparemment le mois prochain à cette heure-ci, la petite sera en train de courir partout dans la maison.'::text),
(397214,44135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre gelecek ay bu zamanlar bebek bütün evde ...'::text,'koşuyor olacakmış'::text,'koşacakmış'::text,'koşuyormuş'::text,'Dinle, duyduğuma göre gelecek ay bu zamanlar bebek bütün evde koşuyor olacakmış.'::text),
(397215,44135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag jövő hónapban ilyenkor a kicsi már az egész házban ...'::text,'rohangálni fog'::text,'rohangál majd'::text,'rohangál'::text,'Figyelj, állítólag jövő hónapban ilyenkor a kicsi már az egész házban rohangálni fog.'::text),
(397227,44137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Kleinkind seine ersten Schritte ..., klatschen die Erwachsenen um es herum meistens.'::text,'macht'::text,'machte'::text,'machen wird'::text,'Wenn ein Kleinkind seine ersten Schritte macht, klatschen die Erwachsenen um es herum meistens.'::text),
(397231,44137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли малеча ... свої перші кроки, дорослі навколо зазвичай плескають.'::text,'робить'::text,'зробила'::text,'зробить'::text,'Коли малеча робить свої перші кроки, дорослі навколо зазвичай плескають.'::text),
(397230,44137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una niña pequeña ... sus primeros pasos, los adultos que la rodean suelen aplaudir.'::text,'da'::text,'dio'::text,'dará'::text,'Si una niña pequeña da sus primeros pasos, los adultos que la rodean suelen aplaudir.'::text),
(397229,44137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand un tout-petit ... ses premiers pas, les adultes autour applaudissent en général.'::text,'fait'::text,'fit'::text,'fera'::text,'Quand un tout-petit fait ses premiers pas, les adultes autour applaudissent en général.'::text),
(397232,44137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir bebek ilk adımlarını ..., etrafındaki yetişkinler genellikle alkışlar.'::text,'atarsa'::text,'attıysa'::text,'atacaksa'::text,'Bir bebek ilk adımlarını atarsa, etrafındaki yetişkinler genellikle alkışlar.'::text),
(397233,44137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy kisgyerek ... az első lépéseit, a körülötte lévő felnőttek általában tapsolnak.'::text,'megteszi'::text,'megtette'::text,'meg fogja tenni'::text,'Ha egy kisgyerek megteszi az első lépéseit, a körülötte lévő felnőttek általában tapsolnak.'::text),
(397236,44138,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Kleinkind seine Eltern erreicht, ... sie es ganz fest in den Arm.'::text,'nehmen'::text,'würden nehmen'::text,'nahmen'::text,'Wenn das Kleinkind seine Eltern erreicht, nehmen sie es ganz fest in den Arm.'::text),
(397240,44138,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо малеча дійде до батьків, вони ... її міцно-міцно.'::text,'обіймуть'::text,'обійняли б'::text,'обійняли'::text,'Якщо малеча дійде до батьків, вони обіймуть її міцно-міцно.'::text),
(397239,44138,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la niña llega hasta sus padres, ellos le ... un abrazo enorme.'::text,'darán'::text,'darían'::text,'dieron'::text,'Si la niña llega hasta sus padres, ellos le darán un abrazo enorme.'::text),
(397238,44138,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la petite atteint ses parents, ils lui ... un gros câlin.'::text,'feront'::text,'feraient'::text,'firent'::text,'Si la petite atteint ses parents, ils lui feront un gros câlin.'::text),
(397241,44138,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bebek anne babasına ulaşırsa, ona kocaman ...'::text,'sarılacaklar'::text,'sarılırlardı'::text,'sarıldılar'::text,'Bebek anne babasına ulaşırsa, ona kocaman sarılacaklar.'::text),
(397242,44138,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kicsi eléri a szüleit, ... őt jó szorosan.'::text,'megölelik'::text,'megölelnék'::text,'megölelték'::text,'Ha a kicsi eléri a szüleit, megölelik őt jó szorosan.'::text),
(397245,44139,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... das Kleinkind langsam auf seine Eltern zu, die klatschen.'::text,'geht'::text,'geht'::text,'ist gegangen'::text,'Gerade geht das Kleinkind langsam auf seine Eltern zu, die klatschen.'::text),
(397249,44139,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз малеча повільно ... до батьків, які плескають.'::text,'прямує'::text,'прямує'::text,'попрямувала'::text,'Саме зараз малеча повільно прямує до батьків, які плескають.'::text),
(397248,44139,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo la niña ... despacio hacia sus padres, que están aplaudiendo.'::text,'se dirige'::text,'se dirige'::text,'se ha dirigido'::text,'Ahora mismo la niña se dirige despacio hacia sus padres, que están aplaudiendo.'::text),
(397247,44139,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la petite ... lentement vers ses parents, qui applaudissent.'::text,'se dirige'::text,'se dirige'::text,'s''est dirigée'::text,'En ce moment, la petite se dirige lentement vers ses parents, qui applaudissent.'::text),
(397250,44139,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda bebek, alkışlayan anne babasına doğru yavaşça ...'::text,'ilerliyor'::text,'ilerler'::text,'ilerledi'::text,'Şu anda bebek, alkışlayan anne babasına doğru yavaşça ilerliyor.'::text),
(397251,44139,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kicsi most éppen lassan ... a szülei felé, akik tapsolnak.'::text,'halad'::text,'halad'::text,'haladt'::text,'A kicsi most éppen lassan halad a szülei felé, akik tapsolnak.'::text),
(394959,43885,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Tube des Mannes voll wäre, ... er auch eine große Spirale machen.'::text,'würde'::text,'wird'::text,'macht'::text,'Wenn die Tube des Mannes voll wäre, würde er auch eine große Spirale machen.'::text),
(394963,43885,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби тюбик у хлопця був повний, він теж ... велику спіраль.'::text,'зробив би'::text,'зробить'::text,'робить'::text,'Якби тюбик у хлопця був повний, він теж зробив би велику спіраль.'::text),
(394962,43885,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el tubo del chico estuviera lleno, él también ... una espiral grande.'::text,'haría'::text,'hará'::text,'hace'::text,'Si el tubo del chico estuviera lleno, él también haría una espiral grande.'::text),
(394961,43885,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le tube de l''homme était plein, il ... aussi une grosse spirale.'::text,'ferait'::text,'fera'::text,'fait'::text,'Si le tube de l''homme était plein, il ferait aussi une grosse spirale.'::text),
(394964,43885,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamın tüpü dolu olsaydı, o da büyük bir sarmal ...'::text,'yapardı'::text,'yapacak'::text,'yapıyor'::text,'Adamın tüpü dolu olsaydı, o da büyük bir sarmal yapardı.'::text),
(394965,43885,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a férfi tubusa tele lenne, ő is ... egy nagy spirált.'::text,'csinálna'::text,'csinál majd'::text,'csinál'::text,'Ha a férfi tubusa tele lenne, ő is csinálna egy nagy spirált.'::text),
(394968,43886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine dicke Spirale Minzpaste ... nacheinander auf jede Zahnbürste gedrückt.'::text,'wurde'::text,'drückte'::text,'drückte gerade'::text,'Eine dicke Spirale Minzpaste wurde nacheinander auf jede Zahnbürste gedrückt.'::text),
(394972,43886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Густу спіраль м''ятної пасти ... на кожну щітку, одну за одною.'::text,'видавили'::text,'видавила'::text,'видавлювала'::text,'Густу спіраль м''ятної пасти видавили на кожну щітку, одну за одною.'::text),
(394971,43886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una espiral gruesa de pasta de menta ... sobre cada cepillo, uno tras otro.'::text,'fue exprimida'::text,'exprimió'::text,'estaba exprimiendo'::text,'Una espiral gruesa de pasta de menta fue exprimida sobre cada cepillo, uno tras otro.'::text),
(394970,43886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une épaisse spirale de dentifrice à la menthe ... sur chaque brosse, l''une après l''autre.'::text,'a été pressée'::text,'a pressé'::text,'pressait'::text,'Une épaisse spirale de dentifrice à la menthe a été pressée sur chaque brosse, l''une après l''autre.'::text),
(394973,43886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her fırçanın üstüne sırayla kalın bir sarmal naneli macun ...'::text,'sıkıldı'::text,'sıktı'::text,'sıkıyordu'::text,'Her fırçanın üstüne sırayla kalın bir sarmal naneli macun sıkıldı.'::text),
(394974,43886,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vastag spirál mentás fogkrémet ... minden fogkefére, egymás után.'::text,'nyomtak'::text,'nyomott'::text,'nyomott éppen'::text,'Vastag spirál mentás fogkrémet nyomtak minden fogkefére, egymás után.'::text),
(394986,43888,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Tube ist fast leer, also ... da nicht genug Paste für eine Spirale sein.'::text,'kann'::text,'muss'::text,'sollte'::text,'Seine Tube ist fast leer, also kann da nicht genug Paste für eine Spirale sein.'::text),
(394990,43888,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його тюбик майже порожній, тож там ... достатньо пасти для спіралі.'::text,'точно не буде'::text,'точно буде'::text,'мало б бути'::text,'Його тюбик майже порожній, тож там точно не буде достатньо пасти для спіралі.'::text),
(394989,43888,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su tubo está casi vacío, así que ... haber suficiente pasta para una espiral.'::text,'no puede'::text,'debe de'::text,'debería'::text,'Su tubo está casi vacío, así que no puede haber suficiente pasta para una espiral.'::text),
(394988,43888,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tube est presque vide, donc il ... y avoir assez de dentifrice pour une spirale.'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'Son tube est presque vide, donc il ne peut pas y avoir assez de dentifrice pour une spirale.'::text),
(394991,43888,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüpü neredeyse boş, yani bir sarmal için yeterli macun ...'::text,'olamaz'::text,'olmalı'::text,'olması lazım'::text,'Tüpü neredeyse boş, yani bir sarmal için yeterli macun olamaz.'::text),
(394992,43888,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tubusa majdnem üres, szóval ... elég fogkrém egy spirálhoz.'::text,'biztosan nincs'::text,'biztosan van'::text,'elvileg van'::text,'A tubusa majdnem üres, szóval biztosan nincs elég fogkrém egy spirálhoz.'::text),
(394995,43889,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, das Mädchen, ... diese riesigen Spiralen gemacht hat, ist lowkey komplett durch.'::text,'das'::text,'welches'::text,'dessen'::text,'Yo, das Mädchen, das diese riesigen Spiralen gemacht hat, ist lowkey komplett durch.'::text),
(394999,43889,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, дівчина, ... зробила ці гігантські спіралі, трохи неадекватна.'::text,'яка'::text,'котра'::text,'чия'::text,'Йо, дівчина, яка зробила ці гігантські спіралі, трохи неадекватна.'::text),
