(394997,43889,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, la meuf ... a fait ces spirales géantes est un peu perchée.'::text,'qui'::text,'laquelle'::text,'dont'::text,'Yo, la meuf qui a fait ces spirales géantes est un peu perchée.'::text),
(395000,43889,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, o dev sarmalları ... kız biraz kafayı yemiş.'::text,'yapan'::text,'yapan'::text,'yaptığı'::text,'Yo, o dev sarmalları yapan kız biraz kafayı yemiş.'::text),
(395001,43889,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jó, az a csaj, ... azokat az óriási spirálokat csinálta, kicsit elborult.'::text,'aki'::text,'amelyik'::text,'akinek'::text,'Jó, az a csaj, aki azokat az óriási spirálokat csinálta, kicsit elborult.'::text),
(395004,43890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Meeting sagte sie, sie ... auf jede Zahnbürste eine 4-Zentimeter-Spirale.'::text,'gäbe'::text,'wird geben'::text,'gibt'::text,'Im Meeting sagte sie, sie gäbe auf jede Zahnbürste eine 4-Zentimeter-Spirale.'::text),
(395008,43890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На нараді вона сказала, що ... на кожну щітку спіраль у 4 сантиметри.'::text,'нанесе'::text,'нанесе'::text,'наносить'::text,'На нараді вона сказала, що нанесе на кожну щітку спіраль у 4 сантиметри.'::text),
(395007,43890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la reunión, dijo que ... una espiral de 4 centímetros en cada cepillo.'::text,'pondría'::text,'pondrá'::text,'pone'::text,'En la reunión, dijo que pondría una espiral de 4 centímetros en cada cepillo.'::text),
(395006,43890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En réunion, elle a dit qu''elle ... une spirale de 4 centimètres sur chaque brosse.'::text,'mettrait'::text,'mettra'::text,'met'::text,'En réunion, elle a dit qu''elle mettrait une spirale de 4 centimètres sur chaque brosse.'::text),
(395009,43890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantıda her fırçaya 4 santimlik bir sarmal ... söyledi.'::text,'koyacağını'::text,'koyacağını'::text,'koyduğunu'::text,'Toplantıda her fırçaya 4 santimlik bir sarmal koyacağını söyledi.'::text),
(395010,43890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A megbeszélésen azt mondta, hogy minden fogkefére egy 4 centis spirált ...'::text,'tesz'::text,'fog tenni'::text,'tesz'::text,'A megbeszélésen azt mondta, hogy minden fogkefére egy 4 centis spirált tesz.'::text),
(395013,43891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Tube ... voll. Deshalb hat sie damals größere Spiralen gemacht.'::text,'war früher'::text,'war früher'::text,'war es gewohnt zu sein'::text,'Seine Tube war früher voll. Deshalb hat sie damals größere Spiralen gemacht.'::text),
(395017,43891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його тюбик ... повним. Ось чому тоді виходили більші спіралі.'::text,'колись був'::text,'колись був'::text,'звик бути'::text,'Його тюбик колись був повним. Ось чому тоді виходили більші спіралі.'::text),
(395016,43891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su tubo ... estar lleno. Por eso hacía espirales más grandes entonces.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Su tubo solía estar lleno. Por eso hacía espirales más grandes entonces.'::text),
(395015,43891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tube ... plein avant. C''est pour ça qu''il faisait de plus grosses spirales à l''époque.'::text,'était'::text,'était'::text,'avait l''habitude d''être'::text,'Son tube était plein avant. C''est pour ça qu''il faisait de plus grosses spirales à l''époque.'::text),
(395018,43891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüpü eskiden ..., o yüzden o zamanlar daha büyük sarmallar yapıyordu.'::text,'doluydu'::text,'dolu olurdu'::text,'dolu olmaya alışkındı'::text,'Tüpü eskiden doluydu, o yüzden o zamanlar daha büyük sarmallar yapıyordu.'::text),
(395019,43891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a tubusa. Ezért csinált akkoriban nagyobb spirálokat.'::text,'tele volt'::text,'tele szokott lenni'::text,'hozzá volt szokva, hogy tele legyen'::text,'Régen tele volt a tubusa. Ezért csinált akkoriban nagyobb spirálokat.'::text),
(395022,43892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt genießt es offenbar, auf jeder Zahnbürste eine dicke Spirale Paste zu ...'::text,'formen'::text,'formen'::text,'formt'::text,'Das Subjekt genießt es offenbar, auf jeder Zahnbürste eine dicke Spirale Paste zu formen.'::text),
(395026,43892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт, очевидно, отримує задоволення від того, що ... густу спіраль пасти на кожній щітці.'::text,'формує'::text,'формувати'::text,'формує'::text,'Суб''єкт, очевидно, отримує задоволення від того, що формує густу спіраль пасти на кожній щітці.'::text),
(395025,43892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto evidentemente disfruta ... una gruesa espiral de pasta en cada cepillo.'::text,'formando'::text,'formar'::text,'forma'::text,'El sujeto evidentemente disfruta formando una gruesa espiral de pasta en cada cepillo.'::text),
(395024,43892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet prend manifestement plaisir à ... une épaisse spirale de dentifrice sur chaque brosse.'::text,'former'::text,'de former'::text,'forme'::text,'Le sujet prend manifestement plaisir à former une épaisse spirale de dentifrice sur chaque brosse.'::text),
