(374128,41570,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли прийшли туристи, колони там уже ..., бо колони не ходять.'::text,'стояли'::text,'стоять'::text,'стояли'::text,'Коли прийшли туристи, колони там уже стояли, бо колони не ходять.'::text),
(374127,41570,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando llegaron los turistas, las columnas ya ... allí, porque las columnas no caminan.'::text,'habían estado'::text,'han estado'::text,'estuvieron'::text,'Cuando llegaron los turistas, las columnas ya habían estado allí, porque las columnas no caminan.'::text),
(374126,41570,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand les touristes sont arrivés, les colonnes ... déjà là, parce que les colonnes ne marchent pas.'::text,'étaient'::text,'sont'::text,'furent'::text,'Quand les touristes sont arrivés, les colonnes étaient déjà là, parce que les colonnes ne marchent pas.'::text),
(374129,41570,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turistler geldiğinde sütunlar zaten orada ..., çünkü sütunlar yürümez.'::text,'duruyordu'::text,'duruyor'::text,'durdu'::text,'Turistler geldiğinde sütunlar zaten orada duruyordu, çünkü sütunlar yürümez.'::text),
(374130,41570,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a turisták megérkeztek, az oszlopok már ott ..., mert az oszlopok nem sétálnak.'::text,'álltak'::text,'állnak'::text,'álltak'::text,'Mire a turisták megérkeztek, az oszlopok már ott álltak, mert az oszlopok nem sétálnak.'::text),
(374133,41571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Säule unter ihrer Last ..., stürzt die Konstruktion darüber typischerweise ein.'::text,'versagt'::text,'versagen wird'::text,'versagte'::text,'Wenn eine Säule unter ihrer Last versagt, stürzt die Konstruktion darüber typischerweise ein.'::text),
(374137,41571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо колона ... під навантаженням, конструкція над нею зазвичай обвалиться.'::text,'не витримає'::text,'не витримуватиме'::text,'не витримала'::text,'Якщо колона не витримає під навантаженням, конструкція над нею зазвичай обвалиться.'::text),
(374136,41571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un pilar ... bajo su carga, la estructura que sostiene normalmente se derrumbará.'::text,'falla'::text,'fallará'::text,'falló'::text,'Si un pilar falla bajo su carga, la estructura que sostiene normalmente se derrumbará.'::text),
(374135,41571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un pilier ... sous sa charge, la structure au-dessus s''effondrera généralement.'::text,'cède'::text,'cédera'::text,'céda'::text,'Si un pilier cède sous sa charge, la structure au-dessus s''effondrera généralement.'::text),
(374138,41571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sütun yükü altında ..., üzerindeki yapı genellikle çöker.'::text,'çökerse'::text,'çökecekse'::text,'çöktüyse'::text,'Bir sütun yükü altında çökerse, üzerindeki yapı genellikle çöker.'::text),
(374139,41571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy oszlop ... a terhelés alatt, a fölötte lévő szerkezet jellemzően összeomlik.'::text,'enged'::text,'engedni fog'::text,'engedett'::text,'Ha egy oszlop enged a terhelés alatt, a fölötte lévő szerkezet jellemzően összeomlik.'::text),
(374142,41572,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sind normalerweise stabil, aber diese hier haben absolut alles überlebt!'::text,'Säulen'::text,'Die Säulen'::text,'Eine Säule'::text,'Säulen sind normalerweise stabil, aber diese hier haben absolut alles überlebt!'::text),
(374146,41572,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... зазвичай міцні, але ці пережили абсолютно все!'::text,'Колони'::text,'Колони'::text,'Колона'::text,'Колони зазвичай міцні, але ці пережили абсолютно все!'::text),
(374145,41572,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... suelen ser resistentes, pero estas han sobrevivido absolutamente a todo!'::text,'Las columnas'::text,'Las columnas'::text,'Una columna'::text,'¡Las columnas suelen ser resistentes, pero estas han sobrevivido absolutamente a todo!'::text),
(374144,41572,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sont généralement solides, mais celles-ci ont survécu à absolument tout !'::text,'Les colonnes'::text,'Les colonnes'::text,'Une colonne'::text,'Les colonnes sont généralement solides, mais celles-ci ont survécu à absolument tout !'::text),
(374147,41572,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... genelde sağlamdır, ama bunlar kesinlikle her şeye dayandı!'::text,'Sütunlar'::text,'Sütunlar'::text,'Bir sütun'::text,'Sütunlar genelde sağlamdır, ama bunlar kesinlikle her şeye dayandı!'::text),
(374148,41572,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... általában erősek, de ezek abszolút mindent túléltek!'::text,'Az oszlopok'::text,'Az oszlopok'::text,'Egy oszlop'::text,'Az oszlopok általában erősek, de ezek abszolút mindent túléltek!'::text),
(374151,41573,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wusste, ihr Handy ... vor der letzten Säule sterben. Eine totale Katastrophe!'::text,'würde'::text,'wird'::text,'war dabei'::text,'Sie wusste, ihr Handy würde vor der letzten Säule sterben. Eine totale Katastrophe!'::text),
(374155,41573,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знала, що її телефон ... перед останньою колоною. Повна катастрофа!'::text,'сяде'::text,'сяде'::text,'збирався сісти'::text,'Вона знала, що її телефон сяде перед останньою колоною. Повна катастрофа!'::text),
(374154,41573,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que su móvil ... antes de la última columna. ¡Un desastre total!'::text,'se moriría'::text,'se morirá'::text,'iba a morirse'::text,'Sabía que su móvil se moriría antes de la última columna. ¡Un desastre total!'::text),
(374153,41573,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle savait que son téléphone ... avant la dernière colonne. Un désastre total !'::text,'mourrait'::text,'mourra'::text,'allait mourir'::text,'Elle savait que son téléphone mourrait avant la dernière colonne. Un désastre total !'::text),
(374156,41573,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefonunun son sütundan önce ... biliyordu. Tam bir felaket!'::text,'öleceğini'::text,'öleceğini'::text,'ölmek üzere olduğunu'::text,'Telefonunun son sütundan önce öleceğini biliyordu. Tam bir felaket!'::text),
(374157,41573,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy a telefonja ... az utolsó oszlop előtt. Totális katasztrófa!'::text,'le fog merülni'::text,'le fog merülni'::text,'épp lemerülni készült'::text,'Tudta, hogy a telefonja le fog merülni az utolsó oszlop előtt. Totális katasztrófa!'::text),
(374169,41575,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... sich jemand gerade an eine Säule, als der Guide mit dem Schirm wegging.'::text,'lehnte'::text,'hat gelehnt'::text,'lehnt'::text,'Hör zu, angeblich lehnte sich jemand gerade an eine Säule, als der Guide mit dem Schirm wegging.'::text),
(374173,41575,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, хтось ... на колону, коли гід пішов з парасолькою.'::text,'спирався'::text,'сперся'::text,'спирається'::text,'Слухай, кажуть, хтось спирався на колону, коли гід пішов з парасолькою.'::text),
(374172,41575,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dicen que alguien ... en una columna cuando el guía se fue con el paraguas.'::text,'estaba apoyado'::text,'se ha apoyado'::text,'se apoya'::text,'Oye, dicen que alguien estaba apoyado en una columna cuando el guía se fue con el paraguas.'::text),
(374171,41575,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît que quelqu''un ... contre une colonne quand le guide est parti avec le parapluie.'::text,'était appuyé'::text,'s''est appuyé'::text,'s''appuie'::text,'Écoute, il paraît que quelqu''un était appuyé contre une colonne quand le guide est parti avec le parapluie.'::text),
(374174,41575,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre rehber şemsiyeyle uzaklaştığında biri bir sütuna ...'::text,'yaslanıyormuş'::text,'yaslanmış'::text,'yaslanıyor'::text,'Dinle, duyduğuma göre rehber şemsiyeyle uzaklaştığında biri bir sütuna yaslanıyormuş.'::text),
(374175,41575,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy valaki éppen egy oszlopnak ..., amikor az idegenvezető elsétált az esernyővel.'::text,'támaszkodott'::text,'nekitámaszkodott'::text,'támaszkodik'::text,'Figyelj, azt hallottam, hogy valaki éppen egy oszlopnak támaszkodott, amikor az idegenvezető elsétált az esernyővel.'::text),
(374178,41576,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, angeblich ... sie bis Sonnenuntergang jede einzelne Säule auf dem Hügel fotografiert.'::text,'haben'::text,'werden'::text,'fotografieren'::text,'Ok also, angeblich haben sie bis Sonnenuntergang jede einzelne Säule auf dem Hügel fotografiert.'::text),
(374182,41576,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, кажуть, до заходу сонця вони ... кожну колону на тому пагорбі.'::text,'сфотографують'::text,'фотографуватимуть'::text,'фотографують'::text,'Окей, кажуть, до заходу сонця вони сфотографують кожну колону на тому пагорбі.'::text),
(374181,41576,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, pues al parecer para el atardecer ... todas y cada una de las columnas de esa colina.'::text,'habrán fotografiado'::text,'fotografiarán'::text,'fotografían'::text,'Ok, pues al parecer para el atardecer habrán fotografiado todas y cada una de las columnas de esa colina.'::text),
(374180,41576,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok alors, apparemment d''ici le coucher du soleil ils ... chaque colonne de cette colline.'::text,'auront photographié'::text,'photographieront'::text,'photographient'::text,'Ok alors, apparemment d''ici le coucher du soleil ils auront photographié chaque colonne de cette colline.'::text),
(374183,41576,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre gün batımına kadar o tepedeki her bir sütunu ...'::text,'fotoğraflamış olacaklarmış'::text,'fotoğraflayacaklarmış'::text,'fotoğraflıyorlarmış'::text,'Tamam, duyduğuma göre gün batımına kadar o tepedeki her bir sütunu fotoğraflamış olacaklarmış.'::text),
(374184,41576,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag napnyugtáig azon a dombon minden egyes oszlopot ...'::text,'lefotóznak'::text,'fotózni fognak'::text,'fotóznak'::text,'Oké, szóval állítólag napnyugtáig azon a dombon minden egyes oszlopot lefotóznak.'::text),
(378120,42014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Fußgängerbrücke kein Geländer hätte, ... er nicht so nah am Rand.'::text,'stünde'::text,'wird stehen'::text,'steht'::text,'Wenn die Fußgängerbrücke kein Geländer hätte, stünde er nicht so nah am Rand.'::text),
(378124,42014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби на пішохідному мості не було поруччя, він ... так близько до краю.'::text,'не стояв би'::text,'не стоятиме'::text,'не стоїть'::text,'Якби на пішохідному мості не було поруччя, він не стояв би так близько до краю.'::text),
(378123,42014,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pasarela no tuviera barandilla, él no ... tan cerca del borde.'::text,'estaría'::text,'estará'::text,'está'::text,'Si la pasarela no tuviera barandilla, él no estaría tan cerca del borde.'::text),
(378122,42014,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la passerelle n''avait pas de rambarde, il ne ... pas si près du bord.'::text,'se tiendrait'::text,'se tiendra'::text,'se tient'::text,'Si la passerelle n''avait pas de rambarde, il ne se tiendrait pas si près du bord.'::text),
(378125,42014,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üst geçidin korkuluğu olmasaydı, kenara bu kadar yakın ...'::text,'durmazdı'::text,'durmayacak'::text,'durmuyor'::text,'Üst geçidin korkuluğu olmasaydı, kenara bu kadar yakın durmazdı.'::text),
(378126,42014,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a gyalogoshídnak nem lenne korlátja, ... ilyen közel a széléhez.'::text,'nem állna'::text,'nem fog állni'::text,'nem áll'::text,'Ha a gyalogoshídnak nem lenne korlátja, nem állna ilyen közel a széléhez.'::text),
(378129,42015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich ... das Geländer gebaut, damit er einen makellosen Stau bewundern konnte.'::text,'wurde'::text,'baute'::text,'wird'::text,'Natürlich wurde das Geländer gebaut, damit er einen makellosen Stau bewundern konnte.'::text),
(378133,42015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, поруччя ..., щоб він міг милуватися бездоганним затором.'::text,'збудували'::text,'збудувало'::text,'будують'::text,'Звісно, поруччя збудували, щоб він міг милуватися бездоганним затором.'::text),
(378132,42015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Por supuesto, la barandilla ... para que él pudiera admirar un atasco impecable.'::text,'fue construida'::text,'construyó'::text,'es construida'::text,'Por supuesto, la barandilla fue construida para que él pudiera admirar un atasco impecable.'::text),
(378131,42015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien sûr, la rambarde ... pour qu''il puisse admirer un embouteillage parfait.'::text,'a été construite'::text,'a construit'::text,'est construite'::text,'Bien sûr, la rambarde a été construite pour qu''il puisse admirer un embouteillage parfait.'::text),
(378134,42015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki korkuluk, kusursuz bir trafik sıkışıklığını izleyebilsin diye ...'::text,'yapıldı'::text,'yaptı'::text,'yapılıyor'::text,'Tabii ki korkuluk, kusursuz bir trafik sıkışıklığını izleyebilsin diye yapıldı.'::text),
(378135,42015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hát persze, a korlátot azért ..., hogy megcsodálhasson egy tökéletes dugót.'::text,'építették'::text,'építette'::text,'építik'::text,'Hát persze, a korlátot azért építették, hogy megcsodálhasson egy tökéletes dugót.'::text),
(378138,42016,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Metallgeländer mit beiden Händen, während sich der Albtraum-Stau endlos hinzog!'::text,'umklammerte'::text,'wurde umklammert'::text,'umklammernd'::text,'Er umklammerte das Metallgeländer mit beiden Händen, während sich der Albtraum-Stau endlos hinzog!'::text),
(378142,42016,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... металеве поруччя обома руками, поки жахливий затор тягнувся нескінченно!'::text,'стиснув'::text,'був стиснутий'::text,'стискаючи'::text,'Він стиснув металеве поруччя обома руками, поки жахливий затор тягнувся нескінченно!'::text),
(378141,42016,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... la barandilla de metal con las dos manos mientras el atasco de pesadilla no se acababa nunca!'::text,'agarró'::text,'fue agarrado'::text,'agarrando'::text,'¡Él agarró la barandilla de metal con las dos manos mientras el atasco de pesadilla no se acababa nunca!'::text),
(378140,42016,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la rambarde en métal à deux mains pendant que l''embouteillage cauchemardesque s''étirait à l''infini !'::text,'a agrippé'::text,'a été agrippé'::text,'agrippant'::text,'Il a agrippé la rambarde en métal à deux mains pendant que l''embouteillage cauchemardesque s''étirait à l''infini !'::text),
(378143,42016,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus gibi trafik sonsuza dek uzarken metal korkuluğu iki eliyle ...!'::text,'kavradı'::text,'kavrandı'::text,'kavrayarak'::text,'Kâbus gibi trafik sonsuza dek uzarken metal korkuluğu iki eliyle kavradı!'::text),
(378144,42016,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két kézzel ... a fém korlátot, miközben a rémálomszerű dugó a végtelenségig nyúlt!'::text,'markolta'::text,'markolva volt'::text,'markolva'::text,'Két kézzel markolta a fém korlátot, miközben a rémálomszerű dugó a végtelenségig nyúlt!'::text),
(378156,42018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, angeblich hat der Junge, ... das Geländer festhielt, den ganzen Stau von oben gesehen.'::text,'der'::text,'welcher'::text,'dessen'::text,'Süße, angeblich hat der Junge, der das Geländer festhielt, den ganzen Stau von oben gesehen.'::text),
(378160,42018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, хлопець, ... тримався за поруччя, бачив увесь затор згори.'::text,'який'::text,'котрий'::text,'чий'::text,'Подруго, кажуть, хлопець, який тримався за поруччя, бачив увесь затор згори.'::text),
(378159,42018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el chico ... se agarraba a la barandilla vio todo el atasco desde arriba.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Tía, al parecer el chico que se agarraba a la barandilla vio todo el atasco desde arriba.'::text),
(378158,42018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le garçon ... tenait la rambarde a vu tout l''embouteillage d''en haut.'::text,'qui'::text,'lequel'::text,'dont'::text,'Meuf, apparemment le garçon qui tenait la rambarde a vu tout l''embouteillage d''en haut.'::text),
(378161,42018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre korkuluğu ... çocuk bütün trafiği yukarıdan görmüş.'::text,'tutan'::text,'tutan'::text,'tuttuğu'::text,'Kızım, duyduğuma göre korkuluğu tutan çocuk bütün trafiği yukarıdan görmüş.'::text),
(378162,42018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a srác, ... a korlátot fogta, fentről látta az egész dugót.'::text,'aki'::text,'amelyik'::text,'akinek'::text,'Csajszi, állítólag a srác, aki a korlátot fogta, fentről látta az egész dugót.'::text),
(378165,42019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, dass er sich jeden einzelnen Morgen am Geländer dieser Brücke ...'::text,'festhielt'::text,'festhält'::text,'festgehalten hat'::text,'Hör zu, er hat mir erzählt, dass er sich jeden einzelnen Morgen am Geländer dieser Brücke festhielt.'::text),
(378169,42019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що ... за поруччя того мосту кожного ранку.'::text,'тримається'::text,'тримається'::text,'тримався'::text,'Слухай, він сказав мені, що тримається за поруччя того мосту кожного ранку.'::text),
(378168,42019,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que ... la barandilla de esa pasarela todas las mañanas.'::text,'agarraba'::text,'agarra'::text,'ha agarrado'::text,'Oye, me dijo que agarraba la barandilla de esa pasarela todas las mañanas.'::text),
(378167,42019,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il ... la rambarde de cette passerelle chaque matin.'::text,'tenait'::text,'tient'::text,'a tenu'::text,'Écoute, il m''a dit qu''il tenait la rambarde de cette passerelle chaque matin.'::text),
(378170,42019,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana her sabah o üst geçidin korkuluğunu ... söyledi.'::text,'tuttuğunu'::text,'tuttuğunu'::text,'tutmuş olduğunu'::text,'Dinle, bana her sabah o üst geçidin korkuluğunu tuttuğunu söyledi.'::text),
(378171,42019,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta nekem, hogy minden egyes reggel ... annak a hídnak a korlátját.'::text,'fogja'::text,'fogja'::text,'fogta'::text,'Figyelj, azt mondta nekem, hogy minden egyes reggel fogja annak a hídnak a korlátját.'::text),
(378174,42020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, diese Brücke ... früher kein Geländer, und das war schon ziemlich sus.'::text,'hatte'::text,'hatte'::text,'war gewohnt'::text,'Nee Bro, diese Brücke hatte früher kein Geländer, und das war schon ziemlich sus.'::text),
(378178,42020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не-а, бро, цей міст ... поруччя, і це було якось підозріло.'::text,'раніше не мав'::text,'раніше не мав'::text,'не звик мати'::text,'Не-а, бро, цей міст раніше не мав поруччя, і це було якось підозріло.'::text),
(378177,42020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, esta pasarela no ... tener barandilla, y eso era un poco sospechoso.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Qué va, bro, esta pasarela no solía tener barandilla, y eso era un poco sospechoso.'::text),
(378176,42020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, cette passerelle ... pas de rambarde avant, et c''était un peu louche.'::text,'n''avait'::text,'n''avait'::text,'n''était pas habituée à avoir'::text,'Nan frérot, cette passerelle n''avait pas de rambarde avant, et c''était un peu louche.'::text),
(378179,42020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bu üst geçidin eskiden korkuluğu ..., ve bu biraz şüpheliydi.'::text,'yoktu'::text,'olmazdı'::text,'olmamaya alışkındı'::text,'Yok kanka, bu üst geçidin eskiden korkuluğu yoktu, ve bu biraz şüpheliydi.'::text),
(378180,42020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, ennek a gyalogoshídnak régen ... korlátja, és ez elég gyanús volt.'::text,'nem volt'::text,'nem volt'::text,'nem szokott lenni'::text,'Á, tesó, ennek a gyalogoshídnak régen nem volt korlátja, és ez elég gyanús volt.'::text),
(378183,42021,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kleine hat einfach weiter das Geländer ... und auf den Stau gestarrt, kein Witz.'::text,'festgehalten'::text,'festzuhalten'::text,'festhalten'::text,'Der Kleine hat einfach weiter das Geländer festgehalten und auf den Stau gestarrt, kein Witz.'::text),
(378187,42021,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Малий просто далі ... за поруччя і витріщався на затор, без брехні.'::text,'тримався'::text,'триматися'::text,'тримається'::text,'Малий просто далі тримався за поруччя і витріщався на затор, без брехні.'::text),
(378186,42021,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El peque siguió ... la barandilla y mirando el atasco, en serio.'::text,'agarrando'::text,'agarrar'::text,'agarra'::text,'El peque siguió agarrando la barandilla y mirando el atasco, en serio.'::text),
(378185,42021,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit a continué à ... la rambarde en fixant l''embouteillage, sans mentir.'::text,'tenir'::text,'de tenir'::text,'tient'::text,'Le petit a continué à tenir la rambarde en fixant l''embouteillage, sans mentir.'::text),
(378188,42021,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ufaklık korkuluğu ... ve trafiğe bakmaya devam etti, yemin ederim.'::text,'tutmaya'::text,'tutmak'::text,'tut'::text,'Ufaklık korkuluğu tutmaya ve trafiğe bakmaya devam etti, yemin ederim.'::text),
(378189,42021,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis tesó csak ... a korlátot és bámulta a dugót, komolyan.'::text,'fogta tovább'::text,'fogni'::text,'fogja'::text,'A kis tesó csak fogta tovább a korlátot és bámulta a dugót, komolyan.'::text),
(378192,42022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Metallgeländer verläuft über die ganze Brücke, ...?'::text,'oder'::text,'nicht wahr'::text,'oder etwa nicht'::text,'Das Metallgeländer verläuft über die ganze Brücke, oder?'::text),
(378196,42022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Металеве поруччя тягнеться вздовж усього мосту, ...?'::text,'так'::text,'правда'::text,'хіба ні'::text,'Металеве поруччя тягнеться вздовж усього мосту, так?'::text),
(378195,42022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La barandilla de metal recorre toda la pasarela, ¿...?'::text,'verdad'::text,'no'::text,'eh'::text,'La barandilla de metal recorre toda la pasarela, ¿verdad?'::text),
(378194,42022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rambarde en métal longe toute la passerelle, ... ?'::text,'n''est-ce pas'::text,'non'::text,'hein'::text,'La rambarde en métal longe toute la passerelle, n''est-ce pas ?'::text),
(378197,42022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Metal korkuluk bütün üst geçit boyunca uzanıyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil miydi'::text,'Metal korkuluk bütün üst geçit boyunca uzanıyor, değil mi?'::text),
(378198,42022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fém korlát végigfut az egész hídon, ...?'::text,'ugye'::text,'nem igaz'::text,'nem így volt'::text,'A fém korlát végigfut az egész hídon, ugye?'::text),
(378201,42023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Junge das Geländer mit beiden Händen.'::text,'umklammert'::text,'umklammert'::text,'hat umklammert'::text,'Gerade umklammert der Junge das Geländer mit beiden Händen.'::text),
(378205,42023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз хлопець ... поруччя обома руками.'::text,'стискає'::text,'стискає'::text,'стиснув'::text,'Саме зараз хлопець стискає поруччя обома руками.'::text),
(378204,42023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo, el chico ... la barandilla con las dos manos.'::text,'está agarrando'::text,'agarra'::text,'ha agarrado'::text,'Ahora mismo, el chico está agarrando la barandilla con las dos manos.'::text),
(378203,42023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le garçon ... la rambarde à deux mains.'::text,'agrippe'::text,'agrippe'::text,'a agrippé'::text,'En ce moment, le garçon agrippe la rambarde à deux mains.'::text),
(378206,42023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda çocuk korkuluğu iki eliyle ...'::text,'kavrıyor'::text,'kavrar'::text,'kavradı'::text,'Şu anda çocuk korkuluğu iki eliyle kavrıyor.'::text),
(378207,42023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A srác most éppen két kézzel ... a korlátot.'::text,'markolja'::text,'markolja'::text,'megmarkolta'::text,'A srác most éppen két kézzel markolja a korlátot.'::text),
(366186,40688,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich ein ganz ruhiger Fan: Bis Mittag ... sie jeder Lok am Bahnhof zugewunken.'::text,'hat'::text,'wird'::text,'wird'::text,'Offensichtlich ein ganz ruhiger Fan: Bis Mittag hat sie jeder Lok am Bahnhof zugewunken.'::text),
(366190,40688,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, спокійна фанатка: до обіду вона ... кожному локомотиву на вокзалі.'::text,'вже помахає'::text,'помахає'::text,'махатиме'::text,'Очевидно, спокійна фанатка: до обіду вона вже помахає кожному локомотиву на вокзалі.'::text),
(366189,40688,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una fan tranquila, obviamente: para el mediodía ... a todas las locomotoras de la estación.'::text,'habrá saludado'::text,'saludará'::text,'estará saludando'::text,'Una fan tranquila, obviamente: para el mediodía habrá saludado a todas las locomotoras de la estación.'::text),
(366188,40688,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fan très calme, évidemment : d''ici midi, elle ... à chaque locomotive de la gare.'::text,'aura fait coucou'::text,'fera coucou'::text,'sera en train de faire coucou'::text,'Une fan très calme, évidemment : d''ici midi, elle aura fait coucou à chaque locomotive de la gare.'::text),
(366191,40688,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sakin bir hayran: öğlene kadar istasyondaki her lokomotife el ...'::text,'sallamış olacak'::text,'sallayacak'::text,'sallıyor olacak'::text,'Belli ki sakin bir hayran: öğlene kadar istasyondaki her lokomotife el sallamış olacak.'::text),
(366192,40688,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván nagyon nyugodt rajongó: délre az állomás minden mozdonyának ...'::text,'már integetett'::text,'integetni fog'::text,'éppen integetni fog'::text,'Nyilván nagyon nyugodt rajongó: délre az állomás minden mozdonyának már integetett.'::text),
(366195,40689,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nur leicht aufgeregt: Wenn die Lok angehalten hätte, ... sie sie umarmt.'::text,'hätte'::text,'wird'::text,'umarmte'::text,'Nur leicht aufgeregt: Wenn die Lok angehalten hätte, hätte sie sie umarmt.'::text),
(366199,40689,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи схвильована: якби локомотив зупинився, вона ... його.'::text,'обійняла б'::text,'обійме'::text,'обійняла'::text,'Трохи схвильована: якби локомотив зупинився, вона обійняла б його.'::text),
(366198,40689,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ligeramente emocionada: si la locomotora se hubiera detenido, ella le ... un abrazo.'::text,'habría dado'::text,'dará'::text,'dio'::text,'Ligeramente emocionada: si la locomotora se hubiera detenido, ella le habría dado un abrazo.'::text),
(366197,40689,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Légèrement excitée : si la locomotive s''était arrêtée, elle lui ... un câlin.'::text,'aurait fait'::text,'fera'::text,'fit'::text,'Légèrement excitée : si la locomotive s''était arrêtée, elle lui aurait fait un câlin.'::text),
(366200,40689,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hafifçe heyecanlı: lokomotif dursaydı, ona ...'::text,'sarılırdı'::text,'sarılacak'::text,'sarıldı'::text,'Hafifçe heyecanlı: lokomotif dursaydı, ona sarılırdı.'::text),
(366201,40689,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enyhén izgatott: ha a mozdony megállt volna, ... azt.'::text,'megölelte volna'::text,'megöleli'::text,'megölelte'::text,'Enyhén izgatott: ha a mozdony megállt volna, megölelte volna azt.'::text),
(366204,40690,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig kein Fan: Sie bestritt, die orange Lok ...'::text,'angelächelt zu haben'::text,'anzulächeln'::text,'lächelte an'::text,'Eindeutig kein Fan: Sie bestritt, die orange Lok angelächelt zu haben.'::text),
(366208,40690,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно не фанатка, вона заперечила, що ... до помаранчевого локомотива.'::text,'усміхалася'::text,'усміхатися'::text,'усміхнулася'::text,'Явно не фанатка, вона заперечила, що усміхалася до помаранчевого локомотива.'::text),
(366207,40690,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente nada fan, negó ... a la locomotora naranja.'::text,'haberle sonreído'::text,'sonreír'::text,'sonrió'::text,'Claramente nada fan, negó haberle sonreído a la locomotora naranja.'::text),
(366206,40690,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement pas fan, elle a nié ... à la locomotive orange.'::text,'avoir souri'::text,'sourire'::text,'a souri'::text,'Clairement pas fan, elle a nié avoir souri à la locomotive orange.'::text),
(366209,40690,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki hayran değil, turuncu lokomotife ... inkâr etti.'::text,'gülümsediğini'::text,'gülümsemeyi'::text,'gülümsedi'::text,'Belli ki hayran değil, turuncu lokomotife gülümsediğini inkâr etti.'::text),
(366210,40690,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen nem rajongó: tagadta, hogy ... a narancssárga mozdonyra.'::text,'mosolygott'::text,'mosolyogni'::text,'mosolygott'::text,'Egyértelműen nem rajongó: tagadta, hogy mosolygott a narancssárga mozdonyra.'::text),
(366213,40691,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihre Kamera mitbringen sollen! Die orange Lok war ihr großer Moment, und er ist für immer vorbei!'::text,'hätte'::text,'muss'::text,'soll'::text,'Sie hätte ihre Kamera mitbringen sollen! Die orange Lok war ihr großer Moment, und er ist für immer vorbei!'::text),
(366217,40691,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй ... фотоапарат! Той помаранчевий локомотив був її великим моментом, і він зник назавжди!'::text,'варто було взяти'::text,'мабуть, довелося взяти'::text,'варто взяти'::text,'Їй варто було взяти фотоапарат! Той помаранчевий локомотив був її великим моментом, і він зник назавжди!'::text),
(366216,40691,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... traído la cámara! ¡Esa locomotora naranja era su gran momento y se ha ido para siempre!'::text,'Debería haber'::text,'Debe de haber'::text,'Debería'::text,'¡Debería haber traído la cámara! ¡Esa locomotora naranja era su gran momento y se ha ido para siempre!'::text),
(366215,40691,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son appareil photo ! Cette locomotive orange, c''était son grand moment, et c''est fini pour toujours !'::text,'aurait dû apporter'::text,'a dû apporter'::text,'devrait apporter'::text,'Elle aurait dû apporter son appareil photo ! Cette locomotive orange, c''était son grand moment, et c''est fini pour toujours !'::text),
(366218,40691,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fotoğraf makinesini ...! O turuncu lokomotif onun büyük anıydı ve sonsuza dek gitti!'::text,'getirmeliydi'::text,'getirmiş olmalı'::text,'getirmeli'::text,'Fotoğraf makinesini getirmeliydi! O turuncu lokomotif onun büyük anıydı ve sonsuza dek gitti!'::text),
(366219,40691,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Magával ... a fényképezőgépét! Az a narancssárga mozdony volt a nagy pillanata, és örökre elment!'::text,'kellett volna hoznia'::text,'biztos hozta'::text,'kellene hoznia'::text,'Magával kellett volna hoznia a fényképezőgépét! Az a narancssárga mozdony volt a nagy pillanata, és örökre elment!'::text),
(366222,40692,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Verzweifelt brachte sie einen Fremden dazu, ein Foto von ihr mit der Lok ..., bevor sie verschwand!'::text,'zu machen'::text,'machen'::text,'machend'::text,'Verzweifelt brachte sie einen Fremden dazu, ein Foto von ihr mit der Lok zu machen, bevor sie verschwand!'::text),
(366226,40692,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У відчаї вона вмовила незнайомця ... їй фото з локомотивом, поки той не зник!'::text,'зробити'::text,'зробити'::text,'роблячи'::text,'У відчаї вона вмовила незнайомця зробити їй фото з локомотивом, поки той не зник!'::text),
(366225,40692,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desesperada, consiguió que un desconocido le ... una foto con la locomotora antes de que desapareciera!'::text,'hiciera'::text,'hace'::text,'haciendo'::text,'¡Desesperada, consiguió que un desconocido le hiciera una foto con la locomotora antes de que desapareciera!'::text),
(366224,40692,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Désespérée, elle a convaincu un inconnu de ... une photo d''elle avec la locomotive avant qu''elle disparaisse !'::text,'prendre'::text,'prendre'::text,'prenant'::text,'Désespérée, elle a convaincu un inconnu de prendre une photo d''elle avec la locomotive avant qu''elle disparaisse !'::text),
(366227,40692,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çaresizce, lokomotif kaybolmadan önce bir yabancının onun lokomotifle fotoğrafını ... sağladı!'::text,'çekmesini'::text,'çek'::text,'çekerek'::text,'Çaresizce, lokomotif kaybolmadan önce bir yabancının onun lokomotifle fotoğrafını çekmesini sağladı!'::text),
(366228,40692,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kétségbeesetten rávett egy idegent, hogy ... róla egy fotót a mozdonnyal, mielőtt eltűnt!'::text,'csináljon'::text,'csinál'::text,'csinálva'::text,'Kétségbeesetten rávett egy idegent, hogy csináljon róla egy fotót a mozdonnyal, mielőtt eltűnt!'::text),
(366231,40693,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich wünscht sie sich, sie ... diese orange Lok selbst fahren.'::text,'könnte'::text,'kann'::text,'fährt'::text,'Bestie, angeblich wünscht sie sich, sie könnte diese orange Lok selbst fahren.'::text),
(366235,40693,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона хотіла б, щоб ... той помаранчевий локомотив сама.'::text,'могла водити'::text,'може водити'::text,'водить'::text,'Подруго, кажуть, вона хотіла б, щоб могла водити той помаранчевий локомотив сама.'::text),
(366234,40693,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, al parecer le encantaría ... esa locomotora naranja ella misma.'::text,'poder conducir'::text,'puede conducir'::text,'conduce'::text,'Bestie, al parecer le encantaría poder conducir esa locomotora naranja ella misma.'::text),
(366233,40693,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, apparemment elle aimerait ... conduire cette locomotive orange elle-même.'::text,'pouvoir'::text,'peut'::text,'conduit'::text,'Ma bestie, apparemment elle aimerait pouvoir conduire cette locomotive orange elle-même.'::text),
(366236,40693,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre o turuncu lokomotifi kendisi ... istiyormuş.'::text,'sürebilmeyi'::text,'sürebilir'::text,'sürer'::text,'Kanka, duyduğuma göre o turuncu lokomotifi kendisi sürebilmeyi istiyormuş.'::text),
(366237,40693,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, állítólag azt szeretné, ha ő maga ... azt a narancssárga mozdonyt.'::text,'vezethetné'::text,'vezetheti'::text,'vezeti'::text,'Tesó, állítólag azt szeretné, ha ő maga vezethetné azt a narancssárga mozdonyt.'::text),
(366240,40694,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Lok, ... Farbe ein leuchtendes Orange ist, zieht die blauen Wagen.'::text,'deren'::text,'die'::text,'welche'::text,'Die Lok, deren Farbe ein leuchtendes Orange ist, zieht die blauen Wagen.'::text),
(366244,40694,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Локомотив, ... колір яскраво-помаранчевий, тягне сині вагони.'::text,'чий'::text,'який'::text,'котрий'::text,'Локомотив, чий колір яскраво-помаранчевий, тягне сині вагони.'::text),
(366243,40694,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La locomotora, ... color es naranja brillante, tira de los vagones azules.'::text,'cuyo'::text,'la cual'::text,'que'::text,'La locomotora, cuyo color es naranja brillante, tira de los vagones azules.'::text),
(366242,40694,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La locomotive, ... la couleur est orange vif, tire les voitures bleues.'::text,'dont'::text,'laquelle'::text,'qui'::text,'La locomotive, dont la couleur est orange vif, tire les voitures bleues.'::text),
(366245,40694,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rengi parlak turuncu ... lokomotif mavi vagonları çekiyor.'::text,'olan'::text,'olan'::text,'olan'::text,'Rengi parlak turuncu olan lokomotif mavi vagonları çekiyor.'::text),
(366246,40694,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mozdony, ... színe élénk narancssárga, húzza a kék kocsikat.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A mozdony, amelynek a színe élénk narancssárga, húzza a kék kocsikat.'::text),
(366249,40695,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie liebt es schon immer, mit ... zu reisen, besonders hinter einer orangen Lok.'::text,'dem Zug'::text,'dem Zug'::text,'einem Zug'::text,'Sie liebt es schon immer, mit dem Zug zu reisen, besonders hinter einer orangen Lok.'::text),
(366253,40695,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона завжди любила подорожувати ..., особливо за помаранчевим локомотивом.'::text,'потягом'::text,'потягом'::text,'потягом'::text,'Вона завжди любила подорожувати потягом, особливо за помаранчевим локомотивом.'::text),
(366252,40695,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siempre le ha encantado viajar en ..., sobre todo detrás de una locomotora naranja.'::text,'tren'::text,'el tren'::text,'un tren'::text,'Siempre le ha encantado viajar en tren, sobre todo detrás de una locomotora naranja.'::text),
(366251,40695,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a toujours adoré voyager en ..., surtout derrière une locomotive orange.'::text,'train'::text,'le train'::text,'un train'::text,'Elle a toujours adoré voyager en train, surtout derrière une locomotive orange.'::text),
(366254,40695,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Özellikle turuncu bir lokomotifin arkasında ... yolculuk yapmayı hep sevmiştir.'::text,'trenle'::text,'trenle'::text,'bir trenle'::text,'Özellikle turuncu bir lokomotifin arkasında trenle yolculuk yapmayı hep sevmiştir.'::text),
(366255,40695,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindig is imádott ... utazni, főleg egy narancssárga mozdony mögött.'::text,'vonattal'::text,'a vonattal'::text,'egy vonattal'::text,'Mindig is imádott vonattal utazni, főleg egy narancssárga mozdony mögött.'::text),
(366267,40697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, bis die Lok anhält, ... du hundert glückliche Fotos gemacht.'::text,'hast'::text,'wirst'::text,'machst'::text,'Ehrlich, bis die Lok anhält, hast du hundert glückliche Fotos gemacht.'::text),
(366271,40697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, поки локомотив зупиниться, ти ... сотню щасливих фото.'::text,'вже зробиш'::text,'зробиш'::text,'робиш'::text,'Чесно, поки локомотив зупиниться, ти вже зробиш сотню щасливих фото.'::text),
(366270,40697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, para cuando pare la locomotora, ... cien fotos felices.'::text,'habrás hecho'::text,'harás'::text,'haces'::text,'Sinceramente, para cuando pare la locomotora, habrás hecho cien fotos felices.'::text),
(366269,40697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, d''ici à ce que la locomotive s''arrête, tu ... cent photos joyeuses.'::text,'auras pris'::text,'prendras'::text,'prends'::text,'Franchement, d''ici à ce que la locomotive s''arrête, tu auras pris cent photos joyeuses.'::text),
(366272,40697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, lokomotif durana kadar yüz tane mutlu fotoğraf ...'::text,'çekmiş olacaksın'::text,'çekeceksin'::text,'çekiyorsun'::text,'Açıkçası, lokomotif durana kadar yüz tane mutlu fotoğraf çekmiş olacaksın.'::text),
(366273,40697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, mire a mozdony megáll, ... száz boldog fotót.'::text,'már készítettél'::text,'készítesz majd'::text,'készítesz'::text,'Őszintén, mire a mozdony megáll, már készítettél száz boldog fotót.'::text),
(346647,38517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Tram das Depot erreichte, ... sie schon völlig den Verstand verloren. Eine ruhige Besucherin, eindeutig.'::text,'hatte'::text,'hat'::text,'verliert'::text,'Als die Tram das Depot erreichte, hatte sie schon völlig den Verstand verloren. Eine ruhige Besucherin, eindeutig.'::text),
(346651,38517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки трамвай доїхав до депо, вона вже ... розум. Явно спокійна відвідувачка.'::text,'втратила'::text,'втратила'::text,'втрачає'::text,'Поки трамвай доїхав до депо, вона вже втратила розум. Явно спокійна відвідувачка.'::text),
(346650,38517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el tranvía llegó a la cochera, ella ya ... la cabeza. Una visitante tranquila, claramente.'::text,'había perdido'::text,'ha perdido'::text,'pierde'::text,'Para cuando el tranvía llegó a la cochera, ella ya había perdido la cabeza. Una visitante tranquila, claramente.'::text),
(346649,38517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que le tram arrive au dépôt, elle ... la tête. Une visiteuse calme, clairement.'::text,'avait perdu'::text,'a perdu'::text,'perd'::text,'Le temps que le tram arrive au dépôt, elle avait perdu la tête. Une visiteuse calme, clairement.'::text),
(346652,38517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tramvay depoya vardığında o çoktan kafayı ..., belli ki sakin bir ziyaretçi.'::text,'yemişti'::text,'yedi'::text,'yiyor'::text,'Tramvay depoya vardığında o çoktan kafayı yemişti, belli ki sakin bir ziyaretçi.'::text),
(346653,38517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a villamos beért a kocsiszínbe, ő már teljesen ... a fejét. Nyilván nyugodt látogató.'::text,'elvesztette'::text,'elvesztette'::text,'elveszti'::text,'Mire a villamos beért a kocsiszínbe, ő már teljesen elvesztette a fejét. Nyilván nyugodt látogató.'::text),
(346656,38518,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder durchs Depot. Ein zutiefst langweiliges Hobby, eindeutig.'::text,'schlendert'::text,'wird schlendern'::text,'schlendert'::text,'Morgen um diese Zeit schlendert sie wieder durchs Depot. Ein zutiefst langweiliges Hobby, eindeutig.'::text),
(346660,38518,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона знову ... по депо. Вочевидь, дуже нудне хобі.'::text,'блукатиме'::text,'поблукає'::text,'блукає'::text,'Завтра в цей час вона знову блукатиме по депо. Вочевидь, дуже нудне хобі.'::text),
(346659,38518,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a estas horas, ella ... otra vez por la cochera. Una afición profundamente aburrida, claramente.'::text,'estará paseando'::text,'paseará'::text,'pasea'::text,'Mañana a estas horas, ella estará paseando otra vez por la cochera. Una afición profundamente aburrida, claramente.'::text),
(346658,38518,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... encore dans le dépôt. Un passe-temps profondément ennuyeux, clairement.'::text,'sera en train de se balader'::text,'se baladera'::text,'se balade'::text,'Demain à la même heure, elle sera en train de se balader encore dans le dépôt. Un passe-temps profondément ennuyeux, clairement.'::text),
(346661,38518,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte yine depoda ...; belli ki derinden sıkıcı bir hobi.'::text,'dolaşıyor olacak'::text,'dolaşacak'::text,'dolaşıyor'::text,'Yarın bu saatte yine depoda dolaşıyor olacak; belli ki derinden sıkıcı bir hobi.'::text),
(346662,38518,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... a kocsiszínben. Nyilván mélységesen unalmas hobbi.'::text,'kóborolni fog'::text,'kóborol majd'::text,'kóborol'::text,'Holnap ilyenkor megint kóborolni fog a kocsiszínben. Nyilván mélységesen unalmas hobbi.'::text),
(346665,38519,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich schwöre, das ist für immer: Ich werde dieses Straßenbahndepot niemals ...!'::text,'verlassen'::text,'verlassen'::text,'verlasse'::text,'Ich schwöre, das ist für immer: Ich werde dieses Straßenbahndepot niemals verlassen!'::text),
(346669,38519,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Клянуся, це назавжди: я ... це трамвайне депо!'::text,'ніколи не покину'::text,'ніколи не покидатиму'::text,'ніколи не покидаю'::text,'Клянуся, це назавжди: я ніколи не покину це трамвайне депо!'::text),
(346668,38519,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te lo juro, esto es para siempre: ¡... de esta cochera de tranvías!'::text,'nunca me iré'::text,'nunca me estaré yendo'::text,'nunca me voy'::text,'Te lo juro, esto es para siempre: ¡nunca me iré de esta cochera de tranvías!'::text),
(346667,38519,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je le jure, c''est pour toujours : je ... ce dépôt de tramways !'::text,'ne quitterai jamais'::text,'ne serai jamais en train de quitter'::text,'ne quitte jamais'::text,'Je le jure, c''est pour toujours : je ne quitterai jamais ce dépôt de tramways !'::text),
(346670,38519,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yemin ederim, bu sonsuza dek: bu tramvay deposundan asla ...!'::text,'ayrılmayacağım'::text,'ayrılıyor olmayacağım'::text,'ayrılmam'::text,'Yemin ederim, bu sonsuza dek: bu tramvay deposundan asla ayrılmayacağım!'::text),
(346671,38519,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esküszöm, ez örökre szól: ezt a villamos-kocsiszínt soha ...!'::text,'nem hagyom el'::text,'nem fogom elhagyni'::text,'nem hagyom el'::text,'Esküszöm, ez örökre szól: ezt a villamos-kocsiszínt soha nem hagyom el!'::text),
(346674,38520,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Tram zu schnell ins Depot ..., versinkt der ganze Hof im Chaos!'::text,'rollt'::text,'rollte'::text,'rollen wird'::text,'Wenn eine Tram zu schnell ins Depot rollt, versinkt der ganze Hof im Chaos!'::text),
(346678,38520,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо трамвай ... в депо надто швидко, увесь двір поринає в хаос!'::text,'заїжджає'::text,'заїхав'::text,'заїде'::text,'Якщо трамвай заїжджає в депо надто швидко, увесь двір поринає в хаос!'::text),
(346677,38520,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si un tranvía ... en la cochera demasiado rápido, todo el patio se sume en el caos!'::text,'entra'::text,'entró'::text,'entrará'::text,'¡Si un tranvía entra en la cochera demasiado rápido, todo el patio se sume en el caos!'::text),
(346676,38520,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un tram ... trop vite dans le dépôt, toute la cour sombre dans le chaos !'::text,'entre'::text,'entra'::text,'entrera'::text,'Si un tram entre trop vite dans le dépôt, toute la cour sombre dans le chaos !'::text),
(346679,38520,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir tramvay depoya fazla hızlı ..., bütün alan kaosa sürüklenir!'::text,'girerse'::text,'girdiyse'::text,'girecekse'::text,'Bir tramvay depoya fazla hızlı girerse, bütün alan kaosa sürüklenir!'::text),
(346680,38520,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy villamos túl gyorsan ... be a kocsiszínbe, az egész udvar káoszba fullad!'::text,'gurul'::text,'gurult'::text,'gurulni fog'::text,'Ha egy villamos túl gyorsan gurul be a kocsiszínbe, az egész udvar káoszba fullad!'::text),
(346683,38521,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie in der Tram bleibt, ... die Tram sie direkt ins Depot.'::text,'bringt'::text,'würde bringen'::text,'brachte'::text,'Wenn sie in der Tram bleibt, bringt die Tram sie direkt ins Depot.'::text),
(346687,38521,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона залишиться в трамваї, він ... її прямо в депо.'::text,'завезе'::text,'завіз би'::text,'завіз'::text,'Якщо вона залишиться в трамваї, він завезе її прямо в депо.'::text),
(346686,38521,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se queda en el tranvía, este la ... directamente a la cochera.'::text,'llevará'::text,'llevaría'::text,'llevó'::text,'Si se queda en el tranvía, este la llevará directamente a la cochera.'::text),
(346685,38521,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle reste dans le tram, il ... tout droit au dépôt.'::text,'l''emmènera'::text,'l''emmènerait'::text,'l''emmena'::text,'Si elle reste dans le tram, il l''emmènera tout droit au dépôt.'::text),
(346688,38521,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tramvayda kalırsa, tramvay onu doğruca depoya ...'::text,'götürecek'::text,'götürürdü'::text,'götürdü'::text,'Tramvayda kalırsa, tramvay onu doğruca depoya götürecek.'::text),
(346689,38521,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a villamoson marad, az egyenesen a kocsiszínbe ... őt.'::text,'viszi'::text,'vinné'::text,'vitte'::text,'Ha a villamoson marad, az egyenesen a kocsiszínbe viszi őt.'::text),
(346692,38522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie im Depot arbeiten würde, ... sie jeden einzelnen Tag Straßenbahnen.'::text,'sähe'::text,'wird sehen'::text,'sieht'::text,'Wenn sie im Depot arbeiten würde, sähe sie jeden einzelnen Tag Straßenbahnen.'::text),
(346696,38522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона працювала в депо, ... трамваї кожного дня.'::text,'бачила б'::text,'побачить'::text,'бачить'::text,'Якби вона працювала в депо, бачила б трамваї кожного дня.'::text),
(346695,38522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si trabajara en la cochera, ... tranvías todos los días.'::text,'vería'::text,'verá'::text,'ve'::text,'Si trabajara en la cochera, vería tranvías todos los días.'::text),
(346694,38522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle travaillait au dépôt, elle ... des trams tous les jours.'::text,'verrait'::text,'verra'::text,'voit'::text,'Si elle travaillait au dépôt, elle verrait des trams tous les jours.'::text),
(346697,38522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depoda çalışsaydı, her gün tramvay ...'::text,'görürdü'::text,'görecek'::text,'görüyor'::text,'Depoda çalışsaydı, her gün tramvay görürdü.'::text),
(346698,38522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kocsiszínben dolgozna, minden egyes nap ... villamosokat.'::text,'látna'::text,'látni fog'::text,'lát'::text,'Ha a kocsiszínben dolgozna, minden egyes nap látna villamosokat.'::text),
(346701,38523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die alte rote Tram ... jede Nacht von den Fahrern im Depot abgestellt.'::text,'wird'::text,'stellt'::text,'abstellend'::text,'Die alte rote Tram wird jede Nacht von den Fahrern im Depot abgestellt.'::text),
(346705,38523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий червоний трамвай водії щоночі ... в депо.'::text,'паркують'::text,'паркується'::text,'паркуючи'::text,'Старий червоний трамвай водії щоночі паркують в депо.'::text),
(346704,38523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El viejo tranvía rojo ... en la cochera cada noche por los conductores.'::text,'es aparcado'::text,'aparca'::text,'aparcando'::text,'El viejo tranvía rojo es aparcado en la cochera cada noche por los conductores.'::text),
(346703,38523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieux tram rouge ... au dépôt chaque soir par les conducteurs.'::text,'est garé'::text,'se gare'::text,'garant'::text,'Le vieux tram rouge est garé au dépôt chaque soir par les conducteurs.'::text),
(346706,38523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski kırmızı tramvay her gece sürücüler tarafından depoya ...'::text,'park ediliyor'::text,'park ediyor'::text,'park ederek'::text,'Eski kırmızı tramvay her gece sürücüler tarafından depoya park ediliyor.'::text),
(346707,38523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A régi piros villamost minden éjjel ... a kocsiszínbe a vezetők.'::text,'beállítják'::text,'beáll'::text,'beállítva'::text,'A régi piros villamost minden éjjel beállítják a kocsiszínbe a vezetők.'::text),
(346719,38525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Depot, ... sie zwischen den Schienen steht, ist voller Trams.'::text,'wo'::text,'das'::text,'wer'::text,'Das Depot, wo sie zwischen den Schienen steht, ist voller Trams.'::text),
(346723,38525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Депо, ... вона стоїть між рейками, повне трамваїв.'::text,'де'::text,'яке'::text,'хто'::text,'Депо, де вона стоїть між рейками, повне трамваїв.'::text),
(346722,38525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cochera ... ella está entre los raíles está llena de tranvías.'::text,'donde'::text,'la cual'::text,'quien'::text,'La cochera donde ella está entre los raíles está llena de tranvías.'::text),
(346721,38525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dépôt ... elle se tient entre les rails est plein de trams.'::text,'où'::text,'lequel'::text,'qui'::text,'Le dépôt où elle se tient entre les rails est plein de trams.'::text),
(346724,38525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rayların arasında ... depo tramvaylarla dolu.'::text,'durduğu'::text,'durduğu'::text,'duran'::text,'Rayların arasında durduğu depo tramvaylarla dolu.'::text),
(346725,38525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kocsiszín, ... a sínek között áll, tele van villamosokkal.'::text,'ahol'::text,'amely'::text,'aki'::text,'A kocsiszín, ahol a sínek között áll, tele van villamosokkal.'::text),
(346728,38526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast mir erzählt, du ... schon mit jeder Tram in diesem Depot gefahren. Ehrlich, Respekt.'::text,'seist'::text,'bist'::text,'fährst'::text,'Du hast mir erzählt, du seist schon mit jeder Tram in diesem Depot gefahren. Ehrlich, Respekt.'::text),
(346732,38526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти казав мені, що вже ... кожним трамваєм у цьому депо. Чесно, респект.'::text,'їздив'::text,'їздив'::text,'їздиш'::text,'Ти казав мені, що вже їздив кожним трамваєм у цьому депо. Чесно, респект.'::text),
(346731,38526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me dijiste que ya ... en todos los tranvías de esta cochera. Sinceramente, respeto.'::text,'te habías subido'::text,'te has subido'::text,'te subes'::text,'Me dijiste que ya te habías subido en todos los tranvías de esta cochera. Sinceramente, respeto.'::text),
(346730,38526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu m''as dit que tu ... déjà pris chaque tram de ce dépôt. Franchement, respect.'::text,'avais'::text,'as'::text,'prends'::text,'Tu m''as dit que tu avais déjà pris chaque tram de ce dépôt. Franchement, respect.'::text),
(346733,38526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bana daha önce bu depodaki her tramvaya ... söyledin. Açıkçası, saygı.'::text,'bindiğini'::text,'bindiğini'::text,'biniyor olduğunu'::text,'Bana daha önce bu depodaki her tramvaya bindiğini söyledin. Açıkçası, saygı.'::text),
(346734,38526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy már ... ebben a kocsiszínben minden villamoson. Őszintén, respekt.'::text,'utaztál'::text,'utaztál'::text,'utazol'::text,'Azt mondtad, hogy már utaztál ebben a kocsiszínben minden villamoson. Őszintén, respekt.'::text),
(346737,38527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kind ... sie jede Nacht von Straßenbahndepots. Eindeutig eine normale Kindheit.'::text,'träumte'::text,'träumte'::text,'war es gewohnt zu träumen'::text,'Als Kind träumte sie jede Nacht von Straßenbahndepots. Eindeutig eine normale Kindheit.'::text),
(346741,38527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві вона щоночі ... про трамвайні депо. Явно нормальне дитинство.'::text,'снила'::text,'снила'::text,'звикла снити'::text,'У дитинстві вона щоночі снила про трамвайні депо. Явно нормальне дитинство.'::text),
(346740,38527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De pequeña, ... con cocheras de tranvías cada noche. Claramente una infancia normal.'::text,'soñaba'::text,'solía soñar'::text,'estaba acostumbrada a soñar'::text,'De pequeña, soñaba con cocheras de tranvías cada noche. Claramente una infancia normal.'::text),
(346739,38527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Petite, elle ... de dépôts de tramways chaque nuit. Clairement une enfance normale.'::text,'rêvait'::text,'avait l''habitude de rêver'::text,'était habituée à rêver'::text,'Petite, elle rêvait de dépôts de tramways chaque nuit. Clairement une enfance normale.'::text),
(346742,38527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken her gece tramvay depolarını rüyasında ...; belli ki normal bir çocukluk.'::text,'görürdü'::text,'görürdü'::text,'görmeye alışkındı'::text,'Çocukken her gece tramvay depolarını rüyasında görürdü; belli ki normal bir çocukluk.'::text),
(346743,38527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekként minden éjjel ... villamos-kocsiszínekről. Nyilván teljesen normális gyerekkor.'::text,'álmodott'::text,'álmodott'::text,'hozzá volt szokva álmodni'::text,'Gyerekként minden éjjel álmodott villamos-kocsiszínekről. Nyilván teljesen normális gyerekkor.'::text),
(362622,40292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie den alten Holzinnenraum ..., verschwand die Straße komplett aus ihrem Kopf!'::text,'bewunderte'::text,'bewunderte'::text,'bewundert hat'::text,'Während sie den alten Holzinnenraum bewunderte, verschwand die Straße komplett aus ihrem Kopf!'::text),
(362626,40292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... старий дерев''яний інтер''єр, вулиця геть вилетіла їй з голови!'::text,'роздивлялася'::text,'роздивилася'::text,'роздивилася'::text,'Поки вона роздивлялася старий дерев''яний інтер''єр, вулиця геть вилетіла їй з голови!'::text),
(362625,40292,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras ella ... el viejo interior de madera, la calle se le borró por completo de la cabeza!'::text,'admiraba'::text,'admiró'::text,'ha admirado'::text,'¡Mientras ella admiraba el viejo interior de madera, la calle se le borró por completo de la cabeza!'::text),
(362624,40292,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... le vieil intérieur en bois, la rue lui est complètement sortie de la tête !'::text,'admirait'::text,'admira'::text,'a admiré'::text,'Pendant qu''elle admirait le vieil intérieur en bois, la rue lui est complètement sortie de la tête !'::text),
(362627,40292,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski ahşap iç mekânı hayranlıkla ... sırada sokak aklından tamamen çıktı!'::text,'izlediği'::text,'izledi'::text,'izlemiş'::text,'Eski ahşap iç mekânı hayranlıkla izlediği sırada sokak aklından tamamen çıktı!'::text),
(362628,40292,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... a régi fa belsőt, az utca teljesen kiment a fejéből!'::text,'csodálta'::text,'csodálta'::text,'megcsodálta'::text,'Miközben csodálta a régi fa belsőt, az utca teljesen kiment a fejéből!'::text),
(362631,40293,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... schon ewig vom Holzinnenraum dieser Tram, und heute wird der Traum endlich wahr!'::text,'träumt'::text,'träumt'::text,'träumt'::text,'Sie träumt schon ewig vom Holzinnenraum dieser Tram, und heute wird der Traum endlich wahr!'::text),
(362635,40293,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... про дерев''яний інтер''єр цього трамвая відколи себе пам''ятає, і сьогодні мрія нарешті збувається!'::text,'мріє'::text,'мріє'::text,'мріє'::text,'Вона мріє про дерев''яний інтер''єр цього трамвая відколи себе пам''ятає, і сьогодні мрія нарешті збувається!'::text),
(362634,40293,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella lleva toda la vida ... con el interior de madera de este tranvía, y hoy por fin el sueño se hace realidad!'::text,'soñando'::text,'sueña'::text,'sueña'::text,'¡Ella lleva toda la vida soñando con el interior de madera de este tranvía, y hoy por fin el sueño se hace realidad!'::text),
(362633,40293,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... de l''intérieur en bois de ce tram depuis toujours, et aujourd''hui le rêve devient enfin réalité !'::text,'rêve'::text,'rêve'::text,'rêve'::text,'Elle rêve de l''intérieur en bois de ce tram depuis toujours, et aujourd''hui le rêve devient enfin réalité !'::text),
(362636,40293,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu tramvayın ahşap iç mekânını hep ... ve bugün hayal sonunda gerçek oluyor!'::text,'hayal ediyordu'::text,'hayal ediyor'::text,'hayal eder'::text,'Bu tramvayın ahşap iç mekânını hep hayal ediyordu ve bugün hayal sonunda gerçek oluyor!'::text),
(362637,40293,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő mióta csak az eszét tudja, ennek a villamosnak a fa belsejéről ..., és ma végre valóra válik az álma!'::text,'álmodik'::text,'álmodik'::text,'álmodik'::text,'Ő mióta csak az eszét tudja, ennek a villamosnak a fa belsejéről álmodik, és ma végre valóra válik az álma!'::text),
(362640,40294,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... sie gerade den Innenraum mit dem Handy, als die Tram losfuhr.'::text,'filmte'::text,'filmte'::text,'hat gefilmt'::text,'Hör zu, angeblich filmte sie gerade den Innenraum mit dem Handy, als die Tram losfuhr.'::text),
(362644,40294,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... інтер''єр на телефон, коли трамвай рушив.'::text,'знімала'::text,'зняла'::text,'зняла'::text,'Слухай, кажуть, вона знімала інтер''єр на телефон, коли трамвай рушив.'::text),
(362643,40294,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dicen que ella ... el interior con el móvil cuando el tranvía arrancó.'::text,'estaba grabando'::text,'grabó'::text,'ha grabado'::text,'Oye, dicen que ella estaba grabando el interior con el móvil cuando el tranvía arrancó.'::text),
(362642,40294,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît qu''elle ... l''intérieur avec son téléphone quand le tram a démarré.'::text,'filmait'::text,'a filmé'::text,'a filmé'::text,'Écoute, il paraît qu''elle filmait l''intérieur avec son téléphone quand le tram a démarré.'::text),
(362645,40294,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre tramvay hareket ettiğinde o iç mekânı telefonuyla ...'::text,'çekiyormuş'::text,'çekmiş'::text,'çekmiş'::text,'Dinle, duyduğuma göre tramvay hareket ettiğinde o iç mekânı telefonuyla çekiyormuş.'::text),
(362646,40294,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy éppen ... a belsőt a telefonjával, amikor a villamos elindult.'::text,'videózta'::text,'levideózta'::text,'levideózta'::text,'Figyelj, azt hallottam, hogy éppen videózta a belsőt a telefonjával, amikor a villamos elindult.'::text),
(362649,40295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, sie hat mir erzählt, dass sie diesen Monat schon sechs alte Tram-Innenräume ...'::text,'gesehen hat'::text,'gesehen hat'::text,'sieht'::text,'Ok also, sie hat mir erzählt, dass sie diesen Monat schon sechs alte Tram-Innenräume gesehen hat.'::text),
(362653,40295,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, вона сказала мені, що цього місяця ... шість старих трамвайних інтер''єрів.'::text,'бачила'::text,'бачила'::text,'бачить'::text,'Окей, вона сказала мені, що цього місяця бачила шість старих трамвайних інтер''єрів.'::text),
(362652,40295,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, pues me dijo que este mes ... seis interiores de tranvías antiguos.'::text,'ha visto'::text,'ha estado viendo'::text,'está viendo'::text,'Ok, pues me dijo que este mes ha visto seis interiores de tranvías antiguos.'::text),
(362651,40295,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok alors, elle m''a dit qu''elle ... six vieux intérieurs de tram ce mois-ci.'::text,'a vu'::text,'voit'::text,'voit'::text,'Ok alors, elle m''a dit qu''elle a vu six vieux intérieurs de tram ce mois-ci.'::text),
(362654,40295,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, bana bu ay altı tane eski tramvay iç mekânı ... söyledi.'::text,'gördüğünü'::text,'görüyor olduğunu'::text,'görüyor olduğunu'::text,'Tamam, bana bu ay altı tane eski tramvay iç mekânı gördüğünü söyledi.'::text),
(362655,40295,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval azt mondta, hogy ebben a hónapban hat régi villamosbelsőt ...'::text,'látott'::text,'látott'::text,'lát'::text,'Oké, szóval azt mondta, hogy ebben a hónapban hat régi villamosbelsőt látott.'::text),
(362658,40296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... vor der Fahrt noch nie einen so hölzernen Innenraum gesehen, kein Witz.'::text,'hatte'::text,'hat'::text,'war'::text,'Bro, sie hatte vor der Fahrt noch nie einen so hölzernen Innenraum gesehen, kein Witz.'::text),
(362662,40296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до тієї поїздки вона ... такого дерев''яного інтер''єру, без брехні.'::text,'ніколи не бачила'::text,'ніколи не бачила'::text,'ніколи не була'::text,'Бро, до тієї поїздки вона ніколи не бачила такого дерев''яного інтер''єру, без брехні.'::text),
(362661,40296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, antes de ese viaje ella nunca ... visto un interior tan de madera, en serio.'::text,'había'::text,'ha'::text,'estaba'::text,'Bro, antes de ese viaje ella nunca había visto un interior tan de madera, en serio.'::text),
(362660,40296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... jamais vu un intérieur aussi boisé avant ce trajet, sans mentir.'::text,'n''avait'::text,'n''a'::text,'n''était'::text,'Frérot, elle n''avait jamais vu un intérieur aussi boisé avant ce trajet, sans mentir.'::text),
(362663,40296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yolculuktan önce bu kadar ahşap bir iç mekân hiç ..., yemin ederim.'::text,'görmemişti'::text,'görmedi'::text,'olmamıştı'::text,'Kanka, o yolculuktan önce bu kadar ahşap bir iç mekân hiç görmemişti, yemin ederim.'::text),
(362664,40296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az előtt az út előtt még soha ... ilyen fás belsőt, komolyan.'::text,'nem látott'::text,'nem látott'::text,'nem volt'::text,'Tesó, az előtt az út előtt még soha nem látott ilyen fás belsőt, komolyan.'::text),
(362667,40297,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es regnet, ... sie im hölzernen Innenraum der Tram.'::text,'bleibt'::text,'würde bleiben'::text,'blieb'::text,'Wenn es regnet, bleibt sie im hölzernen Innenraum der Tram.'::text),
(362671,40297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо піде дощ, вона ... всередині дерев''яного інтер''єру трамвая.'::text,'залишиться'::text,'залишилася б'::text,'залишилася'::text,'Якщо піде дощ, вона залишиться всередині дерев''яного інтер''єру трамвая.'::text),
(362670,40297,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si llueve, ... dentro del interior de madera del tranvía.'::text,'se quedará'::text,'se quedaría'::text,'se quedó'::text,'Si llueve, se quedará dentro del interior de madera del tranvía.'::text),
(362669,40297,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il pleut, elle ... à l''intérieur en bois du tram.'::text,'restera'::text,'resterait'::text,'resta'::text,'S''il pleut, elle restera à l''intérieur en bois du tram.'::text),
(362672,40297,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur yağarsa tramvayın ahşap iç mekânında ...'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Yağmur yağarsa tramvayın ahşap iç mekânında kalacak.'::text),
(362673,40297,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha esik, ... a villamos fa belsejében.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha esik, marad a villamos fa belsejében.'::text),
(362676,40298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Tram einen modernen Innenraum hätte, ... sie nicht so aufgeregt.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn die Tram einen modernen Innenraum hätte, wäre sie nicht so aufgeregt.'::text),
(362680,40298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби трамвай мав сучасний інтер''єр, вона ... такою схвильованою.'::text,'не була б'::text,'не буде'::text,'не є'::text,'Якби трамвай мав сучасний інтер''єр, вона не була б такою схвильованою.'::text),
(362679,40298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el tranvía tuviera un interior moderno, ella no ... tan emocionada.'::text,'estaría'::text,'estará'::text,'está'::text,'Si el tranvía tuviera un interior moderno, ella no estaría tan emocionada.'::text),
(362678,40298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le tram avait un intérieur moderne, elle ne ... pas aussi excitée.'::text,'serait'::text,'sera'::text,'est'::text,'Si le tram avait un intérieur moderne, elle ne serait pas aussi excitée.'::text),
(362681,40298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tramvayın modern bir iç mekânı olsaydı, bu kadar heyecanlı ...'::text,'olmazdı'::text,'olmayacak'::text,'değil'::text,'Tramvayın modern bir iç mekânı olsaydı, bu kadar heyecanlı olmazdı.'::text),
(362682,40298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a villamosnak modern belseje lenne, ... ennyire izgatott.'::text,'nem lenne'::text,'nem lesz'::text,'nem'::text,'Ha a villamosnak modern belseje lenne, nem lenne ennyire izgatott.'::text),
(362685,40299,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Innenraum der Tram ... vor langer Zeit mit lackiertem Holz gebaut.'::text,'wurde'::text,'baute'::text,'wird'::text,'Der Innenraum der Tram wurde vor langer Zeit mit lackiertem Holz gebaut.'::text),
(362689,40299,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Інтер''єр трамвая ... з лакованого дерева дуже давно.'::text,'зробили'::text,'зробив'::text,'роблять'::text,'Інтер''єр трамвая зробили з лакованого дерева дуже давно.'::text),
(362688,40299,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El interior del tranvía ... con madera barnizada hace mucho tiempo.'::text,'fue construido'::text,'construyó'::text,'es construido'::text,'El interior del tranvía fue construido con madera barnizada hace mucho tiempo.'::text),
(362687,40299,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''intérieur du tram ... en bois verni il y a longtemps.'::text,'a été construit'::text,'a construit'::text,'est construit'::text,'L''intérieur du tram a été construit en bois verni il y a longtemps.'::text),
(362690,40299,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tramvayın iç mekânı uzun zaman önce vernikli ahşapla ...'::text,'yapıldı'::text,'yaptı'::text,'yapılıyor'::text,'Tramvayın iç mekânı uzun zaman önce vernikli ahşapla yapıldı.'::text),
(362691,40299,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A villamos belsejét régen lakkozott fából ...'::text,'építették'::text,'építette'::text,'építik'::text,'A villamos belsejét régen lakkozott fából építették.'::text),
(362694,40300,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine sehr ruhige Fahrt, natürlich: Sie ... den Innenraum mit einem lauten „Wuhu!“'::text,'erfüllte'::text,'wurde erfüllt'::text,'erfüllend'::text,'Eine sehr ruhige Fahrt, natürlich: Sie erfüllte den Innenraum mit einem lauten „Wuhu!“'::text),
(362698,40300,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже тиха поїздка, звісно: вона ... салон гучним «Ууу!»'::text,'наповнила'::text,'була наповнена'::text,'наповнюючи'::text,'Дуже тиха поїздка, звісно: вона наповнила салон гучним «Ууу!»'::text),
(362697,40300,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un viaje muy tranquilo, obviamente: ella ... el interior con un sonoro «¡Yuju!»'::text,'llenó'::text,'fue llenada'::text,'llenando'::text,'Un viaje muy tranquilo, obviamente: ella llenó el interior con un sonoro «¡Yuju!»'::text),
(362696,40300,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un trajet très calme, évidemment : elle ... l''intérieur d''un grand « Youhou ! »'::text,'a rempli'::text,'a été remplie'::text,'remplissant'::text,'Un trajet très calme, évidemment : elle a rempli l''intérieur d''un grand « Youhou ! »'::text),
(362699,40300,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok sessiz bir yolculuk, tabii: iç mekânı yüksek sesli bir “Vuhuu!” ile ...'::text,'doldurdu'::text,'dolduruldu'::text,'doldurarak'::text,'Çok sessiz bir yolculuk, tabii: iç mekânı yüksek sesli bir “Vuhuu!” ile doldurdu.'::text),
(362700,40300,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon csendes út, persze: egy hangos „Juhú!” kiáltással ... a belsőteret.'::text,'töltötte be'::text,'be lett töltve'::text,'betöltve'::text,'Nagyon csendes út, persze: egy hangos „Juhú!” kiáltással töltötte be a belsőteret.'::text),
(362712,40302,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tram, ... Innenraum komplett aus Holz ist, ist für sie eindeutig eine langweilige Wahl.'::text,'deren'::text,'die'::text,'wer'::text,'Die Tram, deren Innenraum komplett aus Holz ist, ist für sie eindeutig eine langweilige Wahl.'::text),
(362716,40302,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трамвай, ... інтер''єр увесь дерев''яний, для неї явно нудний вибір.'::text,'чий'::text,'який'::text,'хто'::text,'Трамвай, чий інтер''єр увесь дерев''яний, для неї явно нудний вибір.'::text),
(362715,40302,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tranvía ... interior es todo de madera es claramente una elección aburrida para ella.'::text,'cuyo'::text,'el cual'::text,'quien'::text,'El tranvía cuyo interior es todo de madera es claramente una elección aburrida para ella.'::text),
(362714,40302,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tram ... l''intérieur est tout en bois est clairement un choix ennuyeux pour elle.'::text,'dont'::text,'lequel'::text,'qui'::text,'Le tram dont l''intérieur est tout en bois est clairement un choix ennuyeux pour elle.'::text),
(362717,40302,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İç mekânı tamamen ahşap ... tramvay, belli ki onun için sıkıcı bir seçim.'::text,'olan'::text,'olan'::text,'olan'::text,'İç mekânı tamamen ahşap olan tramvay, belli ki onun için sıkıcı bir seçim.'::text),
(362718,40302,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A villamos, ... belseje csupa fa, nyilván unalmas választás számára.'::text,'amelynek a'::text,'amely'::text,'aki'::text,'A villamos, amelynek a belseje csupa fa, nyilván unalmas választás számára.'::text),
(398154,44240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, angeblich ... er bis Mittag schon seinen vierten Umstieg des Tages gemacht.'::text,'hat'::text,'wird'::text,'wird'::text,'Rate mal, angeblich hat er bis Mittag schon seinen vierten Umstieg des Tages gemacht.'::text),
(398158,44240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, до обіду він ... свою четверту пересадку за день.'::text,'вже зробить'::text,'зробить'::text,'робитиме'::text,'Уяви, кажуть, до обіду він вже зробить свою четверту пересадку за день.'::text),
(398157,44240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, he oído que para el mediodía ... su cuarto transbordo del día.'::text,'habrá hecho'::text,'hará'::text,'estará haciendo'::text,'Adivina qué, he oído que para el mediodía habrá hecho su cuarto transbordo del día.'::text),
(398156,44240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il paraît que d''ici midi il ... sa quatrième correspondance de la journée.'::text,'aura fait'::text,'fera'::text,'sera en train de faire'::text,'Devine quoi, il paraît que d''ici midi il aura fait sa quatrième correspondance de la journée.'::text),
(398159,44240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duyduğuma göre öğlene kadar günün dördüncü aktarmasını ...'::text,'yapmış olacakmış'::text,'yapacakmış'::text,'yapıyor olacakmış'::text,'Bil bakalım, duyduğuma göre öğlene kadar günün dördüncü aktarmasını yapmış olacakmış.'::text),
(398160,44240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy délre ... a nap negyedik átszállását.'::text,'már megcsinálja'::text,'megcsinálja'::text,'éppen csinálja'::text,'Képzeld, azt hallottam, hogy délre már megcsinálja a nap negyedik átszállását.'::text),
(398163,44241,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok also, angeblich ... er bis zu seinem letzten Umstieg schon eine Stunde durch die Stadt gerannt.'::text,'ist'::text,'wird'::text,'wird'::text,'Ok also, angeblich ist er bis zu seinem letzten Umstieg schon eine Stunde durch die Stadt gerannt.'::text),
(398167,44241,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, кажуть, до останньої пересадки він ... містом уже годину.'::text,'бігатиме'::text,'бігатиме'::text,'побіжить'::text,'Окей, кажуть, до останньої пересадки він бігатиме містом уже годину.'::text),
(398166,44241,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, pues supuestamente para su último transbordo ... una hora corriendo por la ciudad.'::text,'llevará'::text,'estará'::text,'correrá'::text,'Ok, pues supuestamente para su último transbordo llevará una hora corriendo por la ciudad.'::text),
(398165,44241,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok alors, soi-disant d''ici sa dernière correspondance, il ... dans toute la ville depuis une heure.'::text,'aura couru'::text,'sera en train de courir'::text,'courra'::text,'Ok alors, soi-disant d''ici sa dernière correspondance, il aura couru dans toute la ville depuis une heure.'::text),
(398168,44241,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, güya son aktarmasına kadar bir saattir şehirde ...'::text,'koşuyor olacakmış'::text,'koşuyor olacakmış'::text,'koşacakmış'::text,'Tamam, güya son aktarmasına kadar bir saattir şehirde koşuyor olacakmış.'::text),
(398169,44241,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag az utolsó átszállásáig már egy órája ... a városban.'::text,'rohangál'::text,'rohangálni fog'::text,'rohanni fog'::text,'Oké, szóval állítólag az utolsó átszállásáig már egy órája rohangál a városban.'::text),
(398172,44242,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, hätte er den Umstieg in die Tram verpasst, ... er die Fähre nicht erwischt, kein Witz.'::text,'hätte'::text,'wird'::text,'hat'::text,'Bro, hätte er den Umstieg in die Tram verpasst, hätte er die Fähre nicht erwischt, kein Witz.'::text),
(398176,44242,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби він проґавив ту пересадку на трамвай, він ... на пором, без брехні.'::text,'не встиг би'::text,'не встигне'::text,'не встиг'::text,'Бро, якби він проґавив ту пересадку на трамвай, він не встиг би на пором, без брехні.'::text),
(398175,44242,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si hubiera perdido ese transbordo al tranvía, ... el ferry, en serio.'::text,'no habría pillado'::text,'no pillará'::text,'no pilló'::text,'Bro, si hubiera perdido ese transbordo al tranvía, no habría pillado el ferry, en serio.'::text),
(398174,44242,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, s''il avait raté cette correspondance avec le tram, il ... le ferry, sans mentir.'::text,'n''aurait pas eu'::text,'n''aura pas'::text,'n''a pas eu'::text,'Frérot, s''il avait raté cette correspondance avec le tram, il n''aurait pas eu le ferry, sans mentir.'::text),
(398177,44242,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o tramvay aktarmasını kaçırsaydı, feribota ..., yemin ederim.'::text,'yetişemezdi'::text,'yetişemeyecek'::text,'yetişemedi'::text,'Kanka, o tramvay aktarmasını kaçırsaydı, feribota yetişemezdi, yemin ederim.'::text),
(398178,44242,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha lekéste volna azt a villamosátszállást, ... a kompot, komolyan.'::text,'nem érte volna el'::text,'nem éri el'::text,'nem érte el'::text,'Tesó, ha lekéste volna azt a villamosátszállást, nem érte volna el a kompot, komolyan.'::text),
(398181,44243,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wäre er nicht bei jedem Umstieg gesprintet, ... er immer noch in der U-Bahn fest, echt.'::text,'säße'::text,'hätte gesessen'::text,'sitzt'::text,'Alter, wäre er nicht bei jedem Umstieg gesprintet, säße er immer noch in der U-Bahn fest, echt.'::text),
(398185,44243,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якби він не спринтував на кожній пересадці, він досі ... в метро, чесно.'::text,'стирчав би'::text,'стирчав би'::text,'стирчатиме'::text,'Чувак, якби він не спринтував на кожній пересадці, він досі стирчав би в метро, чесно.'::text),
(398184,44243,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si no hubiera esprintado en cada transbordo, todavía ... atascado en el metro, en serio.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Tío, si no hubiera esprintado en cada transbordo, todavía estaría atascado en el metro, en serio.'::text),
(398183,44243,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, s''il n''avait pas sprinté à chaque correspondance, il ... encore coincé dans le métro, sérieux.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Mec, s''il n''avait pas sprinté à chaque correspondance, il serait encore coincé dans le métro, sérieux.'::text),
(398186,44243,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, her aktarmada koşmasaydı, hâlâ metroda mahsur ..., cidden.'::text,'kalmış olurdu'::text,'kalmış olurdu'::text,'kalacak'::text,'Kanka, her aktarmada koşmasaydı, hâlâ metroda mahsur kalmış olurdu, cidden.'::text),
(398187,44243,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha nem sprintelt volna minden átszállásnál, még mindig ... a metróban, komolyan.'::text,'rostokolna'::text,'rostokolt volna'::text,'rostokolni fog'::text,'Haver, ha nem sprintelt volna minden átszállásnál, még mindig rostokolna a metróban, komolyan.'::text),
(398199,44245,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann gab zu, den Umstieg in die Tram um nur wenige Sekunden fast ...'::text,'verpasst zu haben'::text,'zu verpassen'::text,'verpasste'::text,'Der Mann gab zu, den Umstieg in die Tram um nur wenige Sekunden fast verpasst zu haben.'::text),
(398203,44245,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік визнав, що ледь не ... пересадку на трамвай лише на кілька секунд.'::text,'проґавив'::text,'проґавити'::text,'проґавив'::text,'Чоловік визнав, що ледь не проґавив пересадку на трамвай лише на кілька секунд.'::text),
(398202,44245,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre admitió ... el transbordo al tranvía por solo unos segundos.'::text,'haber estado a punto de perder'::text,'estar a punto de perder'::text,'estuvo a punto de perder'::text,'El hombre admitió haber estado a punto de perder el transbordo al tranvía por solo unos segundos.'::text),
(398201,44245,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a reconnu ... la correspondance avec le tram à quelques secondes près.'::text,'avoir failli rater'::text,'faillir rater'::text,'a failli rater'::text,'L''homme a reconnu avoir failli rater la correspondance avec le tram à quelques secondes près.'::text),
(398204,44245,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam tramvay aktarmasını sadece birkaç saniye farkla ... itiraf etti.'::text,'neredeyse kaçırdığını'::text,'neredeyse kaçırmayı'::text,'neredeyse kaçırdı'::text,'Adam tramvay aktarmasını sadece birkaç saniye farkla neredeyse kaçırdığını itiraf etti.'::text),
(398205,44245,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi beismerte, hogy csak néhány másodperccel ... a villamosátszállást.'::text,'majdnem lekéste'::text,'majdnem lekésni'::text,'majdnem lekéste'::text,'A férfi beismerte, hogy csak néhány másodperccel majdnem lekéste a villamosátszállást.'::text),
(398208,44246,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat die Fähre rechtzeitig erreicht, also ... der Umstieg in den Bus sehr schnell gewesen sein.'::text,'muss'::text,'hätte'::text,'kann nicht'::text,'Er hat die Fähre rechtzeitig erreicht, also muss der Umstieg in den Bus sehr schnell gewesen sein.'::text),
(398212,44246,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він устиг на пором вчасно, тож пересадка на автобус ... дуже швидкою.'::text,'мабуть, була'::text,'мала бути'::text,'не могла бути'::text,'Він устиг на пором вчасно, тож пересадка на автобус мабуть, була дуже швидкою.'::text),
(398211,44246,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Llegó al ferry a tiempo, así que el transbordo en autobús ... muy rápido.'::text,'debió de ser'::text,'debería haber sido'::text,'no pudo ser'::text,'Llegó al ferry a tiempo, así que el transbordo en autobús debió de ser muy rápido.'::text),
(398210,44246,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a eu le ferry à temps, donc la correspondance en bus ... très rapide.'::text,'a dû être'::text,'aurait dû être'::text,'n''a pas pu être'::text,'Il a eu le ferry à temps, donc la correspondance en bus a dû être très rapide.'::text),
(398213,44246,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feribota zamanında yetişti, yani otobüs aktarması çok hızlı ...'::text,'olmuş olmalı'::text,'olmalıydı'::text,'olmuş olamaz'::text,'Feribota zamanında yetişti, yani otobüs aktarması çok hızlı olmuş olmalı.'::text),
(398214,44246,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Időben elérte a kompot, szóval a buszos átszállás nagyon gyors ...'::text,'lehetett'::text,'kellett volna legyen'::text,'nem lehetett'::text,'Időben elérte a kompot, szóval a buszos átszállás nagyon gyors lehetett.'::text),
(398217,44247,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... einen ruhigeren Umstieg gesehen als diesen Sprint zur Fähre. Echt entspannend.'::text,'habe ich'::text,'ich habe'::text,'sah ich'::text,'Nie habe ich einen ruhigeren Umstieg gesehen als diesen Sprint zur Fähre. Echt entspannend.'::text),
(398221,44247,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... спокійнішої пересадки, ніж цей спринт до порома. Справжній релакс.'::text,'я не бачив'::text,'я не бачив'::text,'не бачив я'::text,'Ніколи я не бачив спокійнішої пересадки, ніж цей спринт до порома. Справжній релакс.'::text),
(398220,44247,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... un transbordo más tranquilo que este sprint al ferry. Superrelajante.'::text,'he visto'::text,'yo he visto'::text,'vi yo'::text,'Nunca he visto un transbordo más tranquilo que este sprint al ferry. Superrelajante.'::text),
(398219,44247,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... une correspondance plus calme que ce sprint vers le ferry. Vraiment relaxant.'::text,'n''ai-je vu'::text,'je n''ai vu'::text,'je vis'::text,'Jamais n''ai-je vu une correspondance plus calme que ce sprint vers le ferry. Vraiment relaxant.'::text),
(398222,44247,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu feribot deparından daha sakin bir aktarma asla ...; gerçekten rahatlatıcı.'::text,'görmedim'::text,'görmedim'::text,'gördüm'::text,'Bu feribot deparından daha sakin bir aktarma asla görmedim; gerçekten rahatlatıcı.'::text),
(398223,44247,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... nyugodtabb átszállást, mint ez a sprint a komphoz. Igazán pihentető.'::text,'nem láttam'::text,'nem láttam'::text,'láttam'::text,'Soha nem láttam nyugodtabb átszállást, mint ez a sprint a komphoz. Igazán pihentető.'::text),
(398226,44248,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat natürlich einen Gepäckträger dazu gebracht, seinen Rucksack ..., und zwar bei jedem Umstieg. Ein echter Profi.'::text,'zu tragen'::text,'tragen'::text,'tragend'::text,'Er hat natürlich einen Gepäckträger dazu gebracht, seinen Rucksack zu tragen, und zwar bei jedem Umstieg. Ein echter Profi.'::text),
(398230,44248,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно ж, він змусив носильника ... свій рюкзак на кожній пересадці. Справжній профі.'::text,'нести'::text,'нести'::text,'несучи'::text,'Звісно ж, він змусив носильника нести свій рюкзак на кожній пересадці. Справжній профі.'::text),
(398229,44248,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente consiguió que un mozo le ... la mochila en cada transbordo. Todo un profesional.'::text,'llevara'::text,'lleva'::text,'llevando'::text,'Claramente consiguió que un mozo le llevara la mochila en cada transbordo. Todo un profesional.'::text),
(398228,44248,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, il a fait ... son sac à dos par un porteur à chaque correspondance. Un vrai pro.'::text,'porter'::text,'de porter'::text,'portant'::text,'Évidemment, il a fait porter son sac à dos par un porteur à chaque correspondance. Un vrai pro.'::text),
(398231,44248,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki her aktarmada sırt çantasını bir hamala ...; gerçek bir profesyonel.'::text,'taşıttı'::text,'taşı'::text,'taşıyarak'::text,'Belli ki her aktarmada sırt çantasını bir hamala taşıttı; gerçek bir profesyonel.'::text),
(398232,44248,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván minden átszállásnál egy hordárral ... a hátizsákját. Igazi profi.'::text,'vitette'::text,'vinni'::text,'vive'::text,'Nyilván minden átszállásnál egy hordárral vitette a hátizsákját. Igazi profi.'::text),
(398235,44249,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, er ... früher von zu Hause losgefahren! Jeder einzelne Umstieg ist ein kompletter Albtraum!'::text,'wäre'::text,'ginge'::text,'würde'::text,'Er wünscht sich, er wäre früher von zu Hause losgefahren! Jeder einzelne Umstieg ist ein kompletter Albtraum!'::text),
(398239,44249,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він шкодує, що не ... з дому раніше! Кожна пересадка — суцільний кошмар!'::text,'вийшов'::text,'виходив'::text,'вийде'::text,'Він шкодує, що не вийшов з дому раніше! Кожна пересадка — суцільний кошмар!'::text),
(398238,44249,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él desearía ... de casa antes! ¡Cada transbordo es una auténtica pesadilla!'::text,'haber salido'::text,'salir'::text,'saldría'::text,'¡Él desearía haber salido de casa antes! ¡Cada transbordo es una auténtica pesadilla!'::text),
(398237,44249,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aurait aimé ... plus tôt de chez lui ! Chaque correspondance est un vrai cauchemar !'::text,'être parti'::text,'partir'::text,'partirait'::text,'Il aurait aimé être parti plus tôt de chez lui ! Chaque correspondance est un vrai cauchemar !'::text),
(398240,44249,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke evden daha erken ...! Her bir aktarma tam bir kâbus!'::text,'çıksaydı'::text,'çıksa'::text,'çıkacak'::text,'Keşke evden daha erken çıksaydı! Her bir aktarma tam bir kâbus!'::text),
(398241,44249,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak korábban ... el otthonról! Minden egyes átszállás maga a rémálom!'::text,'indult volna'::text,'indulna'::text,'elindulna'::text,'Bárcsak korábban indult volna el otthonról! Minden egyes átszállás maga a rémálom!'::text),
(398244,44250,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fähre, ... Gangway er hinaufgerannt ist, war sein letzter verzweifelter Umstieg!'::text,'deren'::text,'die'::text,'welche'::text,'Die Fähre, deren Gangway er hinaufgerannt ist, war sein letzter verzweifelter Umstieg!'::text),
(398248,44250,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пором, ... трапом він забіг нагору, був його останньою відчайдушною пересадкою!'::text,'чиїм'::text,'яким'::text,'котрим'::text,'Пором, чиїм трапом він забіг нагору, був його останньою відчайдушною пересадкою!'::text),
(398247,44250,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El ferry, por ... pasarela subió corriendo, fue su último transbordo desesperado!'::text,'cuya'::text,'la cual'::text,'que'::text,'¡El ferry, por cuya pasarela subió corriendo, fue su último transbordo desesperado!'::text),
(398246,44250,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le ferry, ... il a gravi la passerelle en courant, était sa dernière correspondance désespérée !'::text,'dont'::text,'lequel'::text,'que'::text,'Le ferry, dont il a gravi la passerelle en courant, était sa dernière correspondance désespérée !'::text),
(398249,44250,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koşarak ... çıktığı feribot, onun son çaresiz aktarmasıydı!'::text,'rampasından'::text,'rampadan'::text,'rampadan'::text,'Koşarak rampasından çıktığı feribot, onun son çaresiz aktarmasıydı!'::text),
(398250,44250,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A komp, ... a rámpáján felrohant, volt az utolsó kétségbeesett átszállása!'::text,'amelynek'::text,'amely'::text,'ami'::text,'A komp, amelynek a rámpáján felrohant, volt az utolsó kétségbeesett átszállása!'::text),
(400602,44512,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er ... gerade über den Kai, als das Boarding aufs Schiff losging, kein Witz.'::text,'rannte'::text,'rannte'::text,'ist gerannt'::text,'Yo, er rannte gerade über den Kai, als das Boarding aufs Schiff losging, kein Witz.'::text),
(400606,44512,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, він ... через причал, коли почалася посадка на судно, без брехні.'::text,'біг'::text,'пробіг'::text,'пробіг'::text,'Йо, він біг через причал, коли почалася посадка на судно, без брехні.'::text),
(400605,44512,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, él ... por el muelle cuando empezó el embarque del barco, en serio.'::text,'estaba corriendo'::text,'corrió'::text,'ha corrido'::text,'Oye, él estaba corriendo por el muelle cuando empezó el embarque del barco, en serio.'::text),
(400604,44512,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, il ... sur le quai quand l''embarquement du bateau a commencé, sans mentir.'::text,'courait'::text,'a couru'::text,'a couru'::text,'Yo, il courait sur le quai quand l''embarquement du bateau a commencé, sans mentir.'::text),
(400607,44512,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, gemiye biniş başladığında o rıhtımda ..., yemin ederim.'::text,'koşuyordu'::text,'koştu'::text,'koşmuş'::text,'Yo, gemiye biniş başladığında o rıhtımda koşuyordu, yemin ederim.'::text),
(400608,44512,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jó, ő éppen ... a rakparton, amikor elkezdődött a beszállás a hajóra, komolyan.'::text,'futott'::text,'átfutott'::text,'átfutott'::text,'Jó, ő éppen futott a rakparton, amikor elkezdődött a beszállás a hajóra, komolyan.'::text),
(400620,44514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Timeline: Um 8:15 Uhr ... er gerade den Kai, als das Boarding des Schiffs begann.'::text,'überquerte'::text,'überquerte'::text,'hat überquert'::text,'Timeline: Um 8:15 Uhr überquerte er gerade den Kai, als das Boarding des Schiffs begann.'::text),
(400624,44514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хронологія: о 8:15 він ... причал, коли почалася посадка на судно.'::text,'перетинав'::text,'перетнув'::text,'перетнув'::text,'Хронологія: о 8:15 він перетинав причал, коли почалася посадка на судно.'::text),
(400623,44514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cronología: a las 8:15 él ... el muelle cuando empezó el embarque del barco.'::text,'estaba cruzando'::text,'cruzó'::text,'ha cruzado'::text,'Cronología: a las 8:15 él estaba cruzando el muelle cuando empezó el embarque del barco.'::text),
(400622,44514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chronologie : à 8 h 15, il ... le quai quand l''embarquement du bateau a commencé.'::text,'traversait'::text,'a traversé'::text,'a traversé'::text,'Chronologie : à 8 h 15, il traversait le quai quand l''embarquement du bateau a commencé.'::text),
(400625,44514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zaman çizelgesi: 8.15''te gemiye biniş başladığında o rıhtımı ...'::text,'geçiyordu'::text,'geçti'::text,'geçmiş'::text,'Zaman çizelgesi: 8.15''te gemiye biniş başladığında o rıhtımı geçiyordu.'::text),
(400626,44514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Idővonal: 8:15-kor éppen ... a rakparton, amikor megkezdődött a beszállás a hajóra.'::text,'kelt át'::text,'átkelt'::text,'átkelt'::text,'Idővonal: 8:15-kor éppen kelt át a rakparton, amikor megkezdődött a beszállás a hajóra.'::text),
(400629,44515,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... schon die U-Bahn und eine Tram genommen, und jetzt steigt er aufs Schiff.'::text,'hat'::text,'hat'::text,'nahm'::text,'Er hat schon die U-Bahn und eine Tram genommen, und jetzt steigt er aufs Schiff.'::text),
(400633,44515,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уже ... метро і трамваєм, а тепер сідає на судно.'::text,'скористався'::text,'користується'::text,'скористався'::text,'Він уже скористався метро і трамваєм, а тепер сідає на судно.'::text),
(400632,44515,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ya ... el metro y un tranvía, y ahora está subiendo al barco.'::text,'ha cogido'::text,'ha estado cogiendo'::text,'cogió'::text,'Ya ha cogido el metro y un tranvía, y ahora está subiendo al barco.'::text),
(400631,44515,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... déjà le métro et un tram, et maintenant il monte à bord du bateau.'::text,'a pris'::text,'prend'::text,'prit'::text,'Il a pris déjà le métro et un tram, et maintenant il monte à bord du bateau.'::text),
(400634,44515,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiden metroya ve bir tramvaya ..., şimdi de gemiye biniyor.'::text,'bindi'::text,'biniyor'::text,'bindi'::text,'Şimdiden metroya ve bir tramvaya bindi, şimdi de gemiye biniyor.'::text),
(400635,44515,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már ... metróval és egy villamossal, és most száll fel a hajóra.'::text,'utazott'::text,'utazik'::text,'utazott'::text,'Már utazott metróval és egy villamossal, és most száll fel a hajóra.'::text),
(400638,44516,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er den Kai erreichte, ... die anderen Passagiere schon an Bord gegangen.'::text,'waren'::text,'gingen'::text,'sind'::text,'Als er den Kai erreichte, waren die anderen Passagiere schon an Bord gegangen.'::text),
(400642,44516,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він дістався причалу, інші пасажири вже ... на судно.'::text,'сіли'::text,'сіли'::text,'сіли'::text,'Поки він дістався причалу, інші пасажири вже сіли на судно.'::text),
(400641,44516,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó al muelle, los demás pasajeros ya ... al barco.'::text,'habían subido'::text,'subieron'::text,'han subido'::text,'Para cuando llegó al muelle, los demás pasajeros ya habían subido al barco.'::text),
(400640,44516,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''il arrive au quai, les autres passagers ... à bord du bateau.'::text,'étaient déjà montés'::text,'montèrent'::text,'sont déjà montés'::text,'Le temps qu''il arrive au quai, les autres passagers étaient déjà montés à bord du bateau.'::text),
(400643,44516,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O rıhtıma vardığında diğer yolcular gemiye çoktan ...'::text,'binmişti'::text,'bindi'::text,'binmiş'::text,'O rıhtıma vardığında diğer yolcular gemiye çoktan binmişti.'::text),
(400644,44516,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a rakpartra ért, a többi utas már ... a hajóra.'::text,'felszállt'::text,'felszállt'::text,'felszállt'::text,'Mire a rakpartra ért, a többi utas már felszállt a hajóra.'::text),
(400647,44517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Stunde nachdem er die U-Bahn verlassen hatte, war er ... auf einem kleinen weißen Schiff.'::text,'auf See'::text,'am Meer'::text,'in einem Meer'::text,'Eine Stunde nachdem er die U-Bahn verlassen hatte, war er auf See auf einem kleinen weißen Schiff.'::text),
(400651,44517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Через годину після виходу з метро він був ... на маленькому білому судні.'::text,'у морі'::text,'біля моря'::text,'в якомусь морі'::text,'Через годину після виходу з метро він був у морі на маленькому білому судні.'::text),
(400650,44517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una hora después de salir del metro, estaba ... en un pequeño barco blanco.'::text,'en el mar'::text,'junto al mar'::text,'en un mar'::text,'Una hora después de salir del metro, estaba en el mar en un pequeño barco blanco.'::text),
(400649,44517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une heure après avoir quitté le métro, il était ... sur un petit bateau blanc.'::text,'en mer'::text,'à la mer'::text,'dans une mer'::text,'Une heure après avoir quitté le métro, il était en mer sur un petit bateau blanc.'::text),
(400652,44517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Metrodan çıktıktan bir saat sonra küçük beyaz bir gemiyle ...'::text,'denizdeydi'::text,'deniz kenarındaydı'::text,'bir denizdeydi'::text,'Metrodan çıktıktan bir saat sonra küçük beyaz bir gemiyle denizdeydi.'::text),
(400653,44517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órával azután, hogy kiszállt a metróból, már ... volt egy kis fehér hajón.'::text,'a tengeren'::text,'a tengerparton'::text,'egy tengerben'::text,'Egy órával azután, hogy kiszállt a metróból, már a tengeren volt egy kis fehér hajón.'::text),
(400656,44518,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ging rechtzeitig an Bord ... der ganzen Menschenmassen auf dem U-Bahnsteig.'::text,'trotz'::text,'obwohl'::text,'wegen'::text,'Er ging rechtzeitig an Bord trotz der ganzen Menschenmassen auf dem U-Bahnsteig.'::text),
(400660,44518,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вчасно сів на судно ... всі натовпи на платформі метро.'::text,'попри'::text,'хоча'::text,'завдяки'::text,'Він вчасно сів на судно попри всі натовпи на платформі метро.'::text),
(400659,44518,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Subió al barco a tiempo ... todas las multitudes del andén del metro.'::text,'a pesar de'::text,'aunque'::text,'gracias a'::text,'Subió al barco a tiempo a pesar de todas las multitudes del andén del metro.'::text),
(400658,44518,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est monté à bord à temps ... toute la foule sur le quai du métro.'::text,'malgré'::text,'bien que'::text,'grâce à'::text,'Il est monté à bord à temps malgré toute la foule sur le quai du métro.'::text),
(400661,44518,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Metro peronundaki bütün kalabalığa ... gemiye zamanında bindi.'::text,'rağmen'::text,'rağmen'::text,'sayesinde'::text,'Metro peronundaki bütün kalabalığa rağmen gemiye zamanında bindi.'::text),
(400662,44518,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Időben felszállt a hajóra a metróperonon lévő tömeg ...'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Időben felszállt a hajóra a metróperonon lévő tömeg ellenére.'::text),
(400674,44520,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade die Gangway hoch, als würde dir das Schiff gehören, ganz ehrlich.'::text,'läufst'::text,'läufst'::text,'bist gelaufen'::text,'Du läufst gerade die Gangway hoch, als würde dir das Schiff gehören, ganz ehrlich.'::text),
(400678,44520,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти саме зараз ... трапом так, ніби це судно твоє, не брешу.'::text,'піднімаєшся'::text,'піднімаєшся'::text,'піднявся'::text,'Ти саме зараз піднімаєшся трапом так, ніби це судно твоє, не брешу.'::text),
(400677,44520,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... por la pasarela como si el barco fuera tuyo, no te voy a mentir.'::text,'estás subiendo'::text,'subes'::text,'has subido'::text,'Ahora mismo estás subiendo por la pasarela como si el barco fuera tuyo, no te voy a mentir.'::text),
(400676,44520,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Là, tu ... la passerelle comme si ce bateau t''appartenait, je vais pas mentir.'::text,'montes'::text,'montes'::text,'as monté'::text,'Là, tu montes la passerelle comme si ce bateau t''appartenait, je vais pas mentir.'::text),
(400679,44520,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda rampadan bu gemi seninmiş gibi ..., yalan yok.'::text,'çıkıyorsun'::text,'çıkarsın'::text,'çıktın'::text,'Şu anda rampadan bu gemi seninmiş gibi çıkıyorsun, yalan yok.'::text),
(400680,44520,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most úgy ... fel a rámpán, mintha tiéd lenne ez a hajó, nem hazudok.'::text,'sétálsz'::text,'sétálsz'::text,'sétáltál'::text,'Most úgy sétálsz fel a rámpán, mintha tiéd lenne ez a hajó, nem hazudok.'::text),
(400683,44521,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... diesen Trip schon monatelang geplant, bevor er zum Schiff sprintete. Makellose Planung.'::text,'hatte'::text,'plante'::text,'hat'::text,'Er hatte diesen Trip schon monatelang geplant, bevor er zum Schiff sprintete. Makellose Planung.'::text),
(400687,44521,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... цю поїздку місяцями, перш ніж кинувся бігом до судна. Бездоганне планування.'::text,'планував'::text,'планував'::text,'планує'::text,'Він планував цю поїздку місяцями, перш ніж кинувся бігом до судна. Бездоганне планування.'::text),
(400686,44521,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... este viaje durante meses antes de salir corriendo hacia el barco. Una planificación impecable.'::text,'había estado planeando'::text,'estaba planeando'::text,'ha estado planeando'::text,'Él había estado planeando este viaje durante meses antes de salir corriendo hacia el barco. Una planificación impecable.'::text),
(400685,44521,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... ce voyage depuis des mois avant de sprinter vers le bateau. Une organisation impeccable.'::text,'préparait'::text,'préparait'::text,'prépare'::text,'Il préparait ce voyage depuis des mois avant de sprinter vers le bateau. Une organisation impeccable.'::text),
(400688,44521,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gemiye doğru depar atmadan önce bu geziyi aylardır ...; kusursuz planlama.'::text,'planlıyordu'::text,'planlıyordu'::text,'planlıyor'::text,'Gemiye doğru depar atmadan önce bu geziyi aylardır planlıyordu; kusursuz planlama.'::text),
(400689,44521,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hónapokig ... ezt az utat, mielőtt a hajóhoz sprintelt. Hibátlan tervezés.'::text,'tervezte'::text,'tervezte'::text,'tervezi'::text,'Hónapokig tervezte ezt az utat, mielőtt a hajóhoz sprintelt. Hibátlan tervezés.'::text),
(400692,44522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis er an Bord geht, ... er drei Verkehrsmittel benutzt. Offensichtlich entspannend.'::text,'hat'::text,'wird'::text,'nutzt'::text,'Bis er an Bord geht, hat er drei Verkehrsmittel benutzt. Offensichtlich entspannend.'::text),
(400696,44522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він сяде на судно, він уже ... трьома видами транспорту. Очевидно, розслабляє.'::text,'скористається'::text,'користуватиметься'::text,'користується'::text,'Поки він сяде на судно, він уже скористається трьома видами транспорту. Очевидно, розслабляє.'::text),
(400695,44522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando suba al barco, ... tres medios de transporte. Relajante, obviamente.'::text,'habrá usado'::text,'usará'::text,'usa'::text,'Para cuando suba al barco, habrá usado tres medios de transporte. Relajante, obviamente.'::text),
(400694,44522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''il monte sur le bateau, il ... trois moyens de transport. Évidemment reposant.'::text,'aura pris'::text,'prendra'::text,'prend'::text,'D''ici à ce qu''il monte sur le bateau, il aura pris trois moyens de transport. Évidemment reposant.'::text),
(400697,44522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gemiye binene kadar üç çeşit ulaşım aracı ...; belli ki çok rahatlatıcı.'::text,'kullanmış olacak'::text,'kullanacak'::text,'kullanıyor'::text,'Gemiye binene kadar üç çeşit ulaşım aracı kullanmış olacak; belli ki çok rahatlatıcı.'::text),
(400698,44522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire felszáll a hajóra, ... három közlekedési eszközt. Nyilván pihentető.'::text,'már használt'::text,'használni fog'::text,'használ'::text,'Mire felszáll a hajóra, már használt három közlekedési eszközt. Nyilván pihentető.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
